/* =========================================================================
   PRNG (deterministisch pro Verein → gleicher Kader bei gleichem Namen/Saison)
   ========================================================================= */

function hashStr(str) {
  let h = 1779033703 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  return () => {
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    h ^= h >>> 16;
    return h >>> 0;
  };
}
function mulberry32(seedFn) {
  let a = seedFn();
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function rngFor(seedStr) {
  const seedFn = hashStr(seedStr);
  return mulberry32(seedFn);
}
function pick(rng, arr) { return arr[Math.floor(rng() * arr.length)]; }
function randInt(rng, min, max) { return Math.floor(rng() * (max - min + 1)) + min; }

// Sieben Unterwerte für Feldspieler (Skala 1-100) — werden NICHT separat generiert oder gespeichert,
// sondern deterministisch aus der bereits vorhandenen Gesamtstärke und Position jedes Spielers
// abgeleitet. So bleibt die gesamte bisherige Spielbalance (Matchsimulation, Marktwert, Gehalt usw.,
// die alle weiterhin nur "rating" verwenden) komplett unangetastet — die Unterwerte sind rein für die
// Detailansicht gedacht, geben aber ein stabiles, plausibles Profil pro Spieler.
const FELDSPIELER_ATTRIBUTE = ["technik", "passspiel", "offensive", "defensive", "physis", "tempo", "mentalitaet"];
// Gewichtung je Position — bestimmt, wie stark jeder Unterwert in die Gesamtstärke einfliesst UND wie
// stark er von der reinen Zufallsstreuung nach oben bzw. unten abweichen darf (starke Gewichtung =
// eher eine Stärke des Spielers, schwache Gewichtung = eher eine Schwäche).
const POSITION_ATTRIBUT_GEWICHTE = {
  IV: { technik: 0.6, passspiel: 0.9, offensive: 0.3, defensive: 2.2, physis: 1.8, tempo: 0.8, mentalitaet: 1.4 },
  AV: { technik: 0.9, passspiel: 1.1, offensive: 0.7, defensive: 1.7, physis: 1.2, tempo: 1.6, mentalitaet: 1.0 },
  ZM: { technik: 1.3, passspiel: 2.0, offensive: 0.8, defensive: 1.3, physis: 1.1, tempo: 0.7, mentalitaet: 1.6 },
  OM: { technik: 1.9, passspiel: 1.4, offensive: 1.8, defensive: 0.3, physis: 0.7, tempo: 1.3, mentalitaet: 1.0 },
  ST: { technik: 1.5, passspiel: 0.6, offensive: 2.3, defensive: 0.2, physis: 1.3, tempo: 1.7, mentalitaet: 0.7 }
};
const TORWART_ATTRIBUTE = ["reflexe", "fangen", "eins_gegen_eins", "strafraum", "spielaufbau", "physis", "mentalitaet"];
const TORWART_ATTRIBUT_GEWICHTE = { reflexe: 2.2, fangen: 2.0, eins_gegen_eins: 1.4, strafraum: 1.2, spielaufbau: 0.7, physis: 1.0, mentalitaet: 1.5 };

function berechneSpielerAttribute(spieler) {
  const istTorwart = spieler.pos === "TW";
  const attribute = istTorwart ? TORWART_ATTRIBUTE : FELDSPIELER_ATTRIBUTE;
  const gewichte = istTorwart ? TORWART_ATTRIBUT_GEWICHTE : (POSITION_ATTRIBUT_GEWICHTE[spieler.pos] || POSITION_ATTRIBUT_GEWICHTE.ZM);
  const gewichteWerte = Object.values(gewichte);
  const gewichtMittel = gewichteWerte.reduce((s, w) => s + w, 0) / gewichteWerte.length;

  const roh = {};
  attribute.forEach(attr => {
    const rng = rngFor(`spielerattribut|${spieler.id}|${attr}`);
    // Stärker gewichtete Attribute (= Stärken des Spielers) driften eher nach oben, schwächer
    // gewichtete (= Schwächen) eher nach unten — plus eine gewisse Zufallsstreuung pro Spieler.
    const drift = (gewichte[attr] - gewichtMittel) * 9;
    const streuung = (rng() - 0.5) * 16;
    roh[attr] = spieler.rating + drift + streuung;
  });

  // Korrektur: die gewichtete Durchschnittsstärke der Unterwerte muss der tatsächlichen
  // Gesamtstärke des Spielers entsprechen — sonst würde die Detailansicht einen anderen Wert
  // suggerieren als der Rest des Spiels tatsächlich verwendet.
  const gewichtetesRohMittel = attribute.reduce((s, attr) => s + roh[attr] * gewichte[attr], 0) / gewichteWerte.reduce((s, w) => s + w, 0);
  const korrektur = spieler.rating - gewichtetesRohMittel;

  const ergebnis = {};
  attribute.forEach(attr => {
    ergebnis[attr] = Math.max(1, Math.min(100, Math.round(roh[attr] + korrektur)));
  });
  return ergebnis;
}

// Passt ein BEREITS VORHANDENES Attribut-Set an ein neues Gesamtrating an — bewahrt dabei die
// individuelle Form/das Profil des Spielers (seine relativen Stärken/Schwächen bleiben erhalten),
// verschiebt aber alle Werte gemeinsam so, dass die gewichtete Durchschnittsstärke wieder exakt dem
// neuen Rating entspricht. Wird bei jeder Rating-Änderung (Entwicklung, Alterung) aufgerufen, damit
// die gespeicherten Attribute nie von der tatsächlichen Gesamtstärke abweichen.
function synchronisiereAttribute(spieler, neuesRating) {
  if (!spieler.attribute) return berechneSpielerAttribute({ ...spieler, rating: neuesRating });
  const istTorwart = spieler.pos === "TW";
  const attribute = istTorwart ? TORWART_ATTRIBUTE : FELDSPIELER_ATTRIBUTE;
  const gewichte = istTorwart ? TORWART_ATTRIBUT_GEWICHTE : (POSITION_ATTRIBUT_GEWICHTE[spieler.pos] || POSITION_ATTRIBUT_GEWICHTE.ZM);
  const gewichtSumme = Object.values(gewichte).reduce((s, w) => s + w, 0);
  const gewichtetesMittel = attribute.reduce((s, attr) => s + (spieler.attribute[attr] ?? neuesRating) * gewichte[attr], 0) / gewichtSumme;
  const korrektur = neuesRating - gewichtetesMittel;
  const ergebnis = {};
  attribute.forEach(attr => {
    ergebnis[attr] = Math.max(1, Math.min(100, Math.round((spieler.attribute[attr] ?? neuesRating) + korrektur)));
  });
  return ergebnis;
}

// Welches Attribut ein positionsspezifischer Co-Trainer beim Training gezielt fördert — genau die
// Verbindung, die einzelne Mitarbeiterrollen jetzt sinnvoller macht: ein Stürmertrainer verbessert
// gezielt die Offensive seiner Angreifer, ein Torwarttrainer die Reflexe seiner Torhüter usw.
const ATTRIBUT_SPEZIALIST_ZIEL = { TW: "reflexe", IV: "defensive", AV: "defensive", ZM: "passspiel", OM: "offensive", ST: "offensive" };
// Trainiert EIN Zielattribut gezielt hoch (deutlich stärkerer Sprung als die übrigen Werte) und
// synchronisiert danach das gesamte Set wieder gegen das neue Gesamtrating — der Effekt bleibt so
// spürbar konzentriert auf das trainierte Attribut, statt gleichmässig auf alle sieben verteilt.
function trainiereAttributGezielt(spieler, zielAttribut, neuesRating) {
  const basis = spieler.attribute || berechneSpielerAttribute(spieler);
  const angehoben = { ...basis, [zielAttribut]: Math.min(100, (basis[zielAttribut] ?? spieler.rating) + 4) };
  return synchronisiereAttribute({ ...spieler, attribute: angehoben }, neuesRating);
}

