function trainerPortraitFuer(trainerName) {
  if (!trainerName) return TRAINER_PORTRAITS[0];
  const rng = rngFor("portrait|" + trainerName);
  return TRAINER_PORTRAITS[Math.floor(rng() * TRAINER_PORTRAITS.length)];
}

// Kleines Easter Egg: wer sich bei Vor- und Nachname mit "1" / "1" registriert, wird als Hommage an
// den Startbildschirm des Spiels zu "Max Eberl" umbenannt (nur bei der Anzeige, intern bleiben
// vorname/nachname unverändert "1"/"1" gespeichert).
function managerAnzeigeName(vorname, nachname) {
  if (vorname === "1" && nachname === "1") return "Max Eberl";
  return `${vorname} ${nachname}`;
}

// Für Listen mehrerer Trainer gleichzeitig (z.B. die Kandidatenliste): garantiert, dass innerhalb
// DIESER Liste kein Porträt doppelt vergeben wird. Jeder Name bekommt zunächst seinen üblichen,
// deterministischen Wunschindex (siehe trainerPortraitFuer) — ist der schon vergeben, wird linear
// zum nächsten freien Index weitergerückt. Bei bis zu 60 Porträts und typischerweise 10 Kandidaten
// pro Liste bleibt genug Spielraum, ohne dass es je eng wird.
function trainerPortraitsFuerListe(namen) {
  const vergeben = new Set();
  const zuordnung = {};
  namen.forEach(name => {
    const rng = rngFor("portrait|" + name);
    let idx = Math.floor(rng() * TRAINER_PORTRAITS.length);
    let versuche = 0;
    while (vergeben.has(idx) && versuche < TRAINER_PORTRAITS.length) {
      idx = (idx + 1) % TRAINER_PORTRAITS.length;
      versuche++;
    }
    vergeben.add(idx);
    zuordnung[name] = TRAINER_PORTRAITS[idx];
  });
  return zuordnung;
}

