function spielerPortraitFuer(spielerId) {
  const rng = rngFor("spielerportrait|" + spielerId);
  return SPIELER_PORTRAITS[Math.floor(rng() * SPIELER_PORTRAITS.length)];
}
// Kollisionsfrei PRO TEAM — dieselbe lineare Sondierung wie bei den Trainern, aber hier über
// Spieler-IDs statt Namen, da IDs garantiert eindeutig sind (Namen könnten sich zufällig wiederholen).
function spielerPortraitsFuerTeam(spielerIds) {
  const vergeben = new Set();
  const zuordnung = {};
  spielerIds.forEach(id => {
    const rng = rngFor("spielerportrait|" + id);
    let idx = Math.floor(rng() * SPIELER_PORTRAITS.length);
    let versuche = 0;
    while (vergeben.has(idx) && versuche < SPIELER_PORTRAITS.length) {
      idx = (idx + 1) % SPIELER_PORTRAITS.length;
      versuche++;
    }
    vergeben.add(idx);
    zuordnung[id] = SPIELER_PORTRAITS[idx];
  });
  return zuordnung;
}

