const POSITIONEN = [
  { code: "TW", name: "Torwart", n: 3 },
  { code: "IV", name: "Innenverteidiger", n: 4 },
  { code: "AV", name: "Außenverteidiger", n: 3 },
  { code: "ZM", name: "Zentrales Mittelfeld", n: 4 },
  { code: "OM", name: "Offensives Mittelfeld", n: 3 },
  { code: "ST", name: "Stürmer", n: 3 }
];

// Der Verein existiert schon lange, bevor der Manager übernimmt — ein frisch generierter Kader darf
// also nicht komplett bei "0 Saisons Kontinuität" starten. Realistische, gestaffelte Vereinstreue:
// die meisten Spieler sind schon einige Saisons dabei, nur ein kleinerer Teil ist gerade erst
// gekommen. Junge Spieler können naturgemäss noch nicht lange dabei sein wie ein 19-Jähriger.
function zufallsVereinszugehoerigkeit(rng, season, alter) {
  const maxMoeglich = Math.max(0, alter - 17); // frühestens mit 17 im Profikader
  const wuerfel = rng();
  let jahre;
  if (wuerfel < 0.15) jahre = 5 + Math.floor(rng() * 4); // Vereinsurgestein: 5-8 Saisons
  else if (wuerfel < 0.40) jahre = 3 + Math.floor(rng() * 2); // 3-4 Saisons
  else if (wuerfel < 0.75) jahre = 1 + Math.floor(rng() * 2); // 1-2 Saisons
  else jahre = 0; // gerade erst gekommen
  return season - Math.min(jahre, maxMoeglich);
}

// Schätzt plausible Karrierewerte für die Saisons, die ein Spieler bereits VOR dem Kennenlernen im
// Verein verbracht hat (beimVereinSeitSaison liegt in der Vergangenheit) — sonst zeigt die
// Detailansicht bei einem "3 Jahre dabei"-Spieler fälschlich überall 0 an, obwohl er nachweislich
// schon mitgespielt haben muss. Positions- und stärkeabhängig, mit eigenem, stabilem Zufallssamen
// pro Spieler+Saison, damit der Wert bei jedem Rendern gleich bleibt.
const TORQUOTE_PRO_POSITION = { TW: 0.01, IV: 0.05, AV: 0.09, ZM: 0.13, OM: 0.30, ST: 0.55 };
const VORLAGENQUOTE_PRO_POSITION = { TW: 0.01, IV: 0.06, AV: 0.20, ZM: 0.16, OM: 0.24, ST: 0.13 };
function schaetzeVergangeneKarriere(spielerId, pos, rating, anzahlSaisons) {
  if (anzahlSaisons <= 0) return { tore: 0, vorlagen: 0, gelb: 0, rot: 0, spiele: 0 };
  const spielanteil = Math.min(0.95, 0.4 + rating / 200); // stärkere Spieler kommen öfter zum Einsatz
  const torQuote = (TORQUOTE_PRO_POSITION[pos] ?? 0.1) * (rating / 70);
  const vorlagenQuote = (VORLAGENQUOTE_PRO_POSITION[pos] ?? 0.1) * (rating / 70);
  let gesamt = { tore: 0, vorlagen: 0, gelb: 0, rot: 0, spiele: 0 };
  for (let s = 0; s < anzahlSaisons; s++) {
    const rng = rngFor(`vergangenekarriere|${spielerId}|${s}`);
    const spiele = Math.round(34 * spielanteil * (0.8 + rng() * 0.35));
    gesamt.spiele += spiele;
    gesamt.tore += Math.round(spiele * torQuote * (0.7 + rng() * 0.6));
    gesamt.vorlagen += Math.round(spiele * vorlagenQuote * (0.7 + rng() * 0.6));
    gesamt.gelb += Math.round(2 + rng() * 5);
    gesamt.rot += rng() < 0.15 ? 1 : 0;
  }
  return gesamt;
}

function generateSquad(teamName, baseRating, season, divisionId, salt = 0) {
  const rng = rngFor(`${teamName}|squad|s${season}|${salt}`);
  const spieler = [];
  let rueckennummer = 1;
  POSITIONEN.forEach((pos) => {
    for (let i = 0; i < pos.n; i++) {
      const vorname = pick(rng, VORNAMEN);
      const nachname = pick(rng, NACHNAMEN);
      const variance = randInt(rng, -9, 9);
      const alter = randInt(rng, 18, 35);
      const altersBonus = alter < 22 ? -3 : alter > 31 ? -2 : 2;
      const rating = Math.max(28, Math.min(99, baseRating + variance + altersBonus));
      const beimVereinSeitSaison = zufallsVereinszugehoerigkeit(rng, season, alter);
      const jahreBeiVerein = season - beimVereinSeitSaison;
      const vergangeneKarriere = schaetzeVergangeneKarriere(`${teamName}-${rueckennummer}`, pos.code, rating, jahreBeiVerein);
      // Für die "gesamte Karriere" (unabhängig vom aktuellen Verein) fehlt sonst die Zeit VOR dem
      // Vereinseintritt — ein 30-Jähriger, der erst mit 26 kam, hat vorher zwangsläufig schon Jahre
      // bei anderen Vereinen gespielt (Profidebut realistisch ab ca. 17 Jahren angenommen). Eigener
      // Zufallssamen-Zusatz ("|vorher"), damit diese Schätzung nicht zufällig mit der Vereinszeit
      // übereinstimmt.
      const alterBeiEintritt = alter - jahreBeiVerein;
      const jahreVorDemVerein = Math.max(0, alterBeiEintritt - 17);
      const vorherigeKarriere = schaetzeVergangeneKarriere(`${teamName}-${rueckennummer}|vorher`, pos.code, rating, jahreVorDemVerein);
      spieler.push({
        id: `${teamName}-${rueckennummer}`,
        name: `${vorname} ${nachname}`,
        pos: pos.code,
        posName: pos.name,
        alter,
        nr: rueckennummer,
        rating,
        nationalitaet: pick(rng, NATIONALITAETEN_POOL),
        vertragBisSaison: season + randInt(rng, 1, 5) - 1,
        persoenlichkeit: zufallsPersoenlichkeit(rng),
        zufriedenheit: 70,
        beimVereinSeitSaison,
        gehalt: berechneSpielerlohn({ rating, alter }, divisionId || "OL"),
        attribute: berechneSpielerAttribute({ id: `${teamName}-${rueckennummer}`, pos: pos.code, rating }),
        // Schnappschuss der Attribute zu Saisonbeginn — die Differenz zum aktuellen Wert ergibt die
        // "jährliche Entwicklung" (z.B. "Technik +1") im Spielerdatenblatt. Wird bei jedem
        // Saisonübergang neu gesetzt (siehe Saisonübergangs-Stellen).
        attributeSaisonStart: berechneSpielerAttribute({ id: `${teamName}-${rueckennummer}`, pos: pos.code, rating }),
        tore: 0, vorlagen: 0, gelb: 0, rot: 0, elfmeterTore: 0, eckballTore: 0, freistossTore: 0, verletzungenSaison: 0, spiele: 0, saisonEntwicklungen: 0, form: 60, verletzung: null,
        // Rückwirkend geschätzte Werte für die Saisons vor dem Kennenlernen — sowohl "seit er im
        // Verein ist" (karriereX) als auch "gesamte Karriere" (gesamtkarriereX) starten damit, statt
        // bei einem "3 Jahre dabei"-Spieler fälschlich überall 0 zu zeigen.
        karriereTore: vergangeneKarriere.tore, karriereVorlagen: vergangeneKarriere.vorlagen, karriereGelb: vergangeneKarriere.gelb, karriereRot: vergangeneKarriere.rot, karriereSpiele: vergangeneKarriere.spiele,
        gesamtkarriereTore: vergangeneKarriere.tore + vorherigeKarriere.tore, gesamtkarriereVorlagen: vergangeneKarriere.vorlagen + vorherigeKarriere.vorlagen, gesamtkarriereGelb: vergangeneKarriere.gelb + vorherigeKarriere.gelb, gesamtkarriereRot: vergangeneKarriere.rot + vorherigeKarriere.rot, gesamtkarriereSpiele: vergangeneKarriere.spiele + vorherigeKarriere.spiele
      });
      rueckennummer++;
    }
  });
  return spieler.sort((a, b) => POSITIONEN.findIndex(p => p.code === a.pos) - POSITIONEN.findIndex(p => p.code === b.pos));
}

function teamStrength(squad) {
  const sorted = [...squad].sort((a, b) => b.rating - a.rating);
  const besten = sorted.slice(0, 16);
  return besten.reduce((s, p) => s + p.rating, 0) / besten.length;
}

