/* =========================================================================
   STADION & MATCHDAY-EINNAHMEN (Ticketing + Fanartikel bei Heimspielen)
   ========================================================================= */

// Ticketpreise um ca. 40% gesenkt gegenüber dem ursprünglichen Wert (Faktor 0.6) — zusammen mit dem
// neuen KOMMERZ_FAKTOR der Hauptgrund, warum insbesondere untere Ligen bisher deutlich zu hohe
// Gewinne einfuhren (Ticketing allein konnte den gesamten Ertrag dominieren).
const STADION_BEREICHE = {
  BL: { kap: [28000, 75000], ticket: [13, 25], fan: [4, 9] },
  L2: { kap: [10000, 32000], ticket: [8, 14], fan: [2, 6] },
  L3: { kap: [4000, 18000], ticket: [5, 10], fan: [1, 4] },
  RL: { kap: [2400, 13000], ticket: [4, 8], fan: [1, 4] },
  OL: { kap: [800, 8000], ticket: [2, 5], fan: [1, 3] }
};

const STADION_KATEGORIEN = ["stehplaetze", "sitzplaetze", "logen"];
const STADION_KATEGORIE_NAMEN = { stehplaetze: "Stehplätze", sitzplaetze: "Sitzplätze", logen: "Logen" };
// Baukosten pro Platz/Loge bei Erweiterung; Rückbau kostet nur einen Bruchteil (Abriss statt Neubau)
const STADION_BAUKOSTEN_PRO_PLATZ = { stehplaetze: 350, sitzplaetze: 900, logen: 18000 };
// Neue Mechanik: das Stadion gehört dem Verein zu Karrierebeginn noch nicht — es wird von der Kommune
// gemietet, wie bei vielen echten deutschen Amateur- und Zweitliga-Vereinen üblich. Bewusst grosszügig
// kalibriert (ca. 1-2% des Wiederbeschaffungswerts pro Jahr) — die Miete soll spürbar, aber nicht
// erdrückend sein, gerade weil bereits viele andere Kosten in dieser Session verschärft wurden.
const STADION_MIETE_PRO_PLATZ_JAHR = { OL: 5, L3: 6, RL: 6, L2: 7, BL: 8 };
// Kaufpreis = Wiederbeschaffungswert (Bausubstanz zu heutigen Preisen) plus Aufschlag für Grundstück,
// Erschliessung und Prestige — ein Kauf ist bewusst ein langfristiges Ziel über mehrere Saisons, kein
// Ein-Saison-Vorhaben, aber jederzeit möglich, sobald genug Kapital da ist.
const STADION_KAUF_MARKUP = 1.8;
function stadionMieteProJahr(stadion, managerDivId) {
  const satz = STADION_MIETE_PRO_PLATZ_JAHR[managerDivId] || STADION_MIETE_PRO_PLATZ_JAHR.OL;
  const gesamtKap = STADION_KATEGORIEN.reduce((s, kat) => s + (stadion?.[kat]?.kapazitaet || 0), 0);
  return Math.round(gesamtKap * satz);
}
function stadionKaufpreis(stadion) {
  const bausubstanz = STADION_KATEGORIEN.reduce((s, kat) => s + (stadion?.[kat]?.kapazitaet || 0) * STADION_BAUKOSTEN_PRO_PLATZ[kat], 0);
  return Math.round((bausubstanz * STADION_KAUF_MARKUP) / 10000) * 10000;
}
// Einmaliger Grundausbau-Zuschlag, nur fällig beim allerersten Logenbau (0 -> mehr als 0 Kapazität) —
// deckt die eigentliche Infrastruktur ab (eigene Zufahrt/Eingänge, Küche/Catering-Anschluss, Technik,
// Sicherheitskonzept), die für einen Logenbereich überhaupt erst nötig ist, unabhängig von der Anzahl
// Logen selbst. Bewusst deutlich spürbar, liga-abhängig gestaffelt.
const STADION_LOGEN_GRUNDAUSBAU_KOSTEN = { BL: 1500000, L2: 600000, L3: 250000, RL: 165000, OL: 80000 };

/* =========================================================================
   JUGENDAKADEMIE — permanente, ausbaubare Infrastruktur (wie La Masia / Bayern
   Campus), analog zum Stadion-Umbau: kostet Geld und Bauzeit, bleibt danach
   dauerhaft bestehen und wirkt zusätzlich zur jährlichen Investition.
   ========================================================================= */

const AKADEMIE_MAX_LEVEL = 5;
// Liga-abhängige Obergrenze: ein viertklassiger Verein hat schlicht nicht die Strukturen (Lizenzen,
// Partnerschaften, Standort) für ein Weltklasse-NLZ, egal wie viel Geld zur Verfügung steht — nur die
// Bundesliga kann die volle Stufe 5 erreichen.
const AKADEMIE_MAX_LEVEL_PRO_LIGA = { BL: 5, L2: 4, L3: 3, RL: 2, OL: 2 };
// Mindestwartezeit nach Fertigstellung einer Stufe, bevor die nächste überhaupt begonnen werden darf —
// eine volle Saison "Einlebezeit", unabhängig vom verfügbaren Budget.
const AKADEMIE_ABKLINGZEIT_TAGE = 300;
// Ab dieser Ausbaustufe braucht es zusätzlich einen Mindest-Markenwert — ein Spitzen-NLZ erfordert
// Ausstrahlung und Partnerschaften, nicht nur Kapital.
const AKADEMIE_MARKENWERT_AB_STUFE = 4;
const AKADEMIE_MARKENWERT_MINDESTWERT = 60;
// Ausbaukosten pro Liga für den Sprung auf die jeweilige Stufe (Index 0 = Stufe 1, ...)
// Kalibriert an echten NLZ-Baukosten (ein modernes Nachwuchsleistungszentrum kostet in der Anschaffung
// oft rund 30 Mio. €) UND an der realen Bauzeit — ein Weltklasse-Standort wie La Masia oder der
// Bayern Campus entsteht über viele Jahre, nicht innerhalb von 1-2 Saisons.
// Deutlich erhöht (grob das 4-5-fache der ursprünglichen Werte): die Bauzeit allein (bis zu 750 Tage
// für die letzte Stufe) machte den Ausbau schon zeitlich langsam, aber die Kosten waren selbst in der
// Oberliga aus dem blossen Startkapital heraus bezahlbar — ein Vollausbau soll ein echtes, spürbares
// Mehrjahresprojekt sein, finanziell wie zeitlich.
const AKADEMIE_KOSTEN_PRO_LEVEL = {
  BL: [2000000, 5500000, 13000000, 28000000, 60000000],
  L2: [600000, 1700000, 4000000, 9000000, 20000000],
  L3: [220000, 600000, 1400000, 3200000, 7000000],
  RL: [127500, 345000, 810000, 1850000, 4050000],
  OL: [35000, 90000, 220000, 500000, 1100000]
};
// Bauzeit in Tagen pro Stufe — bewusst lang: alle 5 Stufen zusammen ergeben über 5 Jahre reine
// Bauzeit, ein Vollausbau ist damit ein echtes Mehrjahresprojekt statt in 1-2 Saisons erledigt.
const AKADEMIE_BAUTAGE_PRO_LEVEL = [120, 220, 380, 550, 750];

function akademieKosten(divisionId, zielLevel) {
  const kosten = AKADEMIE_KOSTEN_PRO_LEVEL[divisionId] || AKADEMIE_KOSTEN_PRO_LEVEL.OL;
  return kosten[zielLevel - 1] || 0;
}

// Ab Stufe 3 besteht eine kleine, aber echte Chance auf ein Ausnahmetalent ("Wunderkind") deutlich
// über dem sonst üblichen Niveau — wie bei den grossen Nachwuchsschmieden der Realität.
function akademieWunderkindChance(level) {
  if (level < 3) return 0;
  return 0.04 + (level - 3) * 0.04; // Stufe 3: 4%, Stufe 4: 8%, Stufe 5: 12%
}

function stadionUmbauMultiplikator(delta, aktuelleKapazitaet) {
  if (delta <= 0) return 0.3;
  const relativeErweiterung = delta / Math.max(aktuelleKapazitaet, 200);
  const rabatt = Math.min(0.3, relativeErweiterung * 0.4);
  return 1 - rabatt;
}
// Grobe Bautage pro 100 Plätze/Logen Differenz
// Kalibriert an echten Bauzeiten: eine grosse Stehplatz-Erweiterung ist in wenigen Monaten machbar,
// eine neue Sitzplatz-Tribüne dauert real oft 6-12 Monate, Logen sind aufwendig im Ausbau, aber meist
// nur kleine Stückzahlen betroffen. Vorher lag eine 5'000er-Erweiterung bei absurden 2.5-5.5 Jahren.
const STADION_BAUTAGE_PRO_100 = { stehplaetze: 4, sitzplaetze: 7, logen: 18 };

// Vermieter-Ausbau: solange das Stadion noch NICHT im Eigentum des Vereins ist, kann die Kommune
// (der Eigentümer) von sich aus erweitern — entweder direkt nach einem Aufstieg, oder wenn der Verein
// bereits seit geraumer Zeit (10+ Spieltage) nachhaltig erfolgreich ist (Top 3). Die Kommune trägt die
// Kosten selbst (keine Belastung des Vereinsbudgets), verlangt danach aber automatisch mehr Miete, da
// stadionMieteProJahr sich ohnehin immer an der AKTUELLEN Gesamtkapazität bemisst. Die Bauzeit ist
// bewusst deutlich länger als bei einem selbst finanzierten Umbau (siehe VERMIETER_MINDEST_BAUTAGE) —
// die Entscheidung fällt ja auch erst NACH dem Aufstieg, das Stadion darf also nicht einfach schon
// zum 1. Spieltag der neuen Saison grösser sein.
const VERMIETER_AUSBAU_FAKTOR = 0.12; // +12% Gesamtkapazität pro Vermieter-Ausbau
// Deutlich längere Mindestbauzeit als bei einem selbst beauftragten Umbau (21 Tage): die Kommune
// entscheidet sich ERST nach dem Aufstieg bzw. nach anhaltendem Erfolg dafür — Planung, Genehmigungen
// und Ausschreibung brauchen realistischerweise Monate, bevor überhaupt gebaut wird. Ohne diese
// höhere Untergrenze wäre eine kleine Erweiterung (z.B. +200 Plätze) rein rechnerisch schon nach 3
// Wochen fertig — praktisch schon zum 1. Spieltag der neuen Saison, was den Sinn des Aufstiegs-Anlasses
// konterkarieren würde.
const VERMIETER_MINDEST_BAUTAGE = 150;
function vermieterErwaegtAusbau(stadion, datum, saison, grund) {
  if (!stadion || stadion.eigentum) return null;
  if (stadion.letzterVermieterAusbauSaison === saison) return null; // höchstens 1x pro Saison
  if ((stadion.umbauten || []).length > 0) return null; // nicht parallel zu einem laufenden Umbau
  const kategorienMitPlatz = STADION_KATEGORIEN.filter(k => k !== "logen" && (stadion[k]?.kapazitaet || 0) > 0);
  if (!kategorienMitPlatz.length) return null;
  const gesamtAlt = kategorienMitPlatz.reduce((s, k) => s + stadion[k].kapazitaet, 0);
  const gesamtKapazitaetAktuell = STADION_KATEGORIEN.reduce((s, k) => s + (stadion[k]?.kapazitaet || 0), 0);
  const zuwachsGesamt = Math.max(200, Math.round(gesamtAlt * VERMIETER_AUSBAU_FAKTOR / 50) * 50);
  if (gesamtKapazitaetAktuell + zuwachsGesamt > STADION_MAX_KAPAZITAET) return null; // schon an der Obergrenze
  const neueUmbauten = kategorienMitPlatz.map(k => {
    const anteil = stadion[k].kapazitaet / gesamtAlt;
    const delta = Math.round(zuwachsGesamt * anteil / 10) * 10;
    const alteKapazitaet = stadion[k].kapazitaet;
    const neueKapazitaet = alteKapazitaet + delta;
    const bautage = Math.max(VERMIETER_MINDEST_BAUTAGE, Math.round((delta / 100) * STADION_BAUTAGE_PRO_100[k]));
    return { kategorie: k, alteKapazitaet, neueKapazitaet, fertigAmDatum: addTage(datum, bautage), kosten: 0, bautage, vomVermieter: true };
  }).filter(u => u.neueKapazitaet > u.alteKapazitaet);
  if (!neueUmbauten.length) return null;
  return {
    stadion: {
      ...stadion,
      umbauten: [...(stadion.umbauten || []), ...neueUmbauten],
      letzterVermieterAusbauSaison: saison,
      letzterVermieterAusbauGrund: grund
    },
    // Für die sofortige Ankündigungs-Mitteilung (im Unterschied zu letzterStadionUmbau, der erst bei
    // FERTIGSTELLUNG erscheint) — der Manager soll den Grund direkt bei der Entscheidung erfahren.
    ankuendigung: { grund, erweiterungen: neueUmbauten, fertigAmDatum: neueUmbauten.reduce((max, u) => u.fertigAmDatum > max ? u.fertigAmDatum : max, neueUmbauten[0].fertigAmDatum) }
  };
}

// Reale Stadionkapazitäten (Saison 2026/27, recherchiert) für alle Vereine der Bundesliga,
// 2. Bundesliga und 3. Liga im Spiel. Für die Oberliga (rund 70 kleine Amateurvereine) sind
// systematisch verlässliche Kapazitätsdaten praktisch nicht auffindbar — dort bleibt die
// bestehende, realistisch kalibrierte Zufallsgenerierung (STADION_BEREICHE.OL) bestehen.
const REALE_STADIONKAPAZITAETEN = {
  // Bundesliga
  "FC Bayern München": 75024, "Borussia Dortmund": 81365, "RB Leipzig": 47069,
  "VfB Stuttgart": 60058, "Bayer 04 Leverkusen": 30210, "Eintracht Frankfurt": 59500,
  "TSG Hoffenheim": 30150, "SC Freiburg": 34700, "1. FSV Mainz 05": 33305,
  "Borussia Mönchengladbach": 54057, "Hamburger SV": 57000, "1. FC Köln": 49698,
  "FC Augsburg": 30660, "1. FC Union Berlin": 22012, "Werder Bremen": 42100,
  "FC Schalke 04": 62271, "SV Elversberg": 10000, "SC Paderborn 07": 15000,
  // 2. Bundesliga
  "Hertha BSC": 74475, "Arminia Bielefeld": 26750, "VfL Bochum": 27599,
  "Eintracht Braunschweig": 23325, "Energie Cottbus": 22528, "SV Darmstadt 98": 17810,
  "Dynamo Dresden": 32249, "SpVgg Greuther Fürth": 16626, "Hannover 96": 49000,
  "1. FC Heidenheim 1846": 15000, "1. FC Kaiserslautern": 49327, "Holstein Kiel": 15034,
  "VfL Osnabrück": 16098, "Karlsruher SC": 33180, "1. FC Magdeburg": 30098,
  "1. FC Nürnberg": 50000, "FC St. Pauli": 29546, "VfL Wolfsburg": 30000,
  // 3. Liga
  "SC Preußen Münster": 12974, "Fortuna Düsseldorf": 54600, "Rot-Weiss Essen": 19962,
  "MSV Duisburg": 31418, "Hansa Rostock": 29000, "SC Verl": 5207,
  "Alemannia Aachen": 32960, "SV Wehen Wiesbaden": 15295, "SV Waldhof Mannheim": 25721,
  "Viktoria Köln": 8343, "FC Ingolstadt 04": 15200, "SSV Jahn Regensburg": 15224,
  "VfB Stuttgart II": 11410, "1. FC Saarbrücken": 16003, "TSG Hoffenheim II": 6350,
  "TSV Havelse": 5001, "SV Meppen": 13241, "SG Sonnenhof Großaspach": 10000,
  "SC Fortuna Köln": 11748, "Würzburger Kickers": 13090
};

function generateStadion(teamName, tierId) {
  const rng = rngFor(`${teamName}|stadion|${tierId}`);
  const b = STADION_BEREICHE[tierId] || STADION_BEREICHE.OL;
  const gesamtKap = REALE_STADIONKAPAZITAETEN[teamName] || randInt(rng, b.kap[0], b.kap[1]);
  const basisPreis = randInt(rng, b.ticket[0], b.ticket[1]);
  const stehKap = Math.round(gesamtKap * 0.55);
  // Logen sind zu Karrierebeginn noch kein Bestandteil des Stadions — sie müssen erst über einen
  // (relativ teuren) Grundausbau errichtet werden, siehe STADION_LOGEN_GRUNDAUSBAU_KOSTEN. Die
  // Kapazität, die sonst auf Logen entfallen wäre, fliesst stattdessen in normale Sitzplätze.
  const logenKap = 0;
  const sitzKap = Math.max(0, gesamtKap - stehKap - logenKap);
  return {
    kapazitaet: stehKap + sitzKap + logenKap,
    stehplaetze: { kapazitaet: stehKap, ticketpreis: basisPreis },
    sitzplaetze: { kapazitaet: sitzKap, ticketpreis: Math.round(basisPreis * 1.8) },
    // Kalibriert an realen Logenpreisen: Eintracht Frankfurt/HSV verlangen real ca. 620-640 € pro Spiel
    // und Sitzplatz — mit dem alten Faktor 8 lagen wir bei nur 176-336 €, deutlich zu tief. Faktor 20
    // trifft die reale Grössenordnung viel besser (ca. 440-840 € pro Spiel in der Bundesliga).
    logen: { kapazitaet: logenKap, ticketpreis: Math.round(basisPreis * 20) },
    umbauten: [],
    saisonkarten: { stehplaetze: 0, sitzplaetze: 0, logen: 0 },
    saisonkartenVerkaufOffen: true,
    eigenerName: null,
    namensSponsor: null,
    namensSponsorAngebot: null,
    rekordZuschauer: 0,
    rekordZuschauerInfo: null,
    zuschauerHistorie: [],
    // Neu: das Stadion wird zu Karrierebeginn von der Kommune gemietet, nicht besessen — siehe
    // stadionMieteProJahr/stadionKaufpreis. naechsteMietzahlung wird erst beim Karrierestart (bzw.
    // Saisonübergang) mit einem echten Datum befüllt.
    eigentum: false,
    naechsteMietzahlung: null,
    flutlicht: false,
    rasenheizung: false,
    videowuerfel: false,
    photovoltaik: false,
    fanzone: false,
    museum: false,
    trainingszentrum: false,
    soundsystem: false,
    digitaleInfrastruktur: false,
    familienbereich: false,
    sicherheitssystem: false,
    infrastrukturZustand: initialerInfrastrukturZustand(),
    personalstufe: "standard",
    naechstePersonalLohnzahlung: null,
    platzzustand: 75,
    personalstufe: "standard",
    naechstePersonalLohnzahlung: null
  };
}

/* =========================================================================
   STADION-ATTRAKTIVITÄT: Namensrechte, Stadionrekord, Infrastruktur-Ausbau.
   Namensrechte kalibriert an echten Bundesliga-Deals (300 Tsd - 6 Mio €/Jahr,
   ca. 80% der BL-Vereine haben einen Namenssponsor).
   ========================================================================= */

const STADION_NAME_BEREICH = { BL: [300000, 6000000], L2: [80000, 500000], L3: [15000, 100000], RL: [7750, 52500], OL: [500, 5000] };
const STADION_NAME_FIRMEN = [
  "Rheingold Versicherung", "Nordlicht Energie", "Alpina Bank", "Kristall Bräu", "Voltano Automobile",
  "Silberkorn Immobilien", "Falkenstein Logistik", "Blauband Telekom", "Granithaus Bau", "Sonnenfeld Solar",
  "Eichenberg Möbel", "Wellenreich Getränke", "Steinadler Sport", "Kupferberg Metall", "Lindenhof Handel"
];

function generiereNamensSponsorAngebot(managerDivId, ausschlussFirmen, salt) {
  const rng = rngFor(`stadionname|${managerDivId}|${salt}`);
  const bereich = STADION_NAME_BEREICH[managerDivId] || STADION_NAME_BEREICH.OL;
  const pool = STADION_NAME_FIRMEN.filter(f => !ausschlussFirmen.includes(f));
  if (!pool.length) return null;
  const firma = pool[Math.floor(rng() * pool.length)];
  const betrag = Math.round((bereich[0] + rng() * (bereich[1] - bereich[0])) / 100) * 100;
  return { firma, betragProJahr: betrag };
}

function stadionAnzeigeName(stadion, teamName) {
  if (stadion.namensSponsor) return `${stadion.namensSponsor.firma}-Arena`;
  if (stadion.eigenerName) return stadion.eigenerName;
  return `${teamName}-Stadion`;
}

// Konzerte & Events: nur möglich, wenn das Stadion dem Verein gehört — bei einem gemieteten Stadion
// entscheidet real die Kommune als Eigentümerin über die Vermarktung an spielfreien Tagen, nicht der
// Mieter-Verein (dieselbe Logik wie bei Erweiterungen, Logen-Ausbau und Namensrechte-Sponsoring).
// Grössere, bekanntere Vereine ziehen grössere Acts und damit mehr Geld an. Der Rasen leidet spürbar
// unter Bühnenaufbau und Publikumsmassen — echter Tradeoff statt geschenktem Geld.
const EVENT_VERANSTALTER = [
  "Nordlicht Festival GmbH", "Arena Concerts", "Bühnenwerk Live-Entertainment", "Klangfeld Booking",
  "Metropol Events", "Sommerbühne Tourneen", "Live-Nation-Partner Regional", "Festplatz Konzerte AG",
  "Grossveranstaltungen Süd", "Openair Kollektiv"
];
function generiereEventAngebot(kapazitaet, markenwert, salt) {
  const rng = rngFor(`event|${kapazitaet}|${salt}`);
  const proPlatz = 8 + rng() * 20; // 8-28 € pro Platz
  const markenwertFaktor = 0.6 + (markenwert / 100) * 0.8; // 0.6x bis 1.4x
  const betrag = Math.round((kapazitaet * proPlatz * markenwertFaktor) / 1000) * 1000;
  const platzSchaden = Math.round(8 + rng() * 12); // 8-20% Rasenschaden durch Bühnenaufbau & Publikum
  const veranstalter = EVENT_VERANSTALTER[Math.floor(rng() * EVENT_VERANSTALTER.length)];
  return { veranstalter, betrag, platzSchaden };
}

// Akademie-Namensrechte: analog zum Stadionnamen, aber erst ab einer gewissen Ausbaustufe für Sponsoren
// interessant (eine kleine Nachwuchsabteilung hat keine Aussenwirkung) — Betrag skaliert zusätzlich mit
// dem Level, eine Weltklasse-Akademie ist deutlich wertvoller als eine frisch begonnene.
const AKADEMIE_NAME_BEREICH = { BL: [150000, 3000000], L2: [40000, 250000], L3: [8000, 60000], RL: [4150, 31500], OL: [300, 3000] };
function generiereAkademieNamensSponsorAngebot(managerDivId, akademieLevel, ausschlussFirmen, salt) {
  const rng = rngFor(`akademiename|${managerDivId}|${salt}`);
  const bereich = AKADEMIE_NAME_BEREICH[managerDivId] || AKADEMIE_NAME_BEREICH.OL;
  const levelFaktor = 0.5 + akademieLevel * 0.3; // Stufe 1: 0.8x, Stufe 5: 2.0x
  const pool = STADION_NAME_FIRMEN.filter(f => !ausschlussFirmen.includes(f));
  if (!pool.length) return null;
  const firma = pool[Math.floor(rng() * pool.length)];
  const betrag = Math.round((bereich[0] + rng() * (bereich[1] - bereich[0])) * levelFaktor / 100) * 100;
  return { firma, betragProJahr: betrag };
}
function akademieAnzeigeName(akademie, teamName) {
  if (akademie?.namensSponsor) return `${akademie.namensSponsor.firma}-Nachwuchsleistungszentrum`;
  return `${teamName}-Jugendakademie`;
}

// Verwaltungs- und Verkaufspersonal: Ticketverkäufer, Kassierer, Imbiss-/Fanshop-Personal,
// Reinigungskräfte und Bürokräfte — proportional zur Vereinsgrösse, inklusive Sozialabgaben als
// fixer Aufschlag. Keine einzelne anstellbare Person wie die übrigen Mitarbeiter, sondern eine
// wählbare Personalstufe, die laufend Geld kostet und sich auf Umsatz und Fanzufriedenheit auswirkt.
const PERSONALSTUFEN = {
  sparsam: { name: "Sparsam", kostenFaktor: 0.6, umsatzMultiplikator: 0.85, zufriedenheitsBonus: -8, beschreibung: "Minimalbesetzung — niedrigste Kosten, aber Warteschlangen und spürbar entgangener Umsatz." },
  standard: { name: "Standard", kostenFaktor: 1.0, umsatzMultiplikator: 1.0, zufriedenheitsBonus: 0, beschreibung: "Ausgewogene Besetzung — solider Service zu fairen Kosten." },
  grosszuegig: { name: "Grosszügig", kostenFaktor: 1.5, umsatzMultiplikator: 1.1, zufriedenheitsBonus: 3, beschreibung: "Vollbesetzung — bester Service, volle Kapazität nutzbar, aber deutlich teurer." }
};
// Basiskosten pro Sitzplatz und Jahr (inkl. Sozialabgaben) bei Personalstufe "Standard" — skaliert
// automatisch mit der Stadiongrösse, ganz ohne einzelne Anstellung.
const PERSONALKOSTEN_PRO_PLATZ_PRO_JAHR = 12;

// Infrastruktur-Zusatzinvestitionen — Kosten skalieren mit der Liga
const STADION_INFRASTRUKTUR = {
  flutlicht: { name: "Flutlicht", kostenReferenz: 800000, beschreibung: "Ermöglicht Abendspiele bei jedem Wetter und wirkt sich positiv auf die Fanzufriedenheit aus." },
  rasenheizung: { name: "Rasenheizung", kostenReferenz: 1200000, beschreibung: "Schützt den Rasen im Winter — senkt das Verletzungsrisiko bei kaltem, hartem Boden spürbar." },
  videowuerfel: { name: "Videowürfel", kostenReferenz: 2500000, beschreibung: "Zeigt Wiederholungen und Choreografien — steigert Fanzufriedenheit und Fanartikel-Umsatz am Spieltag." },
  photovoltaik: { name: "Photovoltaikanlage", kostenReferenz: 1800000, beschreibung: "Überschüssiger Solarstrom wird ins Netz eingespeist — spart laufende Betriebskosten, jede Woche, unabhängig vom Spieltag." },
  fanzone: { name: "Public-Viewing-Fanzone", kostenReferenz: 1500000, beschreibung: "Fängt Fans auf, die bei ausverkauftem Stadion kein Ticket mehr bekommen haben — zusätzliche Einnahmen genau dann, wenn die Nachfrage das Angebot übersteigt." },
  museum: { name: "Vereinsmuseum", kostenReferenz: 900000, beschreibung: "Kleine, aber verlässliche Einnahmequelle durch Führungen und Eintritte — läuft auch an spielfreien Tagen weiter." },
  trainingszentrum: { name: "Trainingszentrum mit Reha-Abteilung", kostenReferenz: 3200000, beschreibung: "Eigene Physiotherapie direkt am Stadion — senkt das Verletzungsrisiko zusätzlich, wirkt sich aber besonders stark aus, wenn zusätzlich ein Vereinsarzt angestellt ist." },
  soundsystem: { name: "Stadion-Soundsystem", kostenReferenz: 600000, beschreibung: "Bessere Akustik und Stimmung — verstärkt den Heimvorteil, besonders bei hoher Auslastung." },
  digitaleInfrastruktur: { name: "Digitale Stadion-Infrastruktur", kostenReferenz: 1100000, beschreibung: "Bargeldloses Bestellen per App spart Wartezeit an den Ständen — steigert den Umsatz bei Fanshop, Verkaufsständen und Vereinsheim." },
  familienbereich: { name: "Familien- & Kids-Bereich", kostenReferenz: 700000, beschreibung: "Macht den Stadionbesuch für Familien attraktiver — hebt die Grundauslastung leicht an, unabhängig von Tabellenplatz oder Gegner." },
  sicherheitssystem: { name: "Modernes Sicherheits- & Zutrittssystem", kostenReferenz: 1400000, beschreibung: "Schnellerer, sichererer Einlass — verbessert die Fanzufriedenheit, besonders wenn die Ticketpreise ohnehin schon hoch sind." }
};

// Kosten skalieren jetzt mit der TATSÄCHLICHEN Stadionkapazität — nicht mehr mit der Liga-Zugehörigkeit.
// Das schliesst einen sonst möglichen Exploit: früher liess sich in der Oberliga viel Geld verdienen
// und die komplette Infrastruktur zum günstigen OL-Fixpreis ausbauen, bevor man aufsteigt und die
// Vorteile einer Bundesliga-Ausstattung geniesst. Ein grösseres Stadion braucht deutlich mehr als nur
// proportional mehr Technik (grössere Bildschirme, mehr Flutlichtmasten, längere Kabelwege) — daher
// quadratische statt lineare Skalierung, kalibriert an einem typischen Bundesliga-Stadion (50'000 Plätze).
const INFRASTRUKTUR_REFERENZ_KAPAZITAET = 50000;
function infrastrukturKosten(typ, kapazitaet) {
  const basis = STADION_INFRASTRUKTUR[typ];
  const faktor = Math.pow(Math.max(kapazitaet || 0, 1000) / INFRASTRUKTUR_REFERENZ_KAPAZITAET, 2);
  return Math.max(1500, Math.round(basis.kostenReferenz * faktor / 500) * 500);
}

// Gekaufte Infrastruktur altert wie das Trainingsmaterial — ohne Pflege lässt die Wirkung mit der Zeit
// spürbar nach. Ein Unterhaltschef verlangsamt die Abnutzung (bis zu 50% bei Top-Rating), genau wie
// der Materialwart beim Trainingsmaterial. Verlust in Prozentpunkten pro Saison (34 Spieltage).
const INFRASTRUKTUR_ABNUTZUNG_PRO_SAISON = 16;
const INFRASTRUKTUR_ABNUTZUNG_PRO_SPIELTAG = INFRASTRUKTUR_ABNUTZUNG_PRO_SAISON / 34;

function initialerInfrastrukturZustand() {
  const zustand = {};
  Object.keys(STADION_INFRASTRUKTUR).forEach(typ => { zustand[typ] = 100; });
  return zustand;
}

// Reparaturkosten: ein Bruchteil des ursprünglichen Baupreises — eine komplette Erneuerung wäre
// unverhältnismässig teuer, eine Wartung/Instandsetzung ist deutlich günstiger.
function infrastrukturReparaturKosten(typ, kapazitaet) {
  const basis = infrastrukturKosten(typ, kapazitaet);
  return Math.max(500, Math.round(basis * 0.18 / 500) * 500);
}

// Rasensanierung: anders als bei der übrigen Infrastruktur hängen die Kosten hier zusätzlich vom
// Schadensausmass ab — eine Auffrischung von 90% auf 100% kostet nur einen Bruchteil einer
// Komplettsanierung von 10% auf 100%. Skaliert wie die übrige Infrastruktur quadratisch mit der
// Stadionkapazität (siehe infrastrukturKosten), damit ein Bundesliga-Rasen nicht zum Oberliga-Preis
// saniert werden kann.
const RASEN_SANIERUNG_REFERENZ_KOSTEN = 45000;
function rasenSanierungKosten(kapazitaet, platzzustand) {
  const faktor = Math.pow(Math.max(kapazitaet || 0, 1000) / INFRASTRUKTUR_REFERENZ_KAPAZITAET, 2);
  const fehlend = Math.max(0, 100 - (platzzustand ?? 75));
  return Math.max(500, Math.round(RASEN_SANIERUNG_REFERENZ_KOSTEN * faktor * (fehlend / 100) / 100) * 100);
}

// Wirkungsgrad einer Infrastruktur-Investition: 0 wenn nicht gekauft, sonst der aktuelle Zustand
// (0-100%) als Faktor — eine verwahrloste Anlage wirkt sich kaum noch aus, eine top gepflegte voll.
function infrastrukturWirkung(stadion, typ) {
  if (!stadion?.[typ]) return 0;
  const zustand = stadion.infrastrukturZustand?.[typ] ?? 100;
  return zustand / 100;
}

// Saisonkarten-Preis: Rabatt gegenüber Einzelkauf aller Heimspiele derselben Kategorie
const SAISONKARTEN_RABATT = 0.80;
function saisonkartenPreis(ticketpreis, heimspieleAnzahl) {
  return Math.round(ticketpreis * heimspieleAnzahl * SAISONKARTEN_RABATT);
}

// Nicht jeder will/kann eine Saisonkarte kaufen — die Nachfrage hängt vom Prestige des Vereins ab:
// höhere Liga und ein guter letztjähriger Tabellenplatz erhöhen den maximal verkaufbaren Anteil je Kategorie.
const SAISONKARTEN_BASISNACHFRAGE = { BL: 0.55, L2: 0.45, L3: 0.35, RL: 0.3, OL: 0.25 };
function maxSaisonkartenAnteil(managerDivId, saisonHistorie) {
  const basis = SAISONKARTEN_BASISNACHFRAGE[managerDivId] ?? 0.25;
  if (!saisonHistorie || !saisonHistorie.length) return basis;
  const letzte = [...saisonHistorie].sort((a, b) => b.saison - a.saison)[0];
  const platzAnteil = 1 - (letzte.platz - 1) / Math.max(1, letzte.anzahlTeams - 1); // 1 = Meister, 0 = Letzter
  return Math.min(0.85, basis + platzAnteil * 0.3);
}

// Wendet fertiggestellte Umbauten an (Datum erreicht) — gibt aktualisiertes Stadion + evtl. Meldungen zurück
function verarbeiteStadionUmbauten(stadion, datum) {
  if (!stadion.umbauten || !stadion.umbauten.length) return { stadion, fertiggestellt: [] };
  const nochOffen = [];
  const fertiggestellt = [];
  let neuesStadion = { ...stadion };
  stadion.umbauten.forEach(u => {
    if (datum >= u.fertigAmDatum) {
      neuesStadion = { ...neuesStadion, [u.kategorie]: { ...neuesStadion[u.kategorie], kapazitaet: u.neueKapazitaet } };
      fertiggestellt.push(u);
    } else {
      nochOffen.push(u);
    }
  });
  neuesStadion.umbauten = nochOffen;
  neuesStadion.kapazitaet = STADION_KATEGORIEN.reduce((s, k) => s + neuesStadion[k].kapazitaet, 0);
  return { stadion: neuesStadion, fertiggestellt };
}

// Akademie-Ausbau fertigstellen, sobald das Bau-Datum erreicht ist — analog zum Stadion-Umbau
function verarbeiteAkademieUmbau(akademie, datum) {
  if (!akademie.umbau || datum < akademie.umbau.fertigAmDatum) return { akademie, fertig: null };
  const neuLevel = akademie.umbau.zielLevel;
  // Zeitpunkt der Fertigstellung merken — Grundlage für die Mindestwartezeit (Abklingzeit) vor dem
  // nächsten Ausbau, unabhängig davon, wie schnell wieder genug Budget zusammenkommt.
  return { akademie: { ...akademie, level: neuLevel, umbau: null, letzteFertigstellungAmDatum: datum }, fertig: neuLevel };
}

/* =========================================================================
   RIVALITÄTEN / DERBYS — echte, bekannte deutsche Fussball-Rivalitäten
   ========================================================================= */

const RIVALITAETEN = [
  ["FC Bayern München", "Borussia Dortmund"],           // Der Klassiker
  ["FC Schalke 04", "Borussia Dortmund"],                // Revierderby
  ["VfL Bochum", "FC Schalke 04"],                       // Ruhrgebiet
  ["1. FC Köln", "Borussia Mönchengladbach"],            // Rheinisches Derby
  ["Hamburger SV", "Werder Bremen"],                     // Nordderby
  ["Hamburger SV", "FC St. Pauli"],                      // Hamburger Stadtderby
  ["1. FC Union Berlin", "Hertha BSC"],                  // Berliner Stadtderby
  ["Eintracht Frankfurt", "1. FSV Mainz 05"],            // Rhein-Main-Derby
  ["VfB Stuttgart", "Karlsruher SC"],                    // Baden-Württemberg-Derby
  ["1. FC Nürnberg", "SpVgg Greuther Fürth"],            // Fränkisches Derby
  ["Hannover 96", "Eintracht Braunschweig"],             // Niedersachsen-Derby
  ["Dynamo Dresden", "1. FC Magdeburg"],                 // Ost-Derby
  ["1. FC Kaiserslautern", "1. FC Saarbrücken"],         // Pfalz-Saar-Derby
  ["MSV Duisburg", "Rot-Weiss Essen"],                   // Ruhrgebiets-Klassiker
  ["Viktoria Köln", "SC Fortuna Köln"],                  // Kölner Lokalderby
  ["SV Waldhof Mannheim", "Karlsruher SC"],              // Badisches Derby
  ["Hansa Rostock", "Energie Cottbus"],                  // Ost-Rivalität
  ["Alemannia Aachen", "Fortuna Düsseldorf"]             // Rheinland-Derby
];

function istDerby(teamA, teamB) {
  return RIVALITAETEN.some(([a, b]) => (a === teamA && b === teamB) || (a === teamB && b === teamA));
}

// Attraktivität eines Gegners für die Zuschauerzahl: ein deutlich stärkerer/prominenterer Gegner
// Photovoltaikanlage (überschüssiger Solarstrom) und Vereinsmuseum (Führungen/Eintritte) laufen
// unabhängig vom Spieltag weiter — echte passive Einnahmequellen, jede Kalenderwoche, ob Spieltag
// oder nicht. Skaliert leicht mit der Stadiongrösse (grössere Anlage = mehr Solarfläche/Besucher).
function berechnePassiveWocheneinnahmen(stadion) {
  if (!stadion) return 0;
  const groessenFaktor = Math.max(0.5, Math.min(3, (stadion.kapazitaet || 10000) / 25000));
  let summe = 0;
  summe += 180 * groessenFaktor * infrastrukturWirkung(stadion, "photovoltaik");
  summe += 240 * groessenFaktor * infrastrukturWirkung(stadion, "museum");
  return Math.round(summe);
}

// Laufende Betriebskosten, die jede Woche anfallen — unabhängig vom Spieltag, da diese Posten
// durchlaufen: Versicherungen (Haftpflicht, Veranstalter-, Fahrzeug-, Inhaltsversicherung),
// Büromaterial (Geschäftsstelle, Kontoführung), Fahrzeuge (Mannschaftsbus, Unterhalt/Sprit),
// Dresseinkäufe (laufende Trainingsausrüstung, nicht die einmalige Erstausstattung) und
// Waschservice (Trikot-/Wäschereinigung nach jedem Training und Spiel). In der Realität eigene,
// aber jeweils kleine Posten — zu einer gemeinsamen Position gebündelt, wie es auch reale Vereine
// in ihrer laufenden Buchhaltung meist handhaben. Skaliert mit Liga-Niveau und Kadergrösse.
const BETRIEBSKOSTEN_PRO_WOCHE = { BL: 20000, L2: 5000, L3: 1200, RL: 725, OL: 250 };
function berechneBetriebskosten(managerDivId, kaderGroesse) {
  const basis = BETRIEBSKOSTEN_PRO_WOCHE[managerDivId] || BETRIEBSKOSTEN_PRO_WOCHE.OL;
  const kaderFaktor = Math.max(0.7, Math.min(1.4, (kaderGroesse || 22) / 22));
  return Math.round(basis * kaderFaktor);
}

// zieht mehr Fans an — unabhängig von der eigenen Tabellensituation. Klassiker: ein kleiner Verein
// zieht gegen einen grossen Namen im Pokal oder Testspiel volle Ränge.
function berechneGegnerAttraktivitaet(gegnerStaerke, eigeneStaerke) {
  const diff = gegnerStaerke - eigeneStaerke;
  return Math.max(0, Math.min(0.25, diff / 200));
}

function berechneHeimspielEinnahmen(stadion, tabellenplatz, anzahlTeams, derby = false, gegnerAttraktivitaet = 0) {
  // Derbys ziehen unabhängig von der Tabellensituation deutlich mehr Zuschauer — echte Fussballkultur.
  // Ein attraktiver Gegner (starkes Team, grosser Name, internationale Bühne) zieht zusätzlich mehr
  // Zuschauer, unabhängig von der eigenen Tabellenposition — genau wie im echten Fussball.
  // Flutlicht (Abendspiele bei jedem Wetter) und Familienbereich heben die Grundauslastung leicht an,
  // unabhängig von Tabellenplatz oder Gegner — echte Infrastruktur-Investitionen zahlen sich so aus.
  const infraFormBonus = infrastrukturWirkung(stadion, "flutlicht") * 0.02 + infrastrukturWirkung(stadion, "familienbereich") * 0.03;
  const formFaktor = Math.min(1, (0.5 + 0.4 * (1 - (tabellenplatz - 1) / Math.max(1, anzahlTeams - 1))) + (derby ? 0.25 : 0) + gegnerAttraktivitaet + infraFormBonus);
  let zuschauer = 0;
  let ticketeinnahmen = 0;
  const kategorien = {};
  STADION_KATEGORIEN.forEach(kat => {
    const k = stadion[kat] || { kapazitaet: 0, ticketpreis: 0 };
    const saisonkartenKat = Math.min(k.kapazitaet, (stadion.saisonkarten && stadion.saisonkarten[kat]) || 0);
    const restKapazitaet = k.kapazitaet - saisonkartenKat;
    // Logen-Kunden sind treuer (meist Jahresverträge) — Auslastung schwankt dort deutlich weniger
    const rauschbreite = kat === "logen" ? 0.05 : 0.12;
    const mindestauslastung = kat === "logen" ? 0.55 : 0.25;
    const zufall = (Math.random() - 0.5) * rauschbreite;
    const auslastungKat = Math.max(mindestauslastung, Math.min(1, formFaktor + zufall));
    // Saisonkarten-Inhaber sind immer da (schon bezahlt), Rest der Plätze wird einzeln verkauft
    const tagesticketsKat = Math.round(restKapazitaet * auslastungKat);
    const zuschauerKat = saisonkartenKat + tagesticketsKat;
    zuschauer += zuschauerKat;
    ticketeinnahmen += tagesticketsKat * k.ticketpreis; // Saisonkarten wurden bereits im Voraus bezahlt
    kategorien[kat] = { zuschauer: zuschauerKat, saisonkarten: saisonkartenKat, tagestickets: tagesticketsKat, auslastung: k.kapazitaet > 0 ? zuschauerKat / k.kapazitaet : 0, einnahmen: tagesticketsKat * k.ticketpreis };
  });
  const gesamtKapazitaet = STADION_KATEGORIEN.reduce((s, k) => s + (stadion[k]?.kapazitaet || 0), 0);
  const auslastung = gesamtKapazitaet > 0 ? zuschauer / gesamtKapazitaet : 0;
  // Public-Viewing-Fanzone: fängt Fans auf, die bei (nahezu) ausverkauftem Stadion kein Ticket mehr
  // bekommen haben — lohnt sich nur dann wirklich, wenn die Nachfrage das Angebot übersteigt.
  let fanzoneEinnahmen = 0;
  if (stadion.fanzone && auslastung >= 0.9) {
    const ueberschussFans = Math.round(gesamtKapazitaet * (auslastung - 0.9) * 1.5);
    fanzoneEinnahmen = ueberschussFans * 6.5 * infrastrukturWirkung(stadion, "fanzone");
  }
  return { typ: "heim", zuschauer, auslastung, kategorien, ticketeinnahmen, fanzoneEinnahmen, fanartikeleinnahmen: 0, gesamt: ticketeinnahmen + fanzoneEinnahmen };
}

// Reisekosten je Liga-Ebene (Bus/Flug, Übernachtung fürs Team) — variiert von Spiel zu Spiel
// Reale Reisekosten sind deutlich höher als reine Busfahrten: bereits bei innerdeutschen Spielen
// fliegen Bundesliga-Vereine regelmässig per Chartermaschine (rund 25'000 € allein für den Flug,
// dazu Hotel, Flughafentransfers und eine Leerfahrt des Mannschaftsbusses) — nur bei kurzen Distanzen
// bleibt es beim günstigeren Bus. Die Spanne bildet diese Mischung aus Bus- und Charterflug-Reisen ab.
const REISEKOSTEN_BEREICHE = { BL: [5000, 42000], L2: [2500, 12000], L3: [1000, 4000], RL: [575, 2400], OL: [150, 800] };

function berechneAuswaertsspielKosten(tierId, eigenesStadion, tabellenplatz, anzahlTeams, derby = false) {
  const bereich = REISEKOSTEN_BEREICHE[tierId] || REISEKOSTEN_BEREICHE.OL;
  const kosten = Math.round((bereich[0] + Math.random() * (bereich[1] - bereich[0])) / 50) * 50;

  const formFaktor = 0.025 + 0.025 * (1 - (tabellenplatz - 1) / Math.max(1, anzahlTeams - 1));
  const zufall = (Math.random() - 0.5) * 0.01;
  // Zu einem Derby reisen deutlich mehr eigene Fans mit als zu einem gewöhnlichen Auswärtsspiel
  const reisendenAnteil = Math.max(0.01, formFaktor + zufall) * (derby ? 2.2 : 1);
  const reisendeFans = Math.max(20, Math.round(eigenesStadion.kapazitaet * reisendenAnteil));

  return { typ: "auswaerts", kosten, reisendeFans, fanartikeleinnahmen: 0, gesamt: -kosten };
}

// Europapokal-Auswärtsspiele: deutlich weitere Distanzen als innerhalb Deutschlands (Flüge quer durch
// Europa statt Bus/Bahn) — Faktor 3 gegenüber den normalen Liga-Reisekosten der jeweiligen Liga-Stufe.
// Auch weniger eigene Fans reisen mit (Kosten, Distanz, Wochentag) als bei einem nahen Liga-Auswärtsspiel.
function berechneEuroAuswaertsspielKosten(tierId, eigenesStadion, tabellenplatz, anzahlTeams) {
  const bereich = REISEKOSTEN_BEREICHE[tierId] || REISEKOSTEN_BEREICHE.OL;
  // Die Basis-Spanne enthält jetzt bereits realistische Charterflug-Kosten für innerdeutsche Spiele —
  // international kommen längere Flugzeiten (teurere Maschine) und eine praktisch immer nötige
  // Hotelübernachtung (bei Kurztrips im Inland oft nicht nötig) hinzu. Faktor 1.8 statt vorher 3,
  // da die alte, deutlich niedrigere Basis noch von reinen Busfahrten ausging.
  const kosten = Math.round((bereich[0] + Math.random() * (bereich[1] - bereich[0])) * 1.8 / 50) * 50;

  const formFaktor = 0.025 + 0.025 * (1 - (tabellenplatz - 1) / Math.max(1, anzahlTeams - 1));
  const zufall = (Math.random() - 0.5) * 0.01;
  const reisendenAnteil = Math.max(0.006, (formFaktor + zufall) * 0.5);
  const reisendeFans = Math.max(20, Math.round(eigenesStadion.kapazitaet * reisendenAnteil));

  return { typ: "auswaerts", kosten, reisendeFans, fanartikeleinnahmen: 0, gesamt: -kosten };
}

/* =========================================================================
   FANSHOP — Manager kauft Fanartikel ein, legt Verkaufspreise fest;
   ohne Bestand kein Verkauf mehr während des Spiels
   ========================================================================= */

const FANARTIKEL_TYPEN = [
  { id: "shirts", name: "Trikots", einkaufspreis: 25, nachfrageAnteil: 0.035 },
  { id: "caps", name: "Caps", einkaufspreis: 8, nachfrageAnteil: 0.03 },
  { id: "schals", name: "Schals", einkaufspreis: 6, nachfrageAnteil: 0.045 },
  { id: "wimpel", name: "Wimpel", einkaufspreis: 3, nachfrageAnteil: 0.02 },
  { id: "tassen", name: "Tassen", einkaufspreis: 3.5, nachfrageAnteil: 0.025 },
  { id: "fahnen", name: "Fahnen", einkaufspreis: 5, nachfrageAnteil: 0.018 },
  { id: "schluesselanhaenger", name: "Schlüsselanhänger", einkaufspreis: 1.5, nachfrageAnteil: 0.03 },
  { id: "hoodies", name: "Hoodies", einkaufspreis: 22, nachfrageAnteil: 0.015 },
  { id: "handtuecher", name: "Schwenktücher", einkaufspreis: 4, nachfrageAnteil: 0.022 },
  { id: "poster", name: "Poster", einkaufspreis: 2, nachfrageAnteil: 0.015 }
];

function initialerFanshop() {
  const fanshop = {};
  FANARTIKEL_TYPEN.forEach(t => {
    fanshop[t.id] = { bestand: 0, verkaufspreis: Math.round(t.einkaufspreis * 2), ziel: 0 };
  });
  return fanshop;
}

// Automatisches Nachbestellen bis zum eingestellten Ziel-Bestand (Schieberegler in Fanshop-, Imbiss-
// und Vereinsheim-Tab) — läuft nach jedem Verkauf automatisch, damit nie manuell nachgekauft werden
// muss. Die Kosten fliessen ganz normal ins jeweilige Budget der aufrufenden Stelle ein.
function nachbestellen(shopState, artikelTypen) {
  let kosten = 0;
  const neuerState = {};
  artikelTypen.forEach(t => {
    const item = shopState[t.id] || { bestand: 0, verkaufspreis: t.einkaufspreis * 2 };
    const ziel = item.ziel || 0;
    const nachkauf = Math.max(0, ziel - item.bestand);
    kosten += nachkauf * t.einkaufspreis;
    neuerState[t.id] = nachkauf > 0 ? { ...item, bestand: item.bestand + nachkauf } : item;
  });
  return { neuerState, kosten };
}

// Maximal sinnvoller Ziel-Bestand pro Artikel für den Schieberegler: mindestens das 3-fache der
// theoretisch höchstmöglichen Nachfrage an einem einzigen Heimspieltag (inkl. Zufallsspitze und
// eventuellem Star-Transfer-Trikotansturm) — so wird eine hohe Einstellung selbst im Extremfall nie zu
// knapp. Skaliert automatisch mit der Stadionkapazität: ein Stadionausbau erhöht so auch den möglichen
// Ziel-Bestand proportional, wie gewünscht.
function berechneMaxZielbestand(kapazitaet, nachfrageAnteil, tierId, zusatzMultiplikator = 1) {
  const kommerzFaktor = KOMMERZ_FAKTOR[tierId] || KOMMERZ_FAKTOR.OL;
  const theoretischesMax = kapazitaet * nachfrageAnteil * kommerzFaktor * 1.3 * zusatzMultiplikator;
  return Math.max(20, Math.ceil((theoretischesMax * 3) / 10) * 10);
}


// Nachfrage-Multiplikator für Trikots, wenn kürzlich ein echter Star verpflichtet wurde (siehe
// sternTransferBoost in verarbeiteTransfer) — bewusst NUR auf "shirts" angewendet, nicht auf die
// übrigen Fanartikel, da Fans gezielt das Trikot des neuen Stars kaufen wollen, nicht mehr Schals
// oder Tassen im Allgemeinen.
function verkaufeFanartikel(fanshop, anzahlFans, auswaertsFaktor = 1, infraMultiplikator = 1, tierId = "OL", trikotBoost = 1) {
  const kommerzFaktor = KOMMERZ_FAKTOR[tierId] || KOMMERZ_FAKTOR.OL;
  let einnahmen = 0;
  const neuerFanshop = {};
  const verkaeufe = {};
  FANARTIKEL_TYPEN.forEach(t => {
    const item = fanshop[t.id] || { bestand: 0, verkaufspreis: t.einkaufspreis * 2 };
    const boost = t.id === "shirts" ? trikotBoost : 1;
    const nachfrage = Math.round(anzahlFans * t.nachfrageAnteil * kommerzFaktor * auswaertsFaktor * infraMultiplikator * boost * (0.7 + Math.random() * 0.6));
    const verkauft = Math.max(0, Math.min(nachfrage, item.bestand));
    einnahmen += verkauft * item.verkaufspreis;
    neuerFanshop[t.id] = {
      ...item,
      bestand: item.bestand - verkauft,
      verkauftSaison: (item.verkauftSaison || 0) + verkauft,
      umsatzSaison: (item.umsatzSaison || 0) + verkauft * item.verkaufspreis
    };
    verkaeufe[t.id] = verkauft;
  });
  return { neuerFanshop, einnahmen, verkaeufe };
}

// Essens-/Getränkestände — klassisches Stadionangebot, ortsgebunden (nur bei Heimspielen verkaufbar,
// im Gegensatz zum Fanshop gibt es hier keinen Auswärts-Verkauf). Deutlich höhere Nachfrageanteile als
// beim Fanshop, da die meisten Zuschauer während eines Spiels mindestens etwas essen oder trinken.
// Liga-abhängiger Kommerz-Faktor: skaliert die Verkaufsmenge bei Fanartikel, Imbiss und Vereinsheim
// (und damit proportional auch die Einkaufskosten, das Margenverhältnis bleibt also unverändert).
// Ohne diesen Faktor gab pro Kopf ein Oberliga-Fan exakt gleich viel für Bratwurst, Bier und
// Merchandise aus wie ein Bundesliga-Fan — unrealistisch, und Hauptgrund für deutlich zu hohe
// Gewinne in den unteren Ligen (Verkaufsstände nahezu auf Augenhöhe mit dem Ticketing selbst).
const KOMMERZ_FAKTOR = { BL: 1.0, L2: 0.65, L3: 0.35, RL: 0.25, OL: 0.15 };

const IMBISS_ARTIKEL_TYPEN = [
  { id: "siegesburger", name: "Siegesburger", einkaufspreis: 1.6, nachfrageAnteil: 0.18 },
  { id: "bratwurst", name: "Bratwurst", einkaufspreis: 1.2, nachfrageAnteil: 0.35 },
  { id: "currywurst", name: "Currywurst", einkaufspreis: 1.4, nachfrageAnteil: 0.2 },
  { id: "pommes", name: "Pommes Frites", einkaufspreis: 0.9, nachfrageAnteil: 0.25 },
  { id: "brezel", name: "Brezel", einkaufspreis: 0.5, nachfrageAnteil: 0.2 },
  { id: "bier", name: "Bier", einkaufspreis: 0.6, nachfrageAnteil: 0.55 },
  { id: "alkoholfrei", name: "Alkoholfreies Bier", einkaufspreis: 0.55, nachfrageAnteil: 0.15 },
  { id: "cola", name: "Cola/Limonade", einkaufspreis: 0.45, nachfrageAnteil: 0.3 },
  { id: "wasser", name: "Wasser", einkaufspreis: 0.3, nachfrageAnteil: 0.18 },
  { id: "kaffee", name: "Kaffee", einkaufspreis: 0.35, nachfrageAnteil: 0.12 }
];

function initialerImbissstand() {
  const imbiss = {};
  IMBISS_ARTIKEL_TYPEN.forEach(t => {
    imbiss[t.id] = { bestand: 0, verkaufspreis: Math.round(t.einkaufspreis * 3.5 * 10) / 10, ziel: 0 };
  });
  return imbiss;
}

// Nur bei Heimspielen verkaufbar — anders als der Fanshop gibt es hier keinen Auswärts-Anteil,
// ein Imbissstand ist fest ans eigene Stadion gebunden.
// Mehr Verkaufsstände (wachsen automatisch mit der Stadionkapazität) bedeuten kürzere Warteschlangen
// und damit spürbar mehr Verkäufe pro Zuschauer — ein grosses, modernes Stadion mit vielen Kiosken
// verkauft dadurch effizienter als ein kleines mit nur 1-2 Ständen.
function berechneVerkaufsstandBonus(anzahlVerkaufsstaende) {
  return Math.min(1.15, 1 + Math.max(0, anzahlVerkaufsstaende - 2) * 0.005);
}

function verkaufeImbiss(imbiss, anzahlFans, anzahlVerkaufsstaende = 2, infraMultiplikator = 1, tierId = "OL") {
  const standBonus = berechneVerkaufsstandBonus(anzahlVerkaufsstaende);
  const kommerzFaktor = KOMMERZ_FAKTOR[tierId] || KOMMERZ_FAKTOR.OL;
  let einnahmen = 0;
  const neuerImbiss = {};
  const verkaeufe = {};
  IMBISS_ARTIKEL_TYPEN.forEach(t => {
    const item = imbiss[t.id] || { bestand: 0, verkaufspreis: Math.round(t.einkaufspreis * 3.5 * 10) / 10 };
    const nachfrage = Math.round(anzahlFans * t.nachfrageAnteil * kommerzFaktor * standBonus * infraMultiplikator * (0.7 + Math.random() * 0.6));
    const verkauft = Math.max(0, Math.min(nachfrage, item.bestand));
    einnahmen += verkauft * item.verkaufspreis;
    neuerImbiss[t.id] = {
      ...item,
      bestand: item.bestand - verkauft,
      verkauftSaison: (item.verkauftSaison || 0) + verkauft,
      umsatzSaison: (item.umsatzSaison || 0) + verkauft * item.verkaufspreis
    };
    verkaeufe[t.id] = verkauft;
  });
  return { neuerImbiss, einnahmen, verkaeufe };
}

// Vereinsheim: eigener Standort direkt am Stadion, wo sich die Fans VOR und NACH dem Spiel
// verpflegen (nicht während der 90 Minuten) — gleiches Sortiment wie die Stände im Stadion, aber
// eigener Warenbestand (separater Standort). Nicht jeder Zuschauer geht vorher/nachher noch ins
// Vereinsheim, daher ein deutlich reduzierter Nachfrageanteil gegenüber den Ständen im Stadion selbst.
// Die "Grösse" wächst automatisch mit der Stadionkapazität mit — ein grösserer Verein braucht auch
// ein grösseres Vereinsheim, um den Andrang zu bewältigen.
const VEREINSHEIM_NACHFRAGE_FAKTOR = 0.4;

function initialerVereinsheim() {
  const vereinsheim = {};
  IMBISS_ARTIKEL_TYPEN.forEach(t => {
    vereinsheim[t.id] = { bestand: 0, verkaufspreis: Math.round(t.einkaufspreis * 3.5 * 10) / 10, ziel: 0 };
  });
  return vereinsheim;
}

// Grösse (0.7 bis 1.3) skaliert mit der Stadionkapazität — ein kleines Vereinsheim bei einem kleinen
// Stadion bedient den Andrang schlechter, ein grosses bei einem grossen Stadion entsprechend besser.
function berechneVereinsheimGroesse(kapazitaet) {
  return Math.max(0.7, Math.min(1.3, 0.7 + (kapazitaet / 75000) * 0.6));
}

function verkaufeVereinsheim(vereinsheim, anzahlFans, kapazitaet, infraMultiplikator = 1, tierId = "OL") {
  const groesse = berechneVereinsheimGroesse(kapazitaet);
  const kommerzFaktor = KOMMERZ_FAKTOR[tierId] || KOMMERZ_FAKTOR.OL;
  let einnahmen = 0;
  const neuesVereinsheim = {};
  const verkaeufe = {};
  IMBISS_ARTIKEL_TYPEN.forEach(t => {
    const item = vereinsheim[t.id] || { bestand: 0, verkaufspreis: Math.round(t.einkaufspreis * 3.5 * 10) / 10 };
    const nachfrage = Math.round(anzahlFans * t.nachfrageAnteil * VEREINSHEIM_NACHFRAGE_FAKTOR * kommerzFaktor * groesse * infraMultiplikator * (0.7 + Math.random() * 0.6));
    const verkauft = Math.max(0, Math.min(nachfrage, item.bestand));
    einnahmen += verkauft * item.verkaufspreis;
    neuesVereinsheim[t.id] = {
      ...item,
      bestand: item.bestand - verkauft,
      verkauftSaison: (item.verkauftSaison || 0) + verkauft,
      umsatzSaison: (item.umsatzSaison || 0) + verkauft * item.verkaufspreis
    };
    verkaeufe[t.id] = verkauft;
  });
  return { neuesVereinsheim, einnahmen, verkaeufe };
}

