function initialerFanclub(managerDivId) {
  return {
    groesse: FANCLUB_BASIS_GROESSE[managerDivId] || FANCLUB_BASIS_GROESSE.OL,
    aktivitaeten: [],
    anliegen: null,
    unterstuetzungsBonus: 0
  };
}

// Fasst die gewählten Antworten einer Pressekonferenz zu einer Gesamtsumme je Zielgrösse zusammen —
// Haupt- UND Nebeneffekte aller 3 Antworten fliessen zusammen ein.
function berechnePressekonferenzEffekte(antworten) {
  const summen = { fans: 0, spieler: 0, trainer: 0, marke: 0 };
  antworten.forEach(a => {
    summen[a.ziel] = (summen[a.ziel] || 0) + a.delta;
    if (a.nebenziel) summen[a.nebenziel] = (summen[a.nebenziel] || 0) + a.nebendelta;
  });
  return summen;
}
// Wählt 2 unterschiedliche Fragen zufällig aus dem 20er-Pool — kein Thema kommt innerhalb derselben
// Pressekonferenz doppelt vor, da jede id nur einmal im Pool existiert und wir ohne Zurücklegen ziehen.
// Nimmt einen "Kontext" mit dem tatsächlichen Spielgeschehen entgegen (siehe Aufrufstelle in
// naechsterSpieltag) und lässt nur Fragen zu, deren Bedingung gerade wirklich zutrifft — sonst könnte
// z.B. nach Verletzungen gefragt werden, obwohl noch gar keine passiert sind. Fragen ohne besondere
// Bedingung (bedingung: () => true) sind immer im Topf, als verlässliche Grundmenge.
function waehlePressekonferenzFragen(rng, kontext, bereitsGestelltIds = []) {
  const fragenPool = PRESSEKONFERENZ_FRAGEN.filter(f => (!f.bedingung || f.bedingung(kontext)) && !bereitsGestelltIds.includes(f.id));
  const journalistenPool = [...JOURNALISTEN_POOL];
  const gewaehlt = [];
  for (let i = 0; i < 2 && fragenPool.length; i++) {
    const fIdx = Math.floor(rng() * fragenPool.length);
    // Jede Frage kommt sichtbar von einer ANDEREN Person — dieselbe Ohne-Zurücklegen-Logik wie bei
    // den Fragen selbst, damit sich Journalisten nicht innerhalb derselben Pressekonferenz wiederholen.
    const jPoolAktuell = journalistenPool.length ? journalistenPool : JOURNALISTEN_POOL;
    const jIdx = Math.floor(rng() * jPoolAktuell.length);
    const journalist = jPoolAktuell[jIdx];
    if (jPoolAktuell === journalistenPool) journalistenPool.splice(jIdx, 1);
    // Antwortreihenfolge mischen — sonst stünde die beste Antwort im Datensatz immer zuoberst und die
    // schlechteste immer zuunterst, wodurch die Wahl vorhersehbar würde statt eine echte Entscheidung
    // zu verlangen.
    const antworten = [...fragenPool[fIdx].antworten];
    for (let k = antworten.length - 1; k > 0; k--) {
      const j = Math.floor(rng() * (k + 1));
      [antworten[k], antworten[j]] = [antworten[j], antworten[k]];
    }
    gewaehlt.push({ ...fragenPool[fIdx], antworten, journalist });
    fragenPool.splice(fIdx, 1);
  }
  return gewaehlt;
}

