/* =========================================================================
   MARKENWERT — Die Marketingabteilung baut kontinuierlich die Aussenwirkung des
   Vereins auf. Speist sich aus Marketingchef, sportlichem Erfolg, digitaler
   Infrastruktur und Teamgeist — wirkt sich auf Fanartikel-Umsatz, Sponsoring,
   Fanclub-Wachstum, Ticketpreis-Toleranz und Transferverhandlungen aus.
   ========================================================================= */

function berechneMarkenwertAenderung(kontext) {
  const { marketingRating, tabellenplatz, anzahlTeams, digitaleInfrastruktur, teamgeist, marketingBudgetProMonat, managerDivId } = kontext;
  let aenderung = 0;
  // Marketingchef: kontinuierlicher, passiver Aufbau — je besser, desto stärker der wöchentliche Zuwachs
  if (marketingRating) aenderung += Math.max(0, (marketingRating - 30) / 400);
  else aenderung -= 0.02; // ohne Marketingchef bröckelt der Markenwert langsam
  // Eigenes laufendes Marketingbudget (Schieberegler) — unabhängig vom Marketingchef, beide addieren
  // sich. Skaliert linear bis zum Liga-Maximum (siehe MARKETING_BUDGET_MAX).
  if (marketingBudgetProMonat > 0) {
    const budgetMax = MARKETING_BUDGET_MAX[managerDivId] || MARKETING_BUDGET_MAX.OL;
    aenderung += Math.min(1, marketingBudgetProMonat / budgetMax) * MARKETING_BUDGET_MAX_BONUS;
  }
  // Sportlicher Erfolg: eine gute Tabellenposition hebt den Markenwert, eine schlechte senkt ihn
  const erfolgsFaktor = 1 - (tabellenplatz - 1) / Math.max(1, anzahlTeams - 1);
  aenderung += (erfolgsFaktor - 0.5) * 0.15;
  // Digitale Stadion-Infrastruktur: moderner Aussenauftritt zahlt auch aufs Markenimage ein
  if (digitaleInfrastruktur) aenderung += 0.03;
  // Teamgeist: eine sympathische, harmonische Truppe wird auch medial positiver wahrgenommen
  aenderung += ((teamgeist ?? 50) - 50) / 2000;
  return aenderung;
}

function markenwertEinordnung(wert) {
  if (wert >= 85) return { label: "Weltmarke", farbe: "text-amber-300" };
  if (wert >= 65) return { label: "National bekannt", farbe: "text-emerald-300" };
  if (wert >= 40) return { label: "Solide Regionalmarke", farbe: "text-emerald-400" };
  if (wert >= 20) return { label: "Kaum bekannt", farbe: "text-amber-500" };
  return { label: "Praktisch unbekannt", farbe: "text-red-400" };
}

// Realistische Obergrenze für den Markenwert je nach Liga-Niveau: eine "Weltmarke" (85+) oder auch nur
// "national bekannt" (65+) zu sein ist für einen Oberliga- oder Regionalliga-Verein unrealistisch —
// erst ab der 2. Bundesliga (wo gelegentlich auch traditionsreiche Grossvereine durchrutschen) ist der
// volle Bereich bis 100 erreichbar. Nutzt divisionTier statt der rohen Division-ID, da Oberliga/
// Regionalliga-Staffeln eigene IDs haben (z.B. "HH", "BAYERN") statt "OL"/"RL".
const MARKENWERT_DECKEL_NACH_TIER = { 5: 45, 4: 60, 3: 75, 2: 100, 1: 100 };
function markenwertDeckel(managerDivId) {
  return MARKENWERT_DECKEL_NACH_TIER[divisionTier(managerDivId)] ?? 100;
}

/* =========================================================================
   BUDGETKRISE — Dispo mit Zinsen, danach greift der Vorstand ein. Skaliert wie
   der Markenwert-Deckel mit der Liga-Ebene (divisionTier), da ein Oberligist
   mit ganz anderen Beträgen wirtschaftet als ein Bundesligist.
   ========================================================================= */

// Kreditrahmen (Dispo): solange das Budget nicht tiefer als dieser Wert rutscht, passiert nur der
// wöchentliche Zinsabzug — kein Eingreifen des Vorstands.
const DISPO_LIMIT_NACH_TIER = { 5: -100000, 4: -120000, 3: -150000, 2: -300000, 1: -1000000 };
function dispoLimit(managerDivId) {
  return DISPO_LIMIT_NACH_TIER[divisionTier(managerDivId)] ?? -100000;
}
const DISPO_ZINSSATZ = 0.02; // 2% pro Woche auf den negativen Betrag, solange innerhalb des Dispos

// Wird nach JEDER wöchentlichen Budgetabrechnung (Liga- und Pokalspieltag, die einzigen Zweige, die
// auch Löhne abbuchen) aufgerufen. Drei Stufen:
//  1) Budget positiv: nichts passiert.
//  2) Budget negativ, aber innerhalb des Dispos: nur Zinsen auf den negativen Betrag.
//  3) Budget tiefer als der Dispo: der Vorstand greift ein — beim ERSTEN Vorfall mit einem
//     Zwangsverkauf der teuersten verkäuflichen Spieler (bis das Budget wieder den Dispo-Rahmen
//     erreicht, Mindestkadergrösse bleibt erhalten), danach mit einer Warnung. Beim ZWEITEN Vorfall
//     entlässt die Vereinsversammlung den Manager sofort — mitten in der Saison, nicht erst am
//     Saisonende (siehe karriereEnde/KarriereEndeScreen).
function verarbeiteBudgetKrise({ budgetRoh, managerDivId, squad, warnstufeBisher, profile, season, anzahlSaisonsImAmt, trophaeenAnzahl }) {
  if (budgetRoh >= 0) return { budget: budgetRoh };
  const limit = dispoLimit(managerDivId);
  if (budgetRoh >= limit) {
    const zinsen = Math.round(Math.abs(budgetRoh) * DISPO_ZINSSATZ / 10) * 10;
    return { budget: budgetRoh - zinsen, dispoZinsenGezahlt: zinsen };
  }
  if ((warnstufeBisher || 0) >= 1) {
    return {
      budget: budgetRoh,
      karriereEnde: { team: profile.team, season, grund: "insolvenz", anzahlSaisons: anzahlSaisonsImAmt || 0, anzahlTrophaeen: trophaeenAnzahl || 0 }
    };
  }
  const verkaeuflich = [...squad].sort((a, b) => berechneMarktwert(b, managerDivId) - berechneMarktwert(a, managerDivId));
  let laufendesBudget = budgetRoh;
  let restSquad = [...squad];
  const verkaufteSpieler = [];
  for (const p of verkaeuflich) {
    if (laufendesBudget >= limit) break;
    if (restSquad.length <= 14) break; // Mindestkader bleibt erhalten, auch wenn das Budget dann tiefer bleibt
    const notverkaufspreis = Math.round(berechneMarktwert(p, managerDivId) * 0.7 / 100) * 100; // Notverkauf, spürbar unter Marktwert
    laufendesBudget += notverkaufspreis;
    restSquad = restSquad.filter(x => x.id !== p.id);
    verkaufteSpieler.push({ name: p.name, preis: notverkaufspreis });
  }
  return {
    budget: laufendesBudget,
    squadNachZwangsverkauf: verkaufteSpieler.length ? restSquad : null,
    ertragZwangsverkauf: verkaufteSpieler.reduce((s, v) => s + v.preis, 0),
    bankrottWarnstufe: 1,
    budgetKrise: { stufe: 1, verkaufteSpieler, verbleibendesBudget: laufendesBudget, konnteNichtGenugVerkaufen: laufendesBudget < limit }
  };
}

