function sortedTable(table) {
  return Object.values(table).sort((a, b) => {
    if (b.pkt !== a.pkt) return b.pkt - a.pkt;
    const diffA = a.tore - a.gegentore, diffB = b.tore - b.gegentore;
    if (diffB !== diffA) return diffB - diffA;
    return b.tore - a.tore;
  });
}

/* =========================================================================
   SPIELSTAND-AUFBAU
   ========================================================================= */

function buildNewCareer(season, oberligaRegionId, karriereSalt = 0) {
  const region = OBERLIGA_REGIONEN.find(r => r.id === oberligaRegionId) || OBERLIGA_REGIONEN[0];
  // Die zur gewählten Oberliga-Startregion passende Regionalliga-Staffel ermitteln (siehe
  // REGIONALLIGA_ZUORDNUNG) — bleibt für die gesamte Karriere fix, genau wie die Oberliga-Region selbst.
  const regionRL = REGIONALLIGA_REGIONEN.find(r => r.id === REGIONALLIGA_ZUORDNUNG[region.id]) || REGIONALLIGA_REGIONEN[0];
  const divisions = {};
  LIGA_DEFS.forEach(def => {
    const teams = def.id === "OL" ? region.teams : def.id === "RL" ? regionRL.teams : def.teams;
    const name = def.id === "OL" ? region.name : def.id === "RL" ? regionRL.name : def.name;
    const squads = {};
    const stadien = {};
    teams.forEach(n => {
      squads[n] = generateSquad(n, def.baseRating, season, def.id, karriereSalt);
      stadien[n] = generateStadion(n, def.id);
    });
    divisions[def.id] = {
      ...def,
      name,
      teams,
      season,
      squads,
      stadien,
      table: initTable(teams),
      fixtures: generateFixtures(teams),
      matchday: 0,
      results: []
    };
  });
  return divisions;
}

// Wie im echten Fussball (die 3. Liga spielt mit ihren 38 statt 34 Spieltagen gezielt "Englische
// Wochen" mit Doppelspieltagen, damit sie trotzdem zur gleichen Zeit wie die Bundesliga fertig wird):
// Ligen mit mehr Spieltagen als die Referenz-Pace bekommen gleichmässig über die Saison verteilte
// Doppelspieltage, damit am Ende alle Ligen etwa gleichzeitig abschliessen — spätestens Anfang Juli.
const REFERENZ_WOCHEN_PRO_SAISON = 34; // Pace einer 18er-Liga (Bundesliga/2. Liga) ohne Doppelspieltage
function berechneDoppelspieltage(gesamtSpieltage) {
  const ueberschuss = Math.max(0, gesamtSpieltage - REFERENZ_WOCHEN_PRO_SAISON);
  const indices = new Set();
  if (ueberschuss === 0) return indices;
  const abstand = gesamtSpieltage / (ueberschuss + 1);
  for (let i = 1; i <= ueberschuss; i++) {
    indices.add(Math.max(0, Math.round(i * abstand) - 1));
  }
  return indices;
}

// Bislang bekam nur der Manager automatisch einen Bonus für eine positionsoptimierte Startelf
// (formationsBonus, in coachBonuses bereits enthalten) — KI-Teams rechneten nur mit dem simplen
// Kaderdurchschnitt. Das war ein spürbarer, unverdienter Dauervorteil unabhängig vom eigenen
// Management. Jetzt bekommt JEDES Team eine faire, äquivalente Positionsoptimierung.
// Ein passiver Manager, der einfach nur durchklickt, bekommt trotzdem einen Trainer, eine gewisse
// Standard-Heimauslastung, Trainingseinstellungen und Teamgeist "gratis" — macht insgesamt rund
// 2.9 Stärkepunkte pro Spiel aus. KI-Teams hatten bisher NUR die reine Formationsoptimierung und
// sonst nichts, was dem Manager-Team einen unverdienten Dauervorteil gab, unabhängig vom eigenen
// Engagement (genau das gemeldete Problem: Aufstieg allein durchs Durchklicken). Jetzt bekommt jedes
// KI-Team eine vergleichbare Basis (repräsentiert eigenen Trainerstab, Trainingsroutine, Teamgeist)
// plus denselben Heimvorteil, wenn es zuhause spielt.
const KI_BASIS_BONUS = 1.2;
function berechneOptimierteStaerke(squad, istHeimspiel = false) {
  if (!squad.length) return 0;
  const formation = waehleFormation("ausgeglichen", null);
  const startelf = waehleStartelf(squad, formation);
  const basis = startelf.elf.length ? startelf.staerke : teamStrength(squad);
  return basis + KI_BASIS_BONUS + (istHeimspiel ? 1.7 : 0);
}

// Wählt aus den gesammelten Tageskandidaten die "Elf des Tages" — festes 4-4-2-Schema (1 TW, 2 IV,
// 2 AV, 2 ZM, 2 OM, 2 ST), pro Position die höchste Tageswertung. Bei mehreren Einträgen desselben
// Spielers (kann durch Mehrfachzählung nicht vorkommen, da jeder Spieler nur einmal pro Team-Ereignis
// auftaucht) wird ohnehin dedupliziert.
const ELF_DES_TAGES_SCHEMA = { TW: 1, IV: 2, AV: 2, ZM: 2, OM: 2, ST: 2 };
// Grundgewichtung der reinen Spielstärke in der Tageswertung, nach Position gestaffelt: Torschützen
// und Vorlagengeber (v.a. Stürmer/offensives Mittelfeld) haben ohnehin schon durch die Tor-/Vorlagen-
// Boni eine realistische Chance auf die Elf des Tages — ohne diese Staffelung fallen Innenverteidiger,
// Aussenverteidiger und defensives Mittelfeld strukturell fast immer durch, da sie kaum je direkt an
// einem Tor beteiligt sind, ihre reine spielerische Qualität aber trotzdem zählen sollte.
const TAGESWERTUNG_RATING_GEWICHT = { TW: 0.55, IV: 0.45, AV: 0.4, ZM: 0.35, OM: 0.3, ST: 0.3 };
// Maximal so viele Spieler DESSELBEN Vereins in der Elf des Tages — auch bei einem sehr dominanten
// Sieg ist es unrealistisch, wenn z.B. 8 von 11 Spielern vom gleichen Team kommen. Reale
// Team-der-Woche-Wertungen deckeln das aus genau diesem Grund ebenfalls.
const ELF_DES_TAGES_MAX_PRO_VEREIN = 4;
function waehleElfDesTages(kandidaten) {
  const nachPosition = {};
  kandidaten.forEach(k => { (nachPosition[k.pos] = nachPosition[k.pos] || []).push(k); });
  const elf = [];
  const anzahlProVerein = {};
  Object.entries(ELF_DES_TAGES_SCHEMA).forEach(([pos, anzahl]) => {
    const sortiert = (nachPosition[pos] || []).sort((a, b) => b.tageswertung - a.tageswertung);
    let ausgewaehlt = [];
    // Erster Durchlauf: Vereins-Obergrenze respektieren — der Zähler wird SOFORT nach jeder Auswahl
    // erhöht (nicht erst am Ende der Position), sonst könnten innerhalb ein und derselben Position
    // mehrere Slots gleichzeitig an denselben Verein gehen, ohne dass die Obergrenze das bemerkt.
    for (const k of sortiert) {
      if (ausgewaehlt.length >= anzahl) break;
      if ((anzahlProVerein[k.team] || 0) < ELF_DES_TAGES_MAX_PRO_VEREIN) {
        ausgewaehlt.push(k);
        anzahlProVerein[k.team] = (anzahlProVerein[k.team] || 0) + 1;
      }
    }
    // Notlösung: reicht das nicht aus, um die Position vollständig zu besetzen (z.B. weil an diesem
    // Spieltag insgesamt zu wenige unterschiedliche Vereine überhaupt Kandidaten auf dieser Position
    // gestellt haben), wird die Obergrenze für die fehlenden Plätze ignoriert, statt die Elf
    // unvollständig zu lassen.
    if (ausgewaehlt.length < anzahl) {
      const bereitsGenutzt = new Set(ausgewaehlt.map(k => k.id));
      for (const k of sortiert) {
        if (ausgewaehlt.length >= anzahl) break;
        if (!bereitsGenutzt.has(k.id)) {
          ausgewaehlt.push(k);
          anzahlProVerein[k.team] = (anzahlProVerein[k.team] || 0) + 1;
        }
      }
    }
    elf.push(...ausgewaehlt);
  });
  return elf;
}

// Ligaweite Saisonauswertung — alle Vereine der eigenen Liga, nicht nur der eigene Kader. Nutzt
// dieselben kumulativen Saisonwerte (tore/vorlagen/gelb/rot), die während der ganzen Saison ohnehin
// schon für jeden Spieler jedes Teams mitgeführt werden (siehe wendeEreignisseAn).
function ermittleSaisonStatistiken(division) {
  const allePlayers = [];
  Object.entries(division.squads).forEach(([team, squad]) => {
    squad.forEach(p => allePlayers.push({ ...p, team }));
  });
  const topListe = (feld, n = 10) => [...allePlayers].filter(p => (p[feld] || 0) > 0).sort((a, b) => (b[feld] || 0) - (a[feld] || 0)).slice(0, n);

  // Jahreswertung fürs Positionsschema und die Einzelauszeichnungen — Saison-Pendant zur
  // Tageswertung, stärker auf Torbeteiligung als auf einzelne Kartenausschläge gewichtet, da über
  // eine ganze Saison hinweg Konstanz mehr zählt als eine einzelne Szene. Dieselbe positionsabhängige
  // Grundgewichtung wie bei der Tageswertung (proportional auf die höhere Saison-Basis skaliert),
  // damit auch "Verteidiger des Jahres" & Co. nicht strukturell an torarmen Positionen scheitern.
  const JAHRESWERTUNG_RATING_GEWICHT = { TW: 0.9, IV: 0.75, AV: 0.65, ZM: 0.58, OM: 0.5, ST: 0.5 };
  const jahresKandidaten = allePlayers.map(p => ({
    ...p,
    tageswertung: p.rating * (JAHRESWERTUNG_RATING_GEWICHT[p.pos] ?? 0.5) + (p.tore || 0) * 4 + (p.vorlagen || 0) * 2 - (p.gelb || 0) * 0.5 - (p.rot || 0) * 3
  }));
  const elfDesJahres = waehleElfDesTages(jahresKandidaten);

  const desJahres = {};
  Object.entries(KADERGRUPPEN).forEach(([name, codes]) => {
    const gruppe = jahresKandidaten.filter(p => codes.includes(p.pos)).sort((a, b) => b.tageswertung - a.tageswertung);
    desJahres[name] = gruppe[0] || null;
  });
  const spielerDesJahres = [...jahresKandidaten].sort((a, b) => b.tageswertung - a.tageswertung)[0] || null;

  return {
    torschuetzen: topListe("tore"),
    vorlagengeber: topListe("vorlagen"),
    gelbeKarten: topListe("gelb"),
    roteKarten: topListe("rot"),
    elfDesJahres,
    desJahres,
    spielerDesJahres
  };
}

function simulateDivisionMatchday(division, coachBonuses = {}, managerTeam = null, standardInfoMap = {}, managerFormation = null) {
  if (division.matchday >= division.fixtures.length) return { division, managerBericht: null };
  const paarungen = division.fixtures[division.matchday];
  const table = JSON.parse(JSON.stringify(division.table));
  const neueResultate = [];
  const neueSquads = { ...division.squads };
  let managerBericht = null;
  // Sammelt für die "Elf des Tages" eine Tageswertung pro Spieler, ausschliesslich für Spieler, deren
  // Team an diesem Spieltag tatsächlich gespielt hat — Basis für ermittleElfDesTages() nach der Schleife.
  const tageskandidaten = [];

  paarungen.forEach(([heim, gast]) => {
    // Tagesform: betrifft ALLE Vereine (nicht nur den Manager), sorgt für Volatilität & Überraschungen
    const tagesformHeim = (Math.random() - 0.5) * 4;
    const tagesformGast = (Math.random() - 0.5) * 4;
    // Der Manager bekommt seinen Formationsbonus bereits separat über coachBonuses (formationsBonus
    // ist dort schon enthalten) — für alle anderen Teams wird die gleichwertige Optimierung hier
    // direkt berechnet, damit niemand einen unfairen Dauervorteil hat.
    const staerkeHeim = heim === managerTeam ? teamStrength(neueSquads[heim]) : berechneOptimierteStaerke(neueSquads[heim], true);
    const staerkeGast = gast === managerTeam ? teamStrength(neueSquads[gast]) : berechneOptimierteStaerke(neueSquads[gast], false);
    const sHeim = staerkeHeim + (coachBonuses[heim] || 0) + tagesformHeim;
    const sGast = staerkeGast + (coachBonuses[gast] || 0) + tagesformGast;
    const { heim: tHeim, gast: tGast, heimRot, gastRot } = simulateMatch(sHeim, sGast);
    applyResult(table, heim, gast, tHeim, tGast);
    neueResultate.push({ heim, gast, tHeim, tGast, spieltag: division.matchday + 1 });

    // Wichtig: simuliereEreignisse wählt Torschützen/Karten aus dem übergebenen Spielerkreis. Für BEIDE
    // Seiten wird jetzt eine echte Startelf berechnet (KI-Teams pauschal im 4-4-2, mangels eigener
    // Formationswahl) statt wie bisher den ganzen Kader zur Verfügung zu stellen — sonst hätte
    // theoretisch auch ein gar nicht aufgelaufener Ersatzspieler ein Tor bekommen können. Wichtiger
    // noch: nur so wird für JEDEN Spieler eines KI-Vereins überhaupt einmal ein Spieleinsatz gezählt
    // (spiele-Feld) — vorher wurde das bei keinem KI-Verein je hochgezählt, wodurch z.B. ausgeliehene
    // eigene Spieler bei ihrem Leihverein für immer auf 0 Einsätzen stehen blieben, egal wie stark sie
    // dort eigentlich gewesen wären. Beim EIGENEN Team (managerTeam) wird der spiele-Zähler bewusst
    // NICHT hier erhöht — das übernimmt weiter die eigene, genauere Stelle weiter unten (basierend auf
    // aktuelleStartelf/einwechslungen) — sonst würde er doppelt gezählt.
    const aiFormation = FORMATIONEN.find(f => f.id === "4-4-2");
    const spielerkreisUndEinsatz = (team) => {
      const formationFuerTeam = team === managerTeam && managerFormation ? managerFormation : aiFormation;
      const { elf, bank } = waehleStartelf(neueSquads[team], formationFuerTeam);
      const einwechslungen = waehleEinwechslungen(bank);
      return { kreis: [...elf, ...einwechslungen], eingesetzteIds: new Set([...elf, ...einwechslungen].map(p => p.id)) };
    };
    const heimEinsatz = spielerkreisUndEinsatz(heim);
    const gastEinsatz = spielerkreisUndEinsatz(gast);
    const heimEreignisse = simuliereEreignisse(heimEinsatz.kreis, tHeim, standardInfoMap[heim] || null, heimRot);
    const gastEreignisse = simuliereEreignisse(gastEinsatz.kreis, tGast, standardInfoMap[gast] || null, gastRot);
    neueSquads[heim] = wendeEreignisseUndKartenAn(neueSquads[heim], heimEreignisse, true).map(p => (heim !== managerTeam && heimEinsatz.eingesetzteIds.has(p.id)) ? { ...p, spiele: (p.spiele || 0) + 1 } : p);
    neueSquads[gast] = wendeEreignisseUndKartenAn(neueSquads[gast], gastEreignisse, true).map(p => (gast !== managerTeam && gastEinsatz.eingesetzteIds.has(p.id)) ? { ...p, spiele: (p.spiele || 0) + 1 } : p);

    // Tageswertung für die "Elf des Tages" sammeln — für beide Teams dieser Paarung.
    [
      { team: heim, ereignisse: heimEreignisse, eigeneTore: tHeim, gegnerTore: tGast, eigeneStaerke: staerkeHeim, gegnerStaerke: staerkeGast },
      { team: gast, ereignisse: gastEreignisse, eigeneTore: tGast, gegnerTore: tHeim, eigeneStaerke: staerkeGast, gegnerStaerke: staerkeHeim }
    ].forEach(({ team, ereignisse, eigeneTore, gegnerTore, eigeneStaerke, gegnerStaerke }) => {
      const sieg = eigeneTore > gegnerTore;
      const cleanSheet = gegnerTore === 0;
      // Aussenseitersieg-Bonus: gilt für die GANZE Mannschaft (nicht nur Torschützen), skaliert mit
      // dem Kräfteunterschied — ein Sieg gegen ein deutlich stärker eingeschätztes Team ist eine
      // kollektive Leistung, von der auch Spieler ohne persönliche Torbeteiligung profitieren sollen.
      const staerkeDiff = gegnerStaerke - eigeneStaerke;
      const aussenseiterBonus = sieg && staerkeDiff > 0 ? Math.min(15, staerkeDiff * 1.5) : 0;
      const toreZaehler = {}, vorlagenZaehler = {}, gelbZaehler = {};
      ereignisse.torSpieler.forEach(p => { toreZaehler[p.id] = (toreZaehler[p.id] || 0) + 1; });
      ereignisse.vorlagenSpieler.forEach(p => { vorlagenZaehler[p.id] = (vorlagenZaehler[p.id] || 0) + 1; });
      ereignisse.gelbeSpieler.forEach(p => { gelbZaehler[p.id] = (gelbZaehler[p.id] || 0) + 1; });
      (neueSquads[team] || []).forEach(p => {
        const tore = toreZaehler[p.id] || 0;
        const vorlagen = vorlagenZaehler[p.id] || 0;
        const gelb = gelbZaehler[p.id] || 0;
        const rot = ereignisse.rotSpieler?.id === p.id ? 1 : 0;
        const cleanSheetBonus = cleanSheet && (p.pos === "TW" || p.pos === "IV" || p.pos === "AV") ? 10 : 0;
        const ratingGewicht = TAGESWERTUNG_RATING_GEWICHT[p.pos] ?? 0.3;
        const tageswertung = p.rating * ratingGewicht + tore * 15 + vorlagen * 8 + cleanSheetBonus + (sieg ? 5 : 0) + aussenseiterBonus - gelb * 4 - rot * 10;
        tageskandidaten.push({ id: p.id, name: p.name, pos: p.pos, rating: p.rating, team, tore, vorlagen, tageswertung });
      });
    });

    // KI-Vereine entwickeln sich mit einer fairen Basis-Chance weiter — sonst bleibt die ganze Liga
    // eingefroren, während nur der Manager automatisch stärker wird, unabhängig vom eigenen Engagement.
    // Ab der 3. Liga steigt dieser Bonus (siehe kiEntwicklungBonusFuerDivision) — die Konkurrenz wird
    // dort zunehmend professioneller, wer ganz ohne eigenen Mitarbeiterstab auskommen will, gerät ins Hintertreffen.
    if (heim !== managerTeam) neueSquads[heim] = entwickleKaderKI(neueSquads[heim], division.id);
    if (gast !== managerTeam) neueSquads[gast] = entwickleKaderKI(neueSquads[gast], division.id);

    if (managerTeam && (heim === managerTeam || gast === managerTeam)) {
      const istHeim = heim === managerTeam;
      const eigene = istHeim ? heimEreignisse : gastEreignisse;
      const gegnerEreignisse = istHeim ? gastEreignisse : heimEreignisse;
      managerBericht = {
        heim, gast, tHeim, tGast, istHeim,
        tore: eigene.torSpieler,
        vorlagen: eigene.vorlagenSpieler,
        gelb: eigene.gelbeSpieler,
        rot: eigene.rotSpieler,
        // Für "Spieler des Tages": ein Gegenspieler kann jetzt ebenfalls gewinnen, aber nur über eigene
        // Tore/Vorlagen (siehe bestimmeSpielerDesSpieltages) — dafür Name/Team mitgeben, damit die
        // Anzeige ihn korrekt zuordnen kann.
        gegnerTeam: istHeim ? gast : heim,
        gegnerBericht: { tore: gegnerEreignisse.torSpieler, vorlagen: gegnerEreignisse.vorlagenSpieler }
      };
    }
  });

  const elfDesTagesSpieler = waehleElfDesTages(tageskandidaten);
  // Zähler direkt am Spielerobjekt erhöhen — dieselbe Kumulativ-Logik wie bei "Spieler des Spieltages"
  // (motmAnzahl), damit die Statistik-Ansicht sie ganz normal per StatistikListe anzeigen kann.
  if (elfDesTagesSpieler.length) {
    const elfIdsProTeam = {};
    elfDesTagesSpieler.forEach(sp => { (elfIdsProTeam[sp.team] = elfIdsProTeam[sp.team] || new Set()).add(sp.id); });
    Object.keys(elfIdsProTeam).forEach(team => {
      if (!neueSquads[team]) return;
      neueSquads[team] = neueSquads[team].map(p =>
        elfIdsProTeam[team].has(p.id) ? { ...p, elfDesTagesAnzahl: (p.elfDesTagesAnzahl || 0) + 1 } : p
      );
    });
  }

  return {
    division: {
      ...division,
      table,
      squads: neueSquads,
      matchday: division.matchday + 1,
      results: [...division.results, ...neueResultate]
    },
    managerBericht,
    elfDesTages: { spieltag: division.matchday + 1, spieler: elfDesTagesSpieler }
  };
}

// Auf-/Abstieg zwischen den vier Ligen anwenden, neue Saison vorbereiten
// Fallback, falls der reguläre Saisonübergang aus irgendeinem Grund scheitert:
// keine Auf-/Abstiege, Teams bleiben wo sie sind, Kader altern normal weiter.
// Diese Funktion ist bewusst so einfach gehalten, dass sie nicht scheitern kann.
function fallbackSeasonTransition(divisions, season, managerTeam) {
  const naechsteSaison = season + 1;
  const neueDivisions = {};
  ["BL", "L2", "L3", "RL", "OL"].forEach(id => {
    const alt = divisions[id];
    const def = LIGA_DEFS.find(d => d.id === id) || {};
    const teams = [...alt.teams];
    const squads = {};
    const stadien = {};
    teams.forEach(name => {
      const altesSquad = alt.squads[name];
      const rngJugend = rngFor(`${name}|jugend|${naechsteSaison}`);
      const gealtertesSquad = altesSquad
        ? altesSquad
            .map(p => ({
              ...p,
              alter: p.alter + 1,
              // Neue Saison, neuer Vergleichspunkt für die "jährliche Entwicklung" im
              // Spielerdatenblatt — auch wenn dieser vereinfachte Übergang das Rating selbst nicht
              // verändert, muss der Schnappschuss trotzdem auf den aktuellen Stand zurückgesetzt
              // werden, sonst würde die neue Saison fälschlich die Entwicklung der alten mitzählen.
              attributeSaisonStart: p.attribute,
              // Karrierewerte beim Verein kumulieren, BEVOR die Saisonwerte zurückgesetzt werden —
              // Grundlage für die Spieler-Detailansicht ("seit er im Verein ist").
              karriereTore: (p.karriereTore || 0) + (p.tore || 0),
              karriereVorlagen: (p.karriereVorlagen || 0) + (p.vorlagen || 0),
              karriereGelb: (p.karriereGelb || 0) + (p.gelb || 0),
              karriereRot: (p.karriereRot || 0) + (p.rot || 0),
              karriereSpiele: (p.karriereSpiele || 0) + (p.spiele || 0),
              // Gesamtkarriere: dieselbe Kumulierung, aber NIE bei Vereinswechsel zurückgesetzt —
              // Grundlage für "gesamte Karriere, unabhängig vom aktuellen Verein".
              gesamtkarriereTore: (p.gesamtkarriereTore || 0) + (p.tore || 0),
              gesamtkarriereVorlagen: (p.gesamtkarriereVorlagen || 0) + (p.vorlagen || 0),
              gesamtkarriereGelb: (p.gesamtkarriereGelb || 0) + (p.gelb || 0),
              gesamtkarriereRot: (p.gesamtkarriereRot || 0) + (p.rot || 0),
              gesamtkarriereSpiele: (p.gesamtkarriereSpiele || 0) + (p.spiele || 0),
              tore: 0, ligaTore: 0, vorlagen: 0, gelb: 0, rot: 0, elfmeterTore: 0, eckballTore: 0, freistossTore: 0, verletzungenSaison: 0, spiele: 0, saisonEntwicklungen: 0, form: 60, verletzung: null, kartenSperre: false, junior: false, jugendfoerderung: false
            }))
            .filter(p => {
              if (p.alter >= 38) return false;
              if (p.alter >= 35) return Math.random() > (p.alter - 34) * 0.25;
              return true;
            })
        : null;
      squads[name] = !gealtertesSquad
        ? generateSquad(name, def.baseRating || 46, naechsteSaison, def.id)
        : name === managerTeam
        ? gealtertesSquad // eigenes Team: kein automatischer Nachwuchs mehr — nur noch über die eigene Jugendarbeit/Scouting
        : verjuengeSquad(gealtertesSquad, def.baseRating || 46, name, naechsteSaison, rngJugend, def.id);
      stadien[name] = alt.stadien && alt.stadien[name]
        ? { ...alt.stadien[name], saisonkarten: { stehplaetze: 0, sitzplaetze: 0, logen: 0 }, saisonkartenVerkaufOffen: true }
        : generateStadion(name, id);
    });
    neueDivisions[id] = {
      ...def,
      name: alt.name,
      teams,
      season: naechsteSaison,
      squads,
      stadien,
      table: initTable(teams),
      fixtures: generateFixtures(teams),
      matchday: 0,
      results: []
    };
  });
  return { divisions: neueDivisions, season: naechsteSaison, abschlussTabellen: {}, fallbackVerwendet: true, vereinsHistorienZuwachs: {} };
}

function processSeasonTransition(divisions, season, managerTeam, relegationUeberschreibung = null) {
  try {
    return processSeasonTransitionInner(divisions, season, managerTeam, relegationUeberschreibung);
  } catch (err) {
    console.error("Regulärer Saisonübergang fehlgeschlagen, nutze Fallback (keine Auf-/Abstiege diese Saison):", err);
    return fallbackSeasonTransition(divisions, season, managerTeam);
  }
}

// Ist der Manager selbst in der Relegation, wird jetzt (anders als bei den übrigen, rein abstrakt
// entschiedenen Duellen) jede der beiden Partien mit echten Einzelspieler-Ereignissen simuliert — auf
// BEIDEN Seiten, analog zu einem normalen Liga-Spieltag (siehe simulateDivisionMatchday) — statt nur
// eine nackte Zahl zu würfeln. Der Gegner bekommt dabei eine neutrale 4-4-2-Standardformation, sofern
// er nicht selbst der Manager ist (kann bei einer rein theoretischen KI-Formation nicht der Fall sein,
// aber die Funktion bleibt so unabhängig von der Reihenfolge korrekt).
function simuliereRelegationsspielEcht(heimSquad, gastSquad, heimFormation, gastFormation) {
  const { elf: heimElf, bank: heimBank, staerke: sHeim } = waehleStartelf(heimSquad, heimFormation);
  const { elf: gastElf, bank: gastBank, staerke: sGast } = waehleStartelf(gastSquad, gastFormation);
  const { heim: tHeim, gast: tGast } = simulateMatch(sHeim, sGast);
  const heimEreignisse = simuliereEreignisse([...heimElf, ...waehleEinwechslungen(heimBank)], tHeim);
  const gastEreignisse = simuliereEreignisse([...gastElf, ...waehleEinwechslungen(gastBank)], tGast);
  return { tHeim, tGast, heimEreignisse, gastEreignisse };
}

// Relegation (Hin- und Rückspiel, "Europapokalsystem"): bei Gleichstand nach 2 Spielen entscheidet
// ein Elfmeterschiessen. Der Sieger ist für die höhere Liga qualifiziert, der Verlierer für die tiefere.
// Wird nur noch für die Relegation verwendet, an der der Manager NICHT selbst beteiligt ist (siehe
// simuliereRelegationsspielEcht für die spielbare Variante).
function simuliereRelegation(teamHoeher, teamTiefer, squadHoeher, squadTiefer) {  const sHoeher = teamStrength(squadHoeher);
  const sTiefer = teamStrength(squadTiefer);
  const hinspiel = simulateMatch(sHoeher, sTiefer); // Hinspiel: höherklassiger Verein zu Hause
  const rueckspiel = simulateMatch(sTiefer, sHoeher); // Rückspiel: tieferklassiger Verein zu Hause
  const toreHoeher = hinspiel.heim + rueckspiel.gast;
  const toreTiefer = hinspiel.gast + rueckspiel.heim;
  let gewinner, verlierer, elfmeter = false;
  if (toreHoeher > toreTiefer) { gewinner = teamHoeher; verlierer = teamTiefer; }
  else if (toreTiefer > toreHoeher) { gewinner = teamTiefer; verlierer = teamHoeher; }
  else {
    elfmeter = true;
    gewinner = Math.random() < 0.5 + (sHoeher - sTiefer) / 100 ? teamHoeher : teamTiefer;
    verlierer = gewinner === teamHoeher ? teamTiefer : teamHoeher;
  }
  return {
    gewinner, verlierer, elfmeter,
    hinspiel: { heim: teamHoeher, gast: teamTiefer, tHeim: hinspiel.heim, tGast: hinspiel.gast },
    rueckspiel: { heim: teamTiefer, gast: teamHoeher, tHeim: rueckspiel.heim, tGast: rueckspiel.gast },
    aggregat: { hoeher: toreHoeher, tiefer: toreTiefer }
  };
}

// Leihrückkehr: läuft ganz am Anfang jedes Saisonübergangs, bevor Alterung/Entwicklung/Vertragsabläufe
// greifen — jeder verliehene Spieler (ob vom Manager ausgeliehen oder an einen anderen Verein
// verliehen) kehrt automatisch zu seinem Stammverein zurück, sein ursprünglicher Vertrag lebt wieder
// auf. Alle Leihen laufen bewusst genau eine Saison (siehe verarbeiteLeihe), daher reicht ein simpler
// Rückkehr-Scan bei jedem Saisonübergang, ohne einzelne Leihdauern verfolgen zu müssen. Sein Rating/
// Alter zum Zeitpunkt der Rückkehr zählt — er hat sich während der Leihe ja ganz normal weiterentwickelt.
function verarbeiteLeihrueckkehr(divisions) {
  const order = ["BL", "L2", "L3", "RL", "OL"];
  let neueDivisions = { ...divisions };
  const rueckkehrer = [];
  order.forEach(divId => {
    const div = neueDivisions[divId];
    if (!div) return;
    let squadsGeaendert = false;
    const neueSquads = { ...div.squads };
    Object.entries(div.squads).forEach(([team, squad]) => {
      const leihspielerImTeam = squad.filter(p => p.leihspieler);
      if (leihspielerImTeam.length) {
        neueSquads[team] = squad.filter(p => !p.leihspieler);
        squadsGeaendert = true;
        leihspielerImTeam.forEach(p => rueckkehrer.push(p));
      }
    });
    if (squadsGeaendert) neueDivisions[divId] = { ...div, squads: neueSquads };
  });

  rueckkehrer.forEach(p => {
    const heimDivId = p.leihVereinDivId;
    const heimVerein = p.leihVerein;
    if (!neueDivisions[heimDivId] || !neueDivisions[heimDivId].squads[heimVerein]) return; // Stammverein nicht mehr auffindbar (praktisch nie der Fall)
    const { leihspieler, leihVerein, leihVereinDivId, leihBisSaison, leihRueckkehrVertrag, ...basisSpieler } = p;
    const zurueckgekehrterSpieler = {
      ...basisSpieler,
      gehalt: leihRueckkehrVertrag?.gehalt ?? p.gehalt,
      vertragBisSaison: leihRueckkehrVertrag?.vertragBisSaison ?? p.vertragBisSaison
    };
    neueDivisions[heimDivId] = {
      ...neueDivisions[heimDivId],
      squads: { ...neueDivisions[heimDivId].squads, [heimVerein]: [...neueDivisions[heimDivId].squads[heimVerein], zurueckgekehrterSpieler] }
    };
  });

  return neueDivisions;
}

function processSeasonTransitionInner(divisions_, season, managerTeam, relegationUeberschreibung = null) {
  const divisions = verarbeiteLeihrueckkehr(divisions_);
  const order = ["BL", "L2", "L3", "RL", "OL"];
  const finalTables = {};
  order.forEach(id => { finalTables[id] = sortedTable(divisions[id].table); });

  // Stadien-Nachschlagetabelle über ALLE Ligen hinweg — wichtig bei Auf-/Abstieg, da ein Verein dann
  // die Liga wechselt und sonst fälschlich ein neues (falsch grosses) Stadion bekäme.
  const alleAltenStadien = {};
  order.forEach(id => {
    Object.entries(divisions[id].stadien || {}).forEach(([name, stadion]) => { alleAltenStadien[name] = stadion; });
  });

  // Platzierungen aus der abgelaufenen Saison — KI-Vereine entwickeln sich leistungsabhängig weiter:
  // Erfolgreiche Vereine investieren und werden stärker, erfolglose bauen ab. So bleibt die Liga über
  // viele Saisons hinweg dynamisch, statt dass nur der Manager selbst immer stärker wird.
  const alleAltenPlatzierungen = {};
  order.forEach(id => {
    finalTables[id].forEach((row, idx) => {
      alleAltenPlatzierungen[row.name] = { platz: idx + 1, anzahlTeams: finalTables[id].length };
    });
  });

  // Vereinshistorie: JEDER Meister jeder Liga (nicht nur der eigene Verein) bekommt einen Eintrag in
  // die eigene, dauerhafte Trophäen-Historie seines Vereins — auch KI-Vereine. Das macht den
  // Trophäen-Tab zu einer echten Vereinshistorie: wechselt der Manager den Verein, sieht er dort die
  // Erfolge DIESES Vereins, nicht seine eigene Karriere (die bleibt separat im Karriere-Tab erhalten).
  const vereinsHistorienZuwachs = {};
  const eintragen = (verein, eintrag) => {
    if (!verein) return;
    if (!vereinsHistorienZuwachs[verein]) vereinsHistorienZuwachs[verein] = [];
    vereinsHistorienZuwachs[verein].push(eintrag);
  };
  order.forEach(id => {
    const meister = finalTables[id][0];
    if (!meister) return;
    const text = id === "BL" ? "Deutscher Meister"
      : id === "L2" ? "Meister der 2. Bundesliga — Aufstieg"
      : id === "L3" ? "Meister der 3. Liga — Aufstieg"
      : `Meister der ${divisions[id].name} — Aufstieg`;
    eintragen(meister.name, { saison: season, verein: meister.name, typ: id === "BL" ? "meisterschaft" : `meisterschaft_${id.toLowerCase()}`, text });
  });

  const neueTeams = { BL: [], L2: [], L3: [], RL: [], OL: [] };

  // Relegation BL/L2: Tabellen-16. der Bundesliga gegen Tabellen-3. der 2. Liga, Hin- und Rückspiel —
  // wie im echten Fussball seit 2008/09. Sieger spielt in der Bundesliga, Verlierer in der 2. Liga.
  const blTab = finalTables.BL;
  const l2Tab = finalTables.L2;
  const l3Tab = finalTables.L3;
  const relegationBL = relegationUeberschreibung?.liga === "BL" ? relegationUeberschreibung : simuliereRelegation(
    blTab[15].name, l2Tab[2].name,
    divisions.BL.squads[blTab[15].name], divisions.L2.squads[l2Tab[2].name]
  );

  // Relegation L2/L3: Tabellen-16. der 2. Liga gegen Tabellen-3. der 3. Liga, gleiches Prinzip.
  const relegationL2 = relegationUeberschreibung?.liga === "L2" ? relegationUeberschreibung : simuliereRelegation(
    l2Tab[15].name, l3Tab[2].name,
    divisions.L2.squads[l2Tab[15].name], divisions.L3.squads[l3Tab[2].name]
  );

  // Bundesliga: Plätze 1-15 sicher, Platz 16 über Relegation, Plätze 1+2 der 2. Liga direkt auf
  neueTeams.BL.push(...blTab.slice(0, 15).map(t => t.name));
  neueTeams.BL.push(relegationBL.gewinner);
  neueTeams.BL.push(...l2Tab.slice(0, 2).map(t => t.name));

  // 2. Liga: Plätze 4-15 sicher, Relegationsverlierer BL/L2, Relegationssieger L2/L3, Aufsteiger L3, Absteiger BL
  neueTeams.L2.push(...l2Tab.slice(3, 15).map(t => t.name));
  neueTeams.L2.push(relegationBL.verlierer);
  neueTeams.L2.push(relegationL2.gewinner);
  neueTeams.L2.push(...l3Tab.slice(0, 2).map(t => t.name));
  neueTeams.L2.push(...blTab.slice(16, 18).map(t => t.name));

  // 3. Liga: Plätze 4-18 sicher, Relegationsverlierer L2/L3, Absteiger L2, Aufsteiger Regionalliga —
  // direkter Auf-/Abstieg ohne Relegationsspiel (schlanke Version, wie zuvor bei L3↔Oberliga).
  const rlTab = finalTables.RL;
  neueTeams.L3.push(...l3Tab.slice(3, 18).map(t => t.name));
  neueTeams.L3.push(relegationL2.verlierer);
  neueTeams.L3.push(...l2Tab.slice(16, 18).map(t => t.name));
  neueTeams.L3.push(...rlTab.slice(0, 2).map(t => t.name));

  // Regionalliga: dazwischengeschobene neue Stufe — Plätze 3 bis N-2 sicher, Absteiger aus der
  // 3. Liga rücken nach, Aufsteiger aus der Oberliga rücken nach, die beiden letzten Plätze steigen
  // in die Oberliga ab.
  const olTab = finalTables.OL;
  const rlSollAnzahl = divisions.RL.teams.length;
  neueTeams.RL.push(...rlTab.slice(2, rlSollAnzahl - 2).map(t => t.name));
  neueTeams.RL.push(...l3Tab.slice(18, 20).map(t => t.name)); // Absteiger 3. Liga
  neueTeams.RL.push(...olTab.slice(0, 2).map(t => t.name)); // Aufsteiger Oberliga

  // Oberliga: unterste Spielklasse im Spiel — kein simulierter Unterbau, daher KEIN Abstieg
  // aus der Oberliga (das hätte sonst auch das eigene Team spurlos "aus der Pyramide" fallen lassen).
  // Nur die beiden Aufsteiger verlassen die Liga, alle anderen bleiben; die beiden Absteiger aus der
  // Regionalliga rücken zusätzlich nach.
  const bleibendOl = olTab.slice(2).map(t => t.name);
  neueTeams.OL.push(...bleibendOl, ...rlTab.slice(rlSollAnzahl - 2).map(t => t.name)); // + RL-Absteiger

  const naechsteSaison = season + 1;

  // Sicherheitsnetz: Dopplungen entfernen und Team-Anzahl je Liga exakt auf den Sollwert bringen
  // (schützt gegen Datenreste aus früheren, inzwischen behobenen Bugs — die Saison darf NIE steckenbleiben)
  order.forEach(id => {
    const sollAnzahl = divisions[id].teams.length;
    let liste = [...new Set(neueTeams[id].filter(Boolean))];
    let ersatzZaehler = 1;
    while (liste.length < sollAnzahl) {
      const name = `SV Ersatz ${naechsteSaison}-${ersatzZaehler++}`;
      if (!liste.includes(name)) liste.push(name);
    }
    if (liste.length > sollAnzahl) liste = liste.slice(0, sollAnzahl);
    neueTeams[id] = liste;
  });

  const neueDivisions = {};
  order.forEach(id => {
    const def = LIGA_DEFS.find(d => d.id === id);
    const teams = neueTeams[id];
    const squads = {};
    const stadien = {};
    teams.forEach(name => {
      // Kader von bestehenden Vereinen übernehmen (leicht weiterentwickelt), neue Vereine frisch generieren
      const altesSquad = divisions[id].squads[name] || Object.values(divisions).flatMap(d => Object.entries(d.squads)).find(([n]) => n === name)?.[1];
      if (altesSquad) {
        const rngDev = rngFor(`${name}|dev|s${naechsteSaison}`);
        const rngJugend = rngFor(`${name}|jugend|${naechsteSaison}`);
        const platzInfo = alleAltenPlatzierungen[name];
        // Nur KI-Vereine bekommen diesen Erfolgs-/Misserfolgsbonus — der Manager entwickelt sich bereits
        // über eigene Mechanismen (Training, Transfers, Jugend) und soll hier nicht zusätzlich profitieren.
        const vereinsBonus = (name !== managerTeam && platzInfo)
          ? Math.round(((1 - (platzInfo.platz - 1) / Math.max(1, platzInfo.anzahlTeams - 1)) - 0.5) * 6)
          : 0;
        const gealtertesSquad = altesSquad
          .map(p => {
            // Erfolgsbonus fliesst v.a. in jüngere Spieler (Investitionen, Nachwuchs) — bei älteren Spielern
            // gedämpft, damit ältere Spieler nicht künstlich über Jahre hinweg hochgepuscht werden
            const altersDaempfung = p.alter >= 32 ? 0.3 : p.alter >= 29 ? 0.7 : 1;
            const neuesRating = Math.max(28, Math.min(99, p.rating + randInt(rngDev, -3, 3) + Math.round(vereinsBonus * altersDaempfung)));
            const neuesAttribute = synchronisiereAttribute(p, neuesRating);
            return {
              ...p,
              alter: p.alter + 1,
              rating: neuesRating,
              attribute: neuesAttribute,
              // Neue Saison, neuer Vergleichspunkt: die "jährliche Entwicklung" im Spielerdatenblatt
              // (z.B. "Technik +1") bezieht sich nur auf die LAUFENDE Saison — der Schnappschuss wird
              // deshalb bei jedem Saisonübergang auf den aktuellen (bereits weiterentwickelten) Stand
              // zurückgesetzt, statt die alten Werte weiterzuschleppen.
              attributeSaisonStart: neuesAttribute,
              karriereTore: (p.karriereTore || 0) + (p.tore || 0),
              karriereVorlagen: (p.karriereVorlagen || 0) + (p.vorlagen || 0),
              karriereGelb: (p.karriereGelb || 0) + (p.gelb || 0),
              karriereRot: (p.karriereRot || 0) + (p.rot || 0),
              karriereSpiele: (p.karriereSpiele || 0) + (p.spiele || 0),
              gesamtkarriereTore: (p.gesamtkarriereTore || 0) + (p.tore || 0),
              gesamtkarriereVorlagen: (p.gesamtkarriereVorlagen || 0) + (p.vorlagen || 0),
              gesamtkarriereGelb: (p.gesamtkarriereGelb || 0) + (p.gelb || 0),
              gesamtkarriereRot: (p.gesamtkarriereRot || 0) + (p.rot || 0),
              gesamtkarriereSpiele: (p.gesamtkarriereSpiele || 0) + (p.spiele || 0),
              tore: 0, ligaTore: 0, vorlagen: 0, gelb: 0, rot: 0, elfmeterTore: 0, eckballTore: 0, freistossTore: 0, verletzungenSaison: 0, spiele: 0, saisonEntwicklungen: 0, form: 60, verletzung: null, kartenSperre: false, junior: false, jugendfoerderung: false
            };
          })
          // Rente: Spieler ab 38 hören auf, ab 35 mit steigender Wahrscheinlichkeit — sonst würden
          // Kader über viele Saisons hinweg mit unrealistisch alten Spielern volllaufen
          .filter(p => {
            if (p.alter >= 38) return false;
            if (p.alter >= 35) return Math.random() > (p.alter - 34) * 0.25;
            return true;
          });
        squads[name] = name === managerTeam
          ? gealtertesSquad // eigenes Team: kein automatischer Nachwuchs mehr — nur noch über die eigene Jugendarbeit/Scouting
          : verjuengeSquad(gealtertesSquad, def.baseRating, name, naechsteSaison, rngJugend, def.id);
      } else {
        squads[name] = generateSquad(name, def.baseRating, naechsteSaison, def.id);
      }
      stadien[name] = alleAltenStadien[name]
        ? { ...alleAltenStadien[name], saisonkarten: { stehplaetze: 0, sitzplaetze: 0, logen: 0 }, saisonkartenVerkaufOffen: true }
        : generateStadion(name, id);
    });
    neueDivisions[id] = {
      ...def,
      name: divisions[id].name,
      teams,
      season: naechsteSaison,
      squads,
      stadien,
      table: initTable(teams),
      fixtures: generateFixtures(teams),
      matchday: 0,
      results: []
    };
  });

  return { divisions: neueDivisions, season: naechsteSaison, abschlussTabellen: finalTables, relegation: { bl: relegationBL, l2: relegationL2 }, vereinsHistorienZuwachs };
}

// Robuste Liga-Stufen-/Namensauflösung: BL/L2/L3 stehen direkt in LIGA_DEFS, Oberliga-Regionen
// (z.B. "BAY-SUED", "HH") haben aber eigene IDs, die dort NICHT vorkommen — ein direkter
// LIGA_DEFS.find(...).tier-Zugriff würde für Oberliga-Teams mit undefined crashen.
function divisionTier(divId) {
  const def = LIGA_DEFS.find(l => l.id === divId);
  if (def) return def.tier;
  // Unbekannte IDs sind entweder eine Oberliga-Regionalstaffel (Tier 5) oder eine
  // Regionalliga-Staffel (Tier 4) — anhand der Regionen-Listen unterscheiden.
  if (REGIONALLIGA_REGIONEN.some(r => r.id === divId)) return 4;
  return 5;
}
function divisionName(divId) {
  const def = LIGA_DEFS.find(l => l.id === divId);
  if (def && def.id !== "OL" && def.id !== "RL") return def.name;
  return OBERLIGA_REGIONEN.find(r => r.id === divId)?.name
    || REGIONALLIGA_REGIONEN.find(r => r.id === divId)?.name
    || (def ? def.name : "Oberliga");
}

function findManagerDivision(divisions, managerTeam) {
  for (const id of Object.keys(divisions)) {
    if (divisions[id].teams.includes(managerTeam)) return id;
  }
  return null;
}

/* =========================================================================
   UI-KOMPONENTEN
   ========================================================================= */

const LIGA_FARBE = {
  BL: "text-amber-400 border-amber-400/40",
  L2: "text-sky-400 border-sky-400/40",
  L3: "text-emerald-400 border-emerald-400/40",
  RL: "text-orange-400 border-orange-400/40",
  OL: "text-fuchsia-400 border-fuchsia-400/40"
};

function SetupScreen({ onStart }) {
  const [vorname, setVorname] = useState("");
  const [nachname, setNachname] = useState("");
  const [regionId, setRegionId] = useState(OBERLIGA_REGIONEN[0].id);
  const region = OBERLIGA_REGIONEN.find(r => r.id === regionId);
  const [team, setTeam] = useState(region.teams[0]);

  const waehleRegion = (id) => {
    setRegionId(id);
    const neueRegion = OBERLIGA_REGIONEN.find(r => r.id === id);
    setTeam(neueRegion.teams[0]);
  };

  const kannStarten = vorname.trim().length > 0 && nachname.trim().length > 0;

  return (
    <div className="min-h-screen text-emerald-50 flex items-center justify-center p-4 font-mono" style={{background: "linear-gradient(135deg, #050e08 0%, #0b1f14 35%, #123322 65%, #08160e 100%)"}}>
      <div className="w-full max-w-xl border border-emerald-700/50 rounded-lg shadow-2xl overflow-hidden" style={{backgroundColor: "#0e2818"}}>
        <div className="bg-emerald-900/60 border-b border-emerald-700/50 px-6 py-5 text-center">
          <div className="flex items-center justify-center gap-2 text-amber-400 mb-1">
            <Trophy size={22} />
            <span className="text-xs tracking-[0.3em] uppercase">Deutschland</span>
          </div>
          <h1 className="text-2xl sm:text-3xl font-bold tracking-wide text-white">FUSSBALL MANAGER 26/27</h1>
          <p className="text-emerald-400/70 text-xs mt-1">Von der Oberliga bis in die Bundesliga</p>
        </div>

        <div className="p-6 space-y-5">
          <div>
            <label className="block text-xs uppercase tracking-wider text-emerald-400/80 mb-2">Manager-Name</label>
            <div className="grid grid-cols-2 gap-3">
              <input
                value={vorname}
                onChange={e => setVorname(e.target.value)}
                placeholder="Vorname"
                className="border border-emerald-700/50 rounded px-3 py-2 text-sm focus:outline-none focus:border-amber-400 placeholder:text-emerald-700" style={{backgroundColor: "#0b1f14", colorScheme: "dark"}}
              />
              <input
                value={nachname}
                onChange={e => setNachname(e.target.value)}
                placeholder="Nachname"
                className="border border-emerald-700/50 rounded px-3 py-2 text-sm focus:outline-none focus:border-amber-400 placeholder:text-emerald-700" style={{backgroundColor: "#0b1f14", colorScheme: "dark"}}
              />
            </div>
          </div>

          <div>
            <label className="block text-xs uppercase tracking-wider text-emerald-400/80 mb-2">
              1. Oberliga-Staffel wählen ({OBERLIGA_REGIONEN.length} Staffeln)
            </label>
            <div className="grid grid-cols-1 gap-1.5">
              {OBERLIGA_REGIONEN.map(r => (
                <button
                  type="button"
                  key={r.id}
                  onClick={() => waehleRegion(r.id)}
                  className={`text-left px-3 py-2 rounded border text-sm flex items-center justify-between transition-colors ${
                    r.id === regionId
                      ? "border-amber-400 text-amber-300"
                      : "border-emerald-800 text-emerald-200 hover:border-emerald-600"
                  }`}
                  style={{ backgroundColor: r.id === regionId ? "rgba(251,191,36,0.08)" : "#0b1f14" }}
                >
                  <span>{r.name}</span>
                  <span className="text-[11px] text-emerald-600">{r.teams.length} Vereine</span>
                </button>
              ))}
            </div>
          </div>

          <div>
            <label className="block text-xs uppercase tracking-wider text-emerald-400/80 mb-2">
              2. Verein wählen — {region.name}
            </label>
            <select
              value={team}
              onChange={e => setTeam(e.target.value)}
              className="w-full border border-emerald-700/50 rounded px-3 py-2 text-sm focus:outline-none focus:border-amber-400" style={{backgroundColor: "#0b1f14", colorScheme: "dark"}}
            >
              {region.teams.map(t => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>

          <button
            disabled={!kannStarten}
            onClick={() => {
              const istEasterEgg = vorname.trim() === "1" && nachname.trim() === "1";
              onStart(istEasterEgg
                ? { vorname: vorname.trim(), nachname: nachname.trim(), team: "FC Bayern München", regionId, easterEgg: true }
                : { vorname: vorname.trim(), nachname: nachname.trim(), team, regionId });
            }}
            className="w-full mt-2 bg-amber-500 hover:bg-amber-400 disabled:bg-emerald-900 disabled:text-emerald-700 disabled:cursor-not-allowed text-[#0b1f14] font-bold rounded py-3 flex items-center justify-center gap-2 transition-colors"
          >
            <Play size={18} /> Karriere starten
          </button>
        </div>
      </div>
    </div>
  );
}

function LigaPyramide({ divisions, managerDivId }) {
  // Nur noch die eigene Liga anzeigen — alle 5 Ligen gleichzeitig nahmen zu viel Platz in der
  // Kopfzeile ein, obwohl ohnehin fast immer nur die eigene Liga relevant ist.
  const d = divisions[managerDivId];
  return (
    <div className="border rounded p-3 border-amber-400 bg-amber-400/10">
      <div className={`text-xs uppercase tracking-wider ${LIGA_FARBE[managerDivId].split(" ")[0]}`}>{d.name}</div>
      <div className="text-[11px] text-emerald-600">{d.teams.length} Vereine · Spieltag {Math.min(d.matchday + 1, d.fixtures.length)}/{d.fixtures.length}</div>
    </div>
  );
}

function TabelleView({ division, managerTeam, managerBonus = 0 }) {
  const tab = sortedTable(division.table);
  const torschuetzenkoenig = ermittleTorschuetzenkoenig(division);
  return (
    <div className="overflow-x-auto">
      {torschuetzenkoenig && (
        <div className="flex items-center gap-1.5 text-xs text-amber-300 mb-2 px-1">
          <Trophy size={13} className="text-amber-400" />
          Torschützenkönig: <span className="font-semibold">{torschuetzenkoenig.name}</span>
          <span className="text-emerald-600">({torschuetzenkoenig.team}) · {torschuetzenkoenig.tore} Tore</span>
        </div>
      )}
      <table className="w-full text-xs sm:text-sm">
        <thead>
          <tr className="text-emerald-500 border-b border-emerald-800 uppercase text-[10px] sm:text-xs">
            <th className="text-left py-2 pl-2">#</th>
            <th className="text-left py-2">Verein</th>
            <th className="py-2 px-1">Stärke</th>
            <th className="py-2 px-1">Sp</th>
            <th className="py-2 px-1">S</th>
            <th className="py-2 px-1">U</th>
            <th className="py-2 px-1">N</th>
            <th className="py-2 px-1">Tore</th>
            <th className="py-2 px-1">Diff</th>
            <th className="py-2 pr-2">Pkt</th>
          </tr>
        </thead>
        <tbody>
          {tab.map((row, i) => {
            const platz = i + 1;
            const auf = platz <= division.aufsteiger;
            const ab = division.absteiger > 0 && platz > division.teams.length - division.absteiger;
            // Relegationsplätze: BL/L2 Platz 16, L2/L3 Platz 3 (bzw. spiegelbildlich) — weder sicher
            // auf- noch sicher abgestiegen, sondern Hin-/Rückspiel gegen den Nachbarn der anderen Liga.
            const relegation =
              (division.id === "BL" && platz === 16) ||
              (division.id === "L2" && (platz === 3 || platz === 16)) ||
              (division.id === "L3" && platz === 3);
            const istManager = row.name === managerTeam;
            const staerke = Math.round(teamStrength(division.squads[row.name]));
            return (
              <tr key={row.name} className={`border-b border-emerald-900/60 ${istManager ? "bg-amber-400/10 text-amber-300 font-semibold" : "text-emerald-100"}`}>
                <td className="py-1.5 pl-2 relative">
                  <span className={`inline-block w-1 h-4 mr-1 align-middle rounded-sm ${auf ? "bg-emerald-400" : ab ? "bg-red-500" : relegation ? "bg-amber-400" : "bg-transparent"}`}></span>
                  {platz}
                </td>
                <td className="py-1.5">
                  <span className="flex items-center gap-1.5">
                    <VereinsWappen teamName={row.name} size={16} />
                    {row.name}
                  </span>
                </td>
                <td className="text-center py-1.5 text-emerald-400">
                  {staerke}
                  {istManager && Math.abs(managerBonus) >= 0.5 && (
                    <span className={managerBonus > 0 ? "text-amber-400" : "text-red-400"}> ({managerBonus > 0 ? "+" : ""}{managerBonus.toFixed(1)})</span>
                  )}
                </td>
                <td className="text-center py-1.5">{row.sp}</td>
                <td className="text-center py-1.5">{row.s}</td>
                <td className="text-center py-1.5">{row.u}</td>
                <td className="text-center py-1.5">{row.n}</td>
                <td className="text-center py-1.5">{row.tore}:{row.gegentore}</td>
                <td className="text-center py-1.5">{row.tore - row.gegentore > 0 ? "+" : ""}{row.tore - row.gegentore}</td>
                <td className="text-center py-1.5 pr-2 font-semibold">{row.pkt}</td>
              </tr>
            );
          })}
        </tbody>
      </table>
      <div className="flex gap-4 mt-3 text-[10px] text-emerald-600 px-2">
        {division.aufsteiger > 0 && <span className="flex items-center gap-1"><span className="w-2 h-2 bg-emerald-400 inline-block rounded-sm"></span>Aufstieg</span>}
        {(division.id === "BL" || division.id === "L2" || division.id === "L3") && <span className="flex items-center gap-1"><span className="w-2 h-2 bg-amber-400 inline-block rounded-sm"></span>Relegation</span>}
        {division.absteiger > 0 && <span className="flex items-center gap-1"><span className="w-2 h-2 bg-red-500 inline-block rounded-sm"></span>Abstieg</span>}
      </div>
    </div>
  );
}

function VertragsKarte({ spieler, managerDivId, season, onVerlaengern, ergebnis, gesperrt }) {
  const [laufzeit, setLaufzeit] = useState(2);
  const [gehaltsFaktor, setGehaltsFaktor] = useState(105);
  const marktLohn = berechneSpielerlohn(spieler, managerDivId);
  const angebot = Math.round((marktLohn * gehaltsFaktor) / 100 / 100) * 100;
  const jahreVerbleibend = (spieler.vertragBisSaison ?? season) - season;
  return (
    <div className="border border-red-500/40 rounded p-3 text-xs space-y-2" style={{ backgroundColor: "rgba(239,68,68,0.05)" }}>
      <div className="flex items-center justify-between">
        <span className="text-red-300 font-semibold">{spieler.name} <span className="text-emerald-600 font-normal">· {spieler.posName} · {spieler.alter}J · Stärke {spieler.rating}</span></span>
        <span className="text-red-400">{jahreVerbleibend <= 0 ? "Vertrag abgelaufen" : "noch 1 Jahr"}</span>
      </div>
      {ergebnis && (
        <div className={ergebnis.angenommen ? "text-emerald-400" : "text-red-400"}>
          {ergebnis.angenommen
            ? `✓ Verlängert um ${ergebnis.laufzeit} Jahre bei ${ergebnis.gehalt.toLocaleString("de-CH")} €/Jahr.`
            : ergebnis.temporaerFrustriert
            ? "✗ Abgelehnt — er ist frustriert von den Gesprächen. Für ein paar Wochen will er nicht weiterverhandeln, und seine Form leidet vorübergehend etwas darunter."
            : "✗ Abgelehnt — versuch's mit einem besseren Angebot."}
          {!ergebnis.angenommen && ergebnis.forderungen && (
            <div className="text-amber-400 mt-1">Seine Forderung: {ergebnis.forderungen.join(" und ")}.</div>
          )}
        </div>
      )}
      <div className="flex items-center gap-2">
        <span className="text-emerald-500">Laufzeit:</span>
        {[1, 2, 3, 4].map(j => (
          <button key={j} disabled={gesperrt} onClick={() => setLaufzeit(j)} className={`px-2 py-1 rounded border text-[11px] ${laufzeit === j ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-400"} ${gesperrt ? "opacity-50 cursor-not-allowed" : ""}`}>{j}J</button>
        ))}
      </div>
      <div className="flex items-center gap-2">
        <span className="text-emerald-500">Gehalt:</span>
        {[95, 105, 120, 140].map(f => (
          <button key={f} disabled={gesperrt} onClick={() => setGehaltsFaktor(f)} className={`px-2 py-1 rounded border text-[11px] ${gehaltsFaktor === f ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-400"} ${gesperrt ? "opacity-50 cursor-not-allowed" : ""}`}>{f}%</button>
        ))}
        <span className="text-emerald-300 ml-auto">{angebot.toLocaleString("de-CH")} €/Jahr</span>
      </div>
      <button
        disabled={gesperrt}
        onClick={() => onVerlaengern(spieler.id, laufzeit, gehaltsFaktor)}
        className="w-full bg-amber-500 hover:bg-amber-400 disabled:bg-emerald-900 disabled:text-emerald-700 disabled:cursor-not-allowed text-[#0b1f14] font-bold rounded py-1.5"
      >
        {gesperrt ? "Möchte vorerst nicht weiterverhandeln" : "Angebot unterbreiten"}
      </button>
    </div>
  );
}

// Spieler-Detailansicht: Basisdaten + zwei getrennte Statistik-Blöcke (diese Saison vs. seit
// Vereinszugehörigkeit). Die Karriere-Werte werden bei jedem Saisonübergang vor dem Reset der
// Saisonwerte kumuliert (siehe fallbackSeasonTransition/Haupt-Saisonübergang) — beimVereinSeitSaison
// markiert sowohl den Ausgangspunkt der Zählung als auch das Anzeigejahr.
const FELDSPIELER_ATTRIBUT_LABEL = { technik: "Technik", passspiel: "Passspiel", offensive: "Offensive", defensive: "Defensive", physis: "Physis", tempo: "Tempo", mentalitaet: "Mentalität" };
const TORWART_ATTRIBUT_LABEL = { reflexe: "Reflexe", fangen: "Fangen", eins_gegen_eins: "1 gegen 1", strafraum: "Strafraum", spielaufbau: "Spielaufbau", physis: "Physis", mentalitaet: "Mentalität" };
function attributFarbe(wert) {
  if (wert >= 80) return "#4ade80";
  if (wert >= 65) return "#a3e635";
  if (wert >= 50) return "#fbbf24";
  if (wert >= 35) return "#fb923c";
  return "#f87171";
}
// Sieben Unterwerte (1-100), positionsabhängig — Torhüter bekommen ein eigenes Set. Reine
// Detailansicht: siehe berechneSpielerAttribute für die Herleitung aus der Gesamtstärke.
function SpielerAttributBlock({ spieler }) {
  // Bevorzugt die gespeicherten, individuell trainierten Werte — nur falls ein Spieler sie ausnahmsweise
  // noch nicht hat (z.B. ein alter Spielstand von vor dieser Funktion), werden sie einmalig berechnet.
  const attribute = useMemo(() => spieler.attribute || berechneSpielerAttribute(spieler), [spieler.attribute, spieler.id, spieler.pos, spieler.rating]);
  // Schnappschuss zu Saisonbeginn (siehe attributeSaisonStart) — die Differenz ergibt die "jährliche
  // Entwicklung" (z.B. "Technik +1"). Ohne Schnappschuss (alter Spielstand) wird keine Differenz gezeigt.
  const startWerte = spieler.attributeSaisonStart;
  const label = spieler.pos === "TW" ? TORWART_ATTRIBUT_LABEL : FELDSPIELER_ATTRIBUT_LABEL;
  const reihenfolge = spieler.pos === "TW" ? TORWART_ATTRIBUTE : FELDSPIELER_ATTRIBUTE;
  return (
    <div>
      <div className="text-[11px] uppercase tracking-wider text-emerald-400/80 mb-1.5">Fähigkeiten <span className="normal-case text-emerald-700">— Entwicklung diese Saison</span></div>
      <div className="space-y-1.5">
        {reihenfolge.map(attr => {
          const differenz = startWerte ? attribute[attr] - (startWerte[attr] ?? attribute[attr]) : 0;
          return (
            <div key={attr} className="flex items-center gap-2">
              <div className="w-24 text-[11px] text-emerald-300 shrink-0">{label[attr]}</div>
              <div className="flex-1 h-2 rounded-full overflow-hidden" style={{ backgroundColor: "#0b1f14" }}>
                <div className="h-full rounded-full" style={{ width: `${attribute[attr]}%`, backgroundColor: attributFarbe(attribute[attr]) }} />
              </div>
              <div className="w-7 text-right text-[11px] font-semibold text-emerald-200 shrink-0">{attribute[attr]}</div>
              <div className={`w-9 text-right text-[10px] font-semibold shrink-0 ${differenz > 0 ? "text-emerald-400" : differenz < 0 ? "text-red-400" : "text-transparent"}`}>
                {differenz !== 0 ? `${differenz > 0 ? "+" : ""}${differenz}` : "–"}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

function SpielerDetailModal({ spieler: p, managerDivId, season, trophaeen, teamName, portrait, onClose }) {
  const jahreImVerein = season - (p.beimVereinSeitSaison ?? season);
  const marktwert = berechneMarktwert(p, managerDivId);
  // Titel der gesamten Karriere — direkt im Moment des Gewinns auf den Spieler gestempelt (siehe
  // stempleTitelAufSquad), übersteht daher auch Vereinswechsel und ist unabhängig vom aktuellen Verein.
  const alleTitel = p.titelHistorie || [];
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4" style={{ backgroundColor: "rgba(5,14,8,0.85)" }} onClick={onClose}>
      <div className="w-full max-w-md border border-amber-400/50 rounded-lg p-5 space-y-4 max-h-[85vh] overflow-y-auto" style={{ backgroundColor: "#0e2818" }} onClick={e => e.stopPropagation()}>
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            <img src={portrait} alt="" className="w-16 h-16 rounded-full border-2 border-amber-400/50 object-cover shrink-0" />
            <div>
              <div className="text-lg font-bold text-amber-300 flex items-center gap-1.5">
                <span title={p.nationalitaet || "Deutschland"}>{NATIONALITAETEN[p.nationalitaet] || "🇩🇪"}</span> {p.name}
                {p.akademieProdukt && <span className="text-[9px] uppercase tracking-wide text-emerald-400 border border-emerald-400/40 rounded px-1 py-0.5" title="Kam aus der eigenen Jugendakademie">Eigengewächs</span>}
                {p.leihspieler && <span className="text-[9px] uppercase tracking-wide text-orange-400 border border-orange-400/40 rounded px-1 py-0.5" title={`Leihgabe von ${p.leihVerein}`}>🔄 Leihe von {p.leihVerein}</span>}
              </div>
              <div className="text-xs text-emerald-500 flex items-center gap-1.5 flex-wrap">
                <span>{p.posName} · {p.alter} Jahre · Stärke {p.rating} · {p.laenderspiele || 0} Länderspiel{(p.laenderspiele || 0) === 1 ? "" : "e"}</span>
                {!p.leihspieler && (
                  <span
                    className={`text-[10px] ${(p.zufriedenheit ?? 70) < 40 ? "text-red-400" : (p.zufriedenheit ?? 70) < 60 ? "text-amber-400" : "text-emerald-400"}`}
                    title="Individuelle Zufriedenheit — reagiert auf Einsatzzeit (moderiert durch die Persönlichkeit) und Vertragssituation. Unter 40 kostet spürbar Spielstärke."
                  >
                    · Zufriedenheit {Math.round(p.zufriedenheit ?? 70)}/100
                  </span>
                )}
              </div>
            </div>
          </div>
          <button onClick={onClose} className="text-emerald-500 hover:text-emerald-300 text-xl leading-none">×</button>
        </div>

        <div className="grid grid-cols-2 gap-2 text-xs">
          <div className="border border-emerald-800 rounded p-2" style={{ backgroundColor: "#0b1f14" }}>
            <div className="text-emerald-600 text-[10px] uppercase tracking-wider">Vertrag</div>
            <div className="text-emerald-200 font-semibold">{p.vertragBisSaison != null ? `bis Saison ${p.vertragBisSaison}/${(p.vertragBisSaison + 1) % 100}` : "?"}</div>
          </div>
          <div className="border border-emerald-800 rounded p-2" style={{ backgroundColor: "#0b1f14" }}>
            <div className="text-emerald-600 text-[10px] uppercase tracking-wider">Gehalt</div>
            <div className="text-emerald-200 font-semibold">{(p.gehalt ?? berechneSpielerlohn(p, managerDivId)).toLocaleString("de-CH")} €/Jahr</div>
          </div>
          <div className="border border-emerald-800 rounded p-2" style={{ backgroundColor: "#0b1f14" }}>
            <div className="text-emerald-600 text-[10px] uppercase tracking-wider">Marktwert</div>
            <div className="text-emerald-200 font-semibold">{marktwert.toLocaleString("de-CH")} €</div>
          </div>
          <div className="border border-emerald-800 rounded p-2" style={{ backgroundColor: "#0b1f14" }}>
            <div className="text-emerald-600 text-[10px] uppercase tracking-wider">Im Verein seit</div>
            <div className="text-emerald-200 font-semibold">{p.beimVereinSeitSaison != null ? `Saison ${p.beimVereinSeitSaison}/${(p.beimVereinSeitSaison + 1) % 100}` : "?"} ({jahreImVerein <= 0 ? "diese Saison" : `${jahreImVerein}J`})</div>
          </div>
        </div>

        <SpielerAttributBlock spieler={p} />

        <div>
          <div className="text-[11px] uppercase tracking-wider text-emerald-400/80 mb-1.5">Diese Saison</div>
          <div className="grid grid-cols-5 gap-1.5 text-center text-xs">
            <div><div className="text-emerald-600 text-[10px]">Sp</div><div className="text-emerald-200 font-semibold">{p.spiele || 0}</div></div>
            <div><div className="text-emerald-600 text-[10px]">⚽</div><div className="text-emerald-200 font-semibold">{p.tore || 0}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🅰️</div><div className="text-emerald-200 font-semibold">{p.vorlagen || 0}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🟨</div><div className="text-emerald-200 font-semibold">{p.gelb || 0}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🟥</div><div className="text-red-400 font-semibold">{p.rot || 0}</div></div>
          </div>
        </div>

        <div>
          <div className="text-[11px] uppercase tracking-wider text-amber-400/80 mb-1.5">Seit er im Verein ist</div>
          <div className="grid grid-cols-5 gap-1.5 text-center text-xs">
            <div><div className="text-emerald-600 text-[10px]">Sp</div><div className="text-amber-300 font-semibold">{(p.karriereSpiele || 0) + (p.spiele || 0)}</div></div>
            <div><div className="text-emerald-600 text-[10px]">⚽</div><div className="text-amber-300 font-semibold">{(p.karriereTore || 0) + (p.tore || 0)}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🅰️</div><div className="text-amber-300 font-semibold">{(p.karriereVorlagen || 0) + (p.vorlagen || 0)}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🟨</div><div className="text-amber-300 font-semibold">{(p.karriereGelb || 0) + (p.gelb || 0)}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🟥</div><div className="text-red-400 font-semibold">{(p.karriereRot || 0) + (p.rot || 0)}</div></div>
          </div>
          <div className="grid grid-cols-2 gap-1.5 text-center text-xs mt-1.5">
            <div className="border border-amber-400/30 rounded p-1.5"><div className="text-emerald-600 text-[10px]">⭐ Spieler des Spieltages</div><div className="text-amber-300 font-semibold">{p.motmAnzahl || 0}x</div></div>
            <div className="border border-amber-400/30 rounded p-1.5"><div className="text-emerald-600 text-[10px]">🏆 Elf des Tages</div><div className="text-amber-300 font-semibold">{p.elfDesTagesAnzahl || 0}x</div></div>
          </div>
        </div>

        <div>
          <div className="text-[11px] uppercase tracking-wider text-sky-400/80 mb-1.5">Gesamte Karriere — unabhängig vom aktuellen Verein</div>
          <div className="grid grid-cols-5 gap-1.5 text-center text-xs">
            <div><div className="text-emerald-600 text-[10px]">Sp</div><div className="text-sky-300 font-semibold">{(p.gesamtkarriereSpiele || 0) + (p.spiele || 0)}</div></div>
            <div><div className="text-emerald-600 text-[10px]">⚽</div><div className="text-sky-300 font-semibold">{(p.gesamtkarriereTore || 0) + (p.tore || 0)}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🅰️</div><div className="text-sky-300 font-semibold">{(p.gesamtkarriereVorlagen || 0) + (p.vorlagen || 0)}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🟨</div><div className="text-sky-300 font-semibold">{(p.gesamtkarriereGelb || 0) + (p.gelb || 0)}</div></div>
            <div><div className="text-emerald-600 text-[10px]">🟥</div><div className="text-red-400 font-semibold">{(p.gesamtkarriereRot || 0) + (p.rot || 0)}</div></div>
          </div>
        </div>

        {alleTitel.length > 0 && (
          <div>
            <div className="text-[11px] uppercase tracking-wider text-amber-400/80 mb-1.5">Titel der Karriere</div>
            <div className="space-y-1">
              {alleTitel.map((t, i) => (
                <div key={i} className="text-xs text-amber-300 flex items-center gap-1.5">
                  <Trophy size={11} className="text-amber-400 shrink-0" /> {t.text} <span className="text-emerald-600">— {t.verein}, Saison {t.saison}/{(t.saison + 1) % 100}</span>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function KaderView({ squad, kapitaenId, elfmeterSchuetzeId, freistossSchuetzeId, managerDivId, season, datum, onVertragVerlaengern, letzteVertragsverhandlung, stab, vertragGesperrt, trophaeen, teamName, onJugendfoerderungUmschalten, onLeihoptionKaufen, meineAusgeliehenenSpieler, alleDivisionen }) {
  const [ausgewaehlterSpieler, setAusgewaehlterSpieler] = useState(null);
  // Kollisionsfrei PRO TEAM — kein Porträt kommt innerhalb dieses Kaders zweimal vor.
  const squadPortraits = useMemo(
    () => spielerPortraitsFuerTeam([...squad.map(p => p.id), ...(meineAusgeliehenenSpieler || []).map(e => e.spielerId)]),
    [squad, meineAusgeliehenenSpieler]
  );
  // vertragGesperrt speichert jetzt ein Datum ("gesperrt bis") statt eines einfachen true/false —
  // eine zeitlich begrenzte Abkühlphase (ca. 3 Wochen) statt einer kompletten Saisonsperre.
  const istAktuellGesperrt = spielerId => vertragGesperrt?.[spielerId] && vertragGesperrt[spielerId] > datum;
  const onVerlaengernMitZaehler = (spielerId, laufzeit, gehaltsFaktor) => {
    if (istAktuellGesperrt(spielerId)) return;
    onVertragVerlaengern(spielerId, laufzeit, gehaltsFaktor);
  };
  const sortiertesSquad = [...squad].sort((a, b) => {
    const posA = POSITIONEN.findIndex(p => p.code === a.pos);
    const posB = POSITIONEN.findIndex(p => p.code === b.pos);
    if (posA !== posB) return posA - posB;
    return b.rating - a.rating;
  });
  const teamgeist = berechneTeamgeist(squad, season, stab?.psychologe?.rating, kapitaenId);
  const teamgeistInfo = teamgeistEinordnung(teamgeist.gesamt);
  const lohnsumme = berechneSquadLohnsumme(squad, managerDivId);
  const auslaufend = squad.filter(p => !p.leihspieler && (p.vertragBisSaison ?? season + 9) - season <= 1);
  return (
    <div className="overflow-x-auto">
      <div className="flex items-center justify-between border border-emerald-800 rounded px-3 py-2 mb-3 text-xs" style={{ backgroundColor: "#0b1f14" }}>
        <span className="text-emerald-500 uppercase tracking-wider text-[10px]">Gesamte Lohnsumme (jährlich)</span>
        <span className="text-amber-400 font-semibold">{lohnsumme.toLocaleString("de-CH")} €</span>
      </div>

      <div className="border border-emerald-800 rounded p-3 mb-4" style={{ backgroundColor: "#0b1f14" }}>
        <div className="flex items-center justify-between mb-2">
          <span className="text-[10px] uppercase tracking-wider text-emerald-500">Teamgeist</span>
          <span className={`text-sm font-bold ${teamgeistInfo.farbe}`}>{teamgeist.gesamt}/100 — {teamgeistInfo.label}</span>
        </div>
        <p className="text-[11px] text-emerald-600 mb-2">Ein eingespieltes, harmonierendes Team spielt über seine Einzelqualität hinaus — wirkt sich direkt auf die Spielstärke aus.</p>
        <div className="flex flex-col sm:flex-row items-center gap-3">
          <TeamgeistRadar teamgeist={teamgeist} />
          <div className="grid grid-cols-2 sm:grid-cols-3 gap-2 text-[10px] flex-1 w-full">
            <div>
              <div className="text-emerald-600">Kontinuität</div>
              <div className="text-emerald-200 font-semibold">{teamgeist.kontinuitaet}</div>
            </div>
            <div>
              <div className="text-emerald-600">Persönlichkeitsmix</div>
              <div className="text-emerald-200 font-semibold">{teamgeist.persoenlichkeitsmix}</div>
            </div>
            <div>
              <div className="text-emerald-600">Gehaltsgleichheit</div>
              <div className="text-emerald-200 font-semibold">{teamgeist.gehaltsgleichheit}</div>
            </div>
            <div>
              <div className="text-emerald-600">Bankzufriedenheit</div>
              <div className="text-emerald-200 font-semibold">{teamgeist.bankzufriedenheit}</div>
            </div>
            <div>
              <div className="text-emerald-600">Form</div>
              <div className="text-emerald-200 font-semibold">{teamgeist.form}</div>
            </div>
            <div>
              <div className="text-emerald-600">Kapitänsführung</div>
              <div className="text-emerald-200 font-semibold">{teamgeist.kapitaensfuehrung}</div>
            </div>
          </div>
        </div>
      </div>

      {auslaufend.length > 0 && (
        <div className="mb-4">
          <div className="text-[11px] uppercase tracking-wider text-red-400/80 mb-1.5">Vertrag läuft aus — jetzt verlängern oder ablösefrei verlieren</div>
          <div className="space-y-2">
            {auslaufend.map(p => (
              <VertragsKarte
                key={p.id}
                spieler={p}
                managerDivId={managerDivId}
                season={season}
                onVerlaengern={onVerlaengernMitZaehler}
                ergebnis={letzteVertragsverhandlung?.name === p.name ? letzteVertragsverhandlung : null}
                gesperrt={istAktuellGesperrt(p.id)}
              />
            ))}
          </div>
        </div>
      )}

      <p className="text-[11px] text-emerald-600 mb-1.5">💡 Auf einen Spielernamen tippen öffnet sein Spielerdatenblatt mit allen Details und Statistiken.</p>
      <table className="w-full text-xs sm:text-sm">
        <thead>
          <tr className="text-emerald-500 border-b border-emerald-800 uppercase text-[10px] sm:text-xs">
            <th className="text-left py-2 pl-2">Nr</th>
            <th className="text-left py-2">Name</th>
            <th className="text-left py-2">Position</th>
            <th className="text-left py-2">Alter</th>
            <th className="text-center py-2" title="Form">Form</th>
            <th className="text-center py-2" title="Spiele">Sp</th>
            <th className="text-center py-2" title="Tore">⚽</th>
            <th className="text-center py-2" title="Vorlagen">🅰️</th>
            <th className="text-center py-2" title="Gelbe Karten">🟨</th>
            <th className="text-center py-2" title="Rote Karten">🟥</th>
            <th className="text-right py-2" title="Jahresgehalt">Lohn</th>
            <th className="text-center py-2" title="Vertrag bis Saison">Vertrag</th>
            <th className="text-right py-2 pr-2">Stärke</th>
          </tr>
        </thead>
        <tbody>
          {sortiertesSquad.map(p => {
            const jahreVerbleibend = (p.vertragBisSaison ?? season + 9) - season;
            const vertragFarbe = jahreVerbleibend <= 1 ? "text-red-400" : jahreVerbleibend <= 2 ? "text-amber-400" : "text-emerald-500";
            return (
            <tr key={p.id} onClick={() => setAusgewaehlterSpieler(p)} className={`border-b border-emerald-900/60 cursor-pointer hover:bg-emerald-900/20 ${p.verletzung ? "text-red-400/70" : "text-emerald-100"}`}>
              <td className="py-1.5 pl-2 text-emerald-600">{p.nr}</td>
              <td className="py-1.5">
                <span title={p.nationalitaet || "Deutschland"}>{NATIONALITAETEN[p.nationalitaet] || "🇩🇪"}</span>{" "}
                {p.name}
                {p.id === kapitaenId && <span className="ml-1.5 text-[9px] uppercase tracking-wide text-amber-400 border border-amber-400/40 rounded px-1 py-0.5" title="Kapitän">© Kapitän</span>}
                {p.id === elfmeterSchuetzeId && <span className="ml-1.5 text-[9px] uppercase tracking-wide text-sky-400 border border-sky-400/40 rounded px-1 py-0.5" title="Elfmeterschütze">⚽ Elfmeter</span>}
                {p.id === freistossSchuetzeId && p.id !== elfmeterSchuetzeId && <span className="ml-1.5 text-[9px] uppercase tracking-wide text-sky-400 border border-sky-400/40 rounded px-1 py-0.5" title="Freistossschütze">🎯 Freistoss</span>}
                {p.junior && <span className="ml-1.5 text-[9px] uppercase tracking-wide text-amber-400 border border-amber-400/40 rounded px-1 py-0.5">Jugend</span>}
                {p.akademieProdukt && <span className="ml-1.5 text-[9px] uppercase tracking-wide text-emerald-400 border border-emerald-400/40 rounded px-1 py-0.5" title="Kam aus der eigenen Jugendakademie — bleibt dauerhaft sichtbar, unabhängig vom Jugend-Status">Eigengewächs</span>}
                {p.leihspieler && <span className="ml-1.5 text-[9px] uppercase tracking-wide text-orange-400 border border-orange-400/40 rounded px-1 py-0.5" title={`Leihgabe von ${p.leihVerein} — kehrt zum Saisonende automatisch dorthin zurück`}>🔄 Leihe von {p.leihVerein}</span>}
                {(p.zufriedenheit ?? 70) < 40 && (
                  <span
                    className="ml-1.5 text-[9px] uppercase tracking-wide text-red-400 border border-red-400/40 rounded px-1 py-0.5"
                    title={`Unzufrieden (${Math.round(p.zufriedenheit)}/100) — meist wegen zu wenig Einsatzzeit oder ungeklärter Vertragssituation. Kostet spürbar Spielstärke, solange das anhält.`}
                  >
                    😠 Unzufrieden
                  </span>
                )}
                {p.leihspieler && (
                  <button
                    onClick={e => { e.stopPropagation(); onLeihoptionKaufen(p.id); }}
                    className="ml-1.5 text-[9px] uppercase tracking-wide rounded px-1 py-0.5 border border-amber-400/50 text-amber-300"
                    title={`Fest verpflichten statt am Saisonende zurückzugeben — ca. ${(Math.round(berechneMarktwert(p, managerDivId) * 1.2 / 100) * 100).toLocaleString("de-CH")} € Kaufoption`}
                  >
                    💰 Kaufoption ({(Math.round(berechneMarktwert(p, managerDivId) * 1.2 / 100) * 100).toLocaleString("de-CH")} €)
                  </button>
                )}
                {p.junior && (
                  <button
                    onClick={e => { e.stopPropagation(); onJugendfoerderungUmschalten(p.id); }}
                    className={`ml-1.5 text-[9px] uppercase tracking-wide rounded px-1 py-0.5 border ${p.jugendfoerderung ? "bg-sky-500 text-[#0b1f14] border-sky-500 font-semibold" : "text-sky-400 border-sky-400/40"}`}
                    title="Bevorzugt in der Startelf einsetzen — verschafft ihm einen Stärke-Bonus bei der Aufstellungswahl, damit er auch gegen etablierte Stammspieler eine echte Chance hat."
                  >
                    ⭐ {p.jugendfoerderung ? "Wird gefördert" : "Fördern"}
                  </button>
                )}
                {p.verletzung && (
                  <span className="ml-1.5 text-[9px] uppercase tracking-wide text-red-400 border border-red-500/40 rounded px-1 py-0.5" title={`Verletzung: ${p.verletzung.art}`}>
                    🩹 noch {p.verletzung.tageVerbleibend} {p.verletzung.tageVerbleibend === 1 ? "Tag" : "Tage"}
                  </span>
                )}
                {p.laenderspielSperre && (
                  <span className="ml-1.5 text-[9px] uppercase tracking-wide text-amber-400 border border-amber-400/40 rounded px-1 py-0.5" title={p.laenderspielSperre.fenster}>
                    🚩 Länderspiel
                  </span>
                )}
                {p.kartenSperre && (
                  <span className="ml-1.5 text-[9px] uppercase tracking-wide text-red-400 border border-red-500/40 rounded px-1 py-0.5" title={p.rot ? "Rote Karte — nächstes Spiel gesperrt" : "5. Gelbe Karte — nächstes Spiel gesperrt"}>
                    🟥 Gesperrt
                  </span>
                )}
                {p.persoenlichkeit && PERSOENLICHKEITEN[p.persoenlichkeit] && (
                  <span className="ml-1.5 text-[9px] uppercase tracking-wide text-slate-300 border border-slate-500/40 rounded px-1 py-0.5" title={PERSOENLICHKEITEN[p.persoenlichkeit].beschreibung}>
                    {PERSOENLICHKEITEN_ICON[p.persoenlichkeit]} {PERSOENLICHKEITEN[p.persoenlichkeit].name}
                  </span>
                )}
              </td>
              <td className="py-1.5 text-emerald-400">{p.posName}</td>
              <td className="py-1.5">{p.alter}</td>
              <td className="py-1.5 text-center">
                <span
                  className="inline-block w-7 rounded px-1.5 py-0.5 text-[10px] font-bold text-center"
                  style={{ backgroundColor: formFarbe(p.form), color: "#0b1f14" }}
                  title={`Form: ${p.form ?? 60}/100`}
                >
                  {p.form ?? 60}
                </span>
              </td>
              <td className="py-1.5 text-center text-emerald-400 font-semibold">{p.spiele || 0}</td>
              <td className="py-1.5 text-center text-emerald-300">{p.tore || 0}</td>
              <td className="py-1.5 text-center text-emerald-300">{p.vorlagen || 0}</td>
              <td className="py-1.5 text-center text-emerald-300">{p.gelb || 0}</td>
              <td className="py-1.5 text-center text-red-400">{p.rot || 0}</td>
              <td className="py-1.5 text-right text-emerald-500">{(p.gehalt ?? berechneSpielerlohn(p, managerDivId)).toLocaleString("de-CH")} €</td>
              <td className={`py-1.5 text-center font-semibold ${vertragFarbe}`} title={`Vertrag bis Saison ${p.vertragBisSaison ?? "?"}`}>
                {jahreVerbleibend <= 0 ? "abgelaufen" : `${jahreVerbleibend}J`}
              </td>
              <td className="py-1.5 pr-2 text-right font-semibold">
                <span className={p.rating >= 75 ? "text-amber-400" : p.rating >= 55 ? "text-emerald-300" : "text-emerald-600"}>
                  {p.rating}
                </span>
              </td>
            </tr>
          );})}
        </tbody>
      </table>
      {meineAusgeliehenenSpieler && meineAusgeliehenenSpieler.length > 0 && (
        <div className="mt-4">
          <div className="text-[11px] uppercase tracking-wider text-orange-400/80 mb-1.5">Verliehen — aktueller Stand</div>
          <div className="space-y-1">
            {meineAusgeliehenenSpieler.map(e => {
              const aktuellerVerein = e.verliehenAnDivId && alleDivisionen?.[e.verliehenAnDivId]?.teams.includes(e.verliehenAn) ? e.verliehenAn : null;
              const aktuellerSpieler = aktuellerVerein ? alleDivisionen[e.verliehenAnDivId].squads[aktuellerVerein]?.find(p => p.id === e.spielerId) : null;
              return (
                <div key={e.spielerId} className="flex items-center justify-between text-xs border border-orange-400/30 rounded px-3 py-1.5" style={{ backgroundColor: "rgba(251,146,60,0.05)" }}>
                  <span className="text-emerald-100">
                    {aktuellerSpieler ? (
                      <span className="underline decoration-dotted hover:text-amber-300 cursor-pointer" onClick={() => setAusgewaehlterSpieler(aktuellerSpieler)}>{e.name}</span>
                    ) : e.name}
                    {" "}<span className="text-emerald-600">· {e.posName}{aktuellerSpieler ? ` · ${aktuellerSpieler.alter}J · Stärke ${aktuellerSpieler.rating}` : ""}</span>
                  </span>
                  <span className="text-orange-300 text-[11px]">
                    🔄 Ausgeliehen{aktuellerVerein ? ` zu ${aktuellerVerein}` : ""} · {aktuellerSpieler ? `${aktuellerSpieler.spiele || 0} Einsätze` : "Spur verloren"}
                  </span>
                </div>
              );
            })}
          </div>
        </div>
      )}
      {ausgewaehlterSpieler && (
        <SpielerDetailModal
          spieler={ausgewaehlterSpieler}
          managerDivId={managerDivId}
          season={season}
          trophaeen={trophaeen}
          teamName={teamName}
          portrait={squadPortraits[ausgewaehlterSpieler.id]}
          onClose={() => setAusgewaehlterSpieler(null)}
        />
      )}
    </div>
  );
}

// Kleine, feste Farbpalette je Ereignistyp — bewusst an die bestehenden Farbcodes angelehnt
// (Bernstein=Pokal, Himmelblau=Europapokal/Test, Smaragd=Liga), damit der Kalender optisch zum
// Rest der App passt statt wie ein Fremdkörper zu wirken.
const KALENDER_FARBEN = {
  liga: { bg: "rgba(16,185,129,0.16)", text: "#6ee7b7", dot: "#10b981" },
  pokal: { bg: "rgba(251,191,36,0.16)", text: "#fcd34d", dot: "#f59e0b" },
  europa: { bg: "rgba(56,189,248,0.16)", text: "#7dd3fc", dot: "#38bdf8" },
  test: { bg: "rgba(148,163,184,0.14)", text: "#cbd5e1", dot: "#94a3b8" },
  transfer: { bg: "rgba(192,132,252,0.14)", text: "#d8b4fe", dot: "#c084fc" },
  camp: { bg: "rgba(52,211,153,0.10)", text: "#5eead4", dot: "#2dd4bf" }
};
const KALENDER_WOCHENTAGE = ["Mo", "Di", "Mi", "Do", "Fr", "Sa", "So"];

function SpielplanView({ division, managerTeam, testspiele, season, pokal, europapokal, aktuellesDatum, trainingslager, spielHistorie = [] }) {
  const heute = new Date(aktuellesDatum + "T00:00:00");
  const [ansicht, setAnsicht] = useState({ jahr: heute.getFullYear(), monat: heute.getMonth() });
  const [unteransicht, setUnteransicht] = useState("kalender");

  const { spieltagDatum, vorsaisonTestDaten, winterTestDaten, halbzeit } = useMemo(
    () => simuliereSaisonKalender(season, division.fixtures.length),
    [season, division.fixtures.length]
  );
  // Pokal UND Europapokal richten sich real immer nach dem Bundesliga-Spielplan, unabhängig davon,
  // in welcher Liga der Manager selbst spielt — auch die Spielbarkeits-Freigabe (spielbarAb) verwendet
  // durchgehend den Bundesliga-Spieltag-Zähler (blMatchdayReferenz) als gemeinsame Uhr. Ohne diesen
  // eigenen 34er-Referenzkalender würde die Kalenderanzeige stattdessen den Kalender der EIGENEN Liga
  // verwenden (z.B. 30 Spieltage in der Oberliga) — dessen Winterpause an einem anderen Punkt liegt
  // als die der Bundesliga, wodurch der angezeigte Pokal-Termin und der tatsächliche Zeitpunkt der
  // Freigabe auseinanderlaufen können.
  const { spieltagDatum: blSpieltagDatum } = useMemo(
    () => simuliereSaisonKalender(season, 34),
    [season]
  );

  const { eventsByDate, zusaetzlicheHeuteDaten } = useMemo(() => {
    const map = {};
    const zusaetzlicheHeuteDaten = new Set();
    const add = (datum, eintrag) => {
      if (!datum) return;
      map[datum] = map[datum] || [];
      map[datum].push(eintrag);
    };
    let letztesVorsaisonTestDatum = null;
    let letztesWinterTestDatum = null;

    (testspiele?.vorsaison || []).forEach((t, i) => {
      // Das jeweils nächste noch offene Spiel exakt an das echte aktuelle Datum binden (statt an die
      // Vorausberechnung) — nur so stimmt der "Heute"-Punkt im Kalender immer mit dem Spiel überein,
      // das als Nächstes ansteht, auch wenn der reale Spielverlauf (z.B. durch die genaue Abfolge der
      // Länderspielpausen) leicht von der reinen Vorausberechnung abweicht. Nur wenn der simulierte
      // Termin bereits erreicht ist, sonst würde ein noch in der Zukunft liegendes Spiel fälschlich
      // auf "heute" gesetzt.
      // WICHTIG: zusätzlich niemals VOR (oder gleich) dem zuletzt vergebenen Testspiel-Termin, sonst
      // können zwei Testspiele im Kalender auf dasselbe Datum fallen — z.B. wenn nach dem Überspringen
      // mehrerer Wochen das erste Testspiel bereits sein eigenes (nun vergangenes) Datum zeigt und
      // "heute" zufällig genau darauf fällt, während das zweite (noch offene) ebenfalls auf "heute"
      // springen würde.
      const simDatum = vorsaisonTestDaten[i];
      const istNaechstesOffenes = !t.ergebnis && (testspiele.vorsaison.slice(0, i).every(v => v.ergebnis)) && simDatum && simDatum <= aktuellesDatum;
      let zielDatum = istNaechstesOffenes ? aktuellesDatum : simDatum;
      if (zielDatum && letztesVorsaisonTestDatum && zielDatum <= letztesVorsaisonTestDatum) {
        zielDatum = addTage(letztesVorsaisonTestDatum, 1);
      }
      if (zielDatum) letztesVorsaisonTestDatum = zielDatum;
      add(zielDatum, {
        typ: "test", kurz: "Test - H", gegner: t.gegner,
        ergebnis: t.ergebnis ? { tHeim: t.ergebnis.tHeim, tGast: t.ergebnis.tGast } : null
      });
    });
    (testspiele?.winter || []).forEach((t, i) => {
      const simDatum = winterTestDaten[i];
      const istNaechstesOffenes = !t.ergebnis && (testspiele.winter.slice(0, i).every(v => v.ergebnis)) && simDatum && simDatum <= aktuellesDatum;
      let zielDatum = istNaechstesOffenes ? aktuellesDatum : simDatum;
      if (zielDatum && letztesWinterTestDatum && zielDatum <= letztesWinterTestDatum) {
        zielDatum = addTage(letztesWinterTestDatum, 1);
      }
      if (zielDatum) letztesWinterTestDatum = zielDatum;
      add(zielDatum, {
        typ: "test", kurz: "Test - H", gegner: t.gegner,
        ergebnis: t.ergebnis ? { tHeim: t.ergebnis.tHeim, tGast: t.ergebnis.tGast } : null
      });
    });
    division.fixtures.forEach((st, idx) => {
      st.forEach(([h, g]) => {
        if (h === managerTeam || g === managerTeam) {
          const ergebnis = division.results.find(r => r.spieltag === idx + 1 && r.heim === h && r.gast === g);
          const istHeim = h === managerTeam;
          const gegner = istHeim ? g : h;
          add(spieltagDatum[idx + 1], {
            typ: "liga", kurz: `${idx + 1}.SP - ${istHeim ? "H" : "A"}`, gegner,
            ergebnis: ergebnis ? { tHeim: ergebnis.tHeim, tGast: ergebnis.tGast } : null
          });
        }
      });
    });
    (pokal?.verlauf || []).forEach((r, i) => {
      const istHeim = r.heim === managerTeam;
      const gegner = istHeim ? r.gast : r.heim;
      add(pokalRundenDatum(blSpieltagDatum, i, 34), {
        typ: "pokal", kurz: `Pokal (${r.rundenLabel === "finale" ? "Finale" : r.rundenLabel}) - ${istHeim ? "H" : "A"}`, gegner,
        ergebnis: { tHeim: r.tHeim, tGast: r.tGast }
      });
    });
    if (pokal?.ausgeloseRunde) {
      const eigenePaarung = pokal.ausgeloseRunde.paarungen.find(([h, g]) => h === managerTeam || g === managerTeam);
      if (eigenePaarung) {
        const istHeim = eigenePaarung[0] === managerTeam;
        const gegner = istHeim ? eigenePaarung[1] : eigenePaarung[0];
        const simuliertesDatum = pokalRundenDatum(blSpieltagDatum, (pokal.verlauf || []).length, 34);
        // Immer den festen, realistischen Wochentag-Termin verwenden — nicht bei Fälligkeit auf
        // "heute" springen, sonst würde die Zelle jede Woche neu wandern, bis sie schliesslich mit
        // dem Liga-Spieltag verschmilzt. Ist die Runde bereits fällig, gilt diese Zelle stattdessen
        // zusätzlich als "heute" (siehe zusaetzlicheHeuteDaten unten) — Position bleibt stabil, der
        // rote Punkt erscheint trotzdem am richtigen Ort.
        if (simuliertesDatum && simuliertesDatum <= aktuellesDatum) zusaetzlicheHeuteDaten.add(simuliertesDatum);
        add(simuliertesDatum, {
          typ: "pokal", kurz: `Pokal (${pokal.ausgeloseRunde.rundenLabel}) - ${istHeim ? "H" : "A"}`, gegner, ergebnis: null
        });
      }
    }
    if (europapokal?.gegnerListe) {
      const naechstesLigaphaseIndex = europapokal.ergebnisse?.length ?? 0;
      europapokal.gegnerListe.forEach((g, i) => {
        const gespielt = europapokal.ergebnisse?.[i];
        const simuliertesDatum = europaLigaphaseDatum(blSpieltagDatum, i, 34);
        // Gleiches Prinzip: fester Wochentag-Termin bleibt stabil, "heute" wird zusätzlich markiert
        // statt die Zelle zu verschieben.
        if (!gespielt && i === naechstesLigaphaseIndex && simuliertesDatum && simuliertesDatum <= aktuellesDatum) {
          zusaetzlicheHeuteDaten.add(simuliertesDatum);
        }
        add(simuliertesDatum, {
          typ: "europa", kurz: `${EUROPAPOKAL_NAMEN[europapokal.wettbewerb].kurz} - ${g.heim ? "H" : "A"}`, gegner: g.name,
          ergebnis: gespielt ? { tHeim: gespielt.tHeim, tGast: gespielt.tGast } : null
        });
      });
      // K.o.-Runde: der genaue Termin steht erst fest, sobald sie ansteht (kein fester Referenzpunkt
      // wie bei der Ligaphase) — deshalb wird sie, wie gewünscht, laufend ergänzt: sobald ein Gegner
      // bekannt ist, erscheint sie exakt an dem Datum, an dem sie als Nächstes gespielt wird.
      if (europapokal.koGegner) {
        const istHinspiel = !europapokal.koHinspiel;
        add(aktuellesDatum, {
          typ: "europa", kurz: `${EUROPAPOKAL_NAMEN[europapokal.wettbewerb].kurz} - ${istHinspiel ? "H" : "A"}`, gegner: europapokal.koGegner.name, ergebnis: null
        });
      }
    }
    return { eventsByDate: map, zusaetzlicheHeuteDaten };
  }, [division, managerTeam, testspiele, pokal, europapokal, spieltagDatum, vorsaisonTestDaten, winterTestDaten, aktuellesDatum]);

  // Das Trainingslager-Fenster im Kalender ist bewusst exakt an das jeweilige Transferfenster
  // gekoppelt (Sommer -> Vorrunde, Winter -> Rückrunde) — beide öffnen und schliessen zusammen,
  // statt wie zuvor an einem separat berechneten, leicht abweichenden Rückrunden-Starttermin.
  const heuteStr = aktuellesDatum;
  const ersterTagMonat = new Date(ansicht.jahr, ansicht.monat, 1);
  const wochentagVersatz = (ersterTagMonat.getDay() + 6) % 7; // Montag = 0
  const tageImMonat = new Date(ansicht.jahr, ansicht.monat + 1, 0).getDate();
  const zellen = [];
  for (let i = 0; i < wochentagVersatz; i++) zellen.push(null);
  for (let t = 1; t <= tageImMonat; t++) zellen.push(t);
  while (zellen.length % 7 !== 0) zellen.push(null);

  const datumVon = (tag) => `${ansicht.jahr}-${String(ansicht.monat + 1).padStart(2, "0")}-${String(tag).padStart(2, "0")}`;
  const monatsName = ersterTagMonat.toLocaleDateString("de-CH", { month: "long", year: "numeric" });

  return (
    <div className="space-y-3">
      <div className="flex gap-2 mb-1">
        <button
          onClick={() => setUnteransicht("kalender")}
          className={`flex-1 text-xs py-1.5 rounded border ${unteransicht === "kalender" ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-500"}`}
        >Kalender</button>
        <button
          onClick={() => setUnteransicht("zusammenfassung")}
          className={`flex-1 text-xs py-1.5 rounded border ${unteransicht === "zusammenfassung" ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-500"}`}
        >Zusammenfassung</button>
      </div>

      {unteransicht === "zusammenfassung" ? (
        <div className="space-y-2">
          {[...spielHistorie].reverse().map((s, i) => (
            <div key={i} className="border border-emerald-800 rounded p-3" style={{ backgroundColor: "#0b1f14" }}>
              <div className="flex items-center justify-between text-xs mb-1.5">
                <span className="text-emerald-500">{s.wettbewerb}{s.spieltag != null ? ` · Spieltag ${s.spieltag}` : ""} · {formatDatum(s.datum)}</span>
                <span className="text-emerald-600">{s.formation}</span>
              </div>
              <div className="text-sm text-emerald-100 font-semibold mb-1.5 flex items-center gap-1.5 flex-wrap">
                <VereinsWappen teamName={s.heim} size={16} /> {s.heim} {s.tHeim}:{s.tGast} {s.gast} <VereinsWappen teamName={s.gast} size={16} />
              </div>
              <div className="grid grid-cols-2 gap-x-4 gap-y-1 text-[11px] text-emerald-400">
                {s.torSpieler?.length > 0 && (
                  <div className="col-span-2"><span className="text-emerald-600">Tore:</span> {s.torSpieler.map(t => t.name).join(", ")}</div>
                )}
                {s.gelbeSpieler?.length > 0 && (
                  <div><span className="text-amber-500">🟨</span> {s.gelbeSpieler.map(g => g.name).join(", ")}</div>
                )}
                {s.rotSpieler && (
                  <div><span className="text-red-500">🟥</span> {s.rotSpieler.name}</div>
                )}
                {s.zuschauer != null && (
                  <div><span className="text-emerald-600">Zuschauer:</span> {s.zuschauer.toLocaleString("de-CH")}</div>
                )}
                {s.einnahmen != null && (
                  <div><span className="text-emerald-600">Einnahmen:</span> {s.einnahmen.toLocaleString("de-CH")} €</div>
                )}
                {s.ausgaben != null && (
                  <div><span className="text-emerald-600">Ausgaben:</span> {s.ausgaben.toLocaleString("de-CH")} €</div>
                )}
              </div>
            </div>
          ))}
          {!spielHistorie.length && <div className="text-emerald-700 text-xs text-center py-8">Noch keine Spiele diese Saison.</div>}
        </div>
      ) : (
      <div className="space-y-3">
      <div className="flex items-center justify-between">
        <div className="text-base font-bold text-white capitalize">{monatsName}</div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setAnsicht(a => { const m = a.monat - 1; return m < 0 ? { jahr: a.jahr - 1, monat: 11 } : { jahr: a.jahr, monat: m }; })}
            className="px-2 py-1 rounded border border-emerald-700 text-emerald-300 text-xs hover:bg-emerald-900/50"
          >‹</button>
          <button
            onClick={() => setAnsicht({ jahr: heute.getFullYear(), monat: heute.getMonth() })}
            className="px-2 py-1 rounded border border-emerald-700 text-emerald-400 text-[11px] hover:bg-emerald-900/50"
          >Heute</button>
          <button
            onClick={() => setAnsicht(a => { const m = a.monat + 1; return m > 11 ? { jahr: a.jahr + 1, monat: 0 } : { jahr: a.jahr, monat: m }; })}
            className="px-2 py-1 rounded border border-emerald-700 text-emerald-300 text-xs hover:bg-emerald-900/50"
          >›</button>
        </div>
      </div>

      <div className="flex flex-wrap gap-x-3 gap-y-1 text-[10px]">
        {[["liga", "Meisterschaft", null], ["pokal", "Pokal", null], ["europa", "Europapokal", null], ["test", "Testspiel", null], ["transfer", "Transferfenster", Repeat], ["camp", "Trainingslager buchbar", Tent]].map(([k, label, Icon]) => (
          <span key={k} className="flex items-center gap-1 text-emerald-500">
            {Icon
              ? <Icon size={10} style={{ color: KALENDER_FARBEN[k].dot }} />
              : <span className="w-2 h-2 rounded-full inline-block" style={{ backgroundColor: KALENDER_FARBEN[k].dot }}></span>
            } {label}
          </span>
        ))}
      </div>

      <div className="grid grid-cols-7 gap-px rounded overflow-hidden border border-emerald-800" style={{ backgroundColor: "#08150d" }}>
        {KALENDER_WOCHENTAGE.map(w => (
          <div key={w} className="text-center text-[11px] text-emerald-500 py-1.5 font-semibold" style={{ backgroundColor: "#0e2818" }}>{w}</div>
        ))}
        {zellen.map((tag, i) => {
          if (tag === null) return <div key={i} style={{ backgroundColor: "#0a1f13", minHeight: "116px" }} />;
          const dStr = datumVon(tag);
          const events = eventsByDate[dStr] || [];
          const fensterInfo = transferfensterStatus(dStr);
          const istTransferfenster = fensterInfo.offen;
          const istCampfenster = istTransferfenster && (fensterInfo.name === "Sommer-Transferfenster" ? !trainingslager?.vorrunde : !trainingslager?.rueckrunde);
          return (
            <div key={i} className="p-1 space-y-0.5" style={{ backgroundColor: "#0e2818", minHeight: "116px" }}>
              <div className="flex items-center justify-between gap-0.5">
                <div className="flex items-center gap-0.5">
                  {istTransferfenster && (
                    <span title={fensterInfo.name} className="rounded-sm p-0.5 shrink-0" style={{ backgroundColor: KALENDER_FARBEN.transfer.bg }}>
                      <Repeat size={9} style={{ color: KALENDER_FARBEN.transfer.dot }} />
                    </span>
                  )}
                  {istCampfenster && (
                    <span title="Trainingslager buchbar" className="rounded-sm p-0.5 shrink-0" style={{ backgroundColor: KALENDER_FARBEN.camp.bg }}>
                      <Tent size={9} style={{ color: KALENDER_FARBEN.camp.dot }} />
                    </span>
                  )}
                </div>
                <div className="text-[11px] text-emerald-600">
                  {tag}
                </div>
              </div>
              {events.map((e, ei) => (
                <div key={ei} className="text-[8px] leading-tight rounded px-1 py-0.5" style={{ backgroundColor: KALENDER_FARBEN[e.typ].bg, color: KALENDER_FARBEN[e.typ].text }} title={`${e.kurz}: ${e.gegner}${e.ergebnis ? ` ${e.ergebnis.tHeim}:${e.ergebnis.tGast}` : ""}`}>
                  <div className="font-semibold truncate">{e.kurz}</div>
                  <div className="truncate opacity-90">{e.gegner}</div>
                  {e.ergebnis && <div className="font-mono opacity-90">{e.ergebnis.tHeim}:{e.ergebnis.tGast}</div>}
                </div>
              ))}
            </div>
          );
        })}
      </div>
      </div>
      )}
    </div>
  );
}

function CoachScreen({ profile, onCoachChosen }) {
  const [kandidaten] = useState(() => generateTrainerKandidaten(profile.team, 26, Math.floor(Math.random() * 1000000), profile.easterEgg ? "BL" : "OL"));
  const [ausgewaehlt, setAusgewaehlt] = useState(null);
  const [dauer, setDauer] = useState(2);
  // Kalibriert am spielinternen Oberliga-Budgetbereich (50'000-150'000€, siehe NEUES_BUDGET_BEREICH.OL)
  // und an realen Vergleichszahlen: selbst ein bescheidener Regionalliga-Verein (eine Liga über der
  // Oberliga) kommt laut Recherche mit rund 650'000€ Jahresetat aus — 200'000€ Startkapital lag damit
  // sowohl über der eigenen Spiellogik als auch unrealistisch hoch für einen Oberliga-Verein.
  const budget = profile.easterEgg ? 100000000 : 120000;

  const sterne = (rating) => Math.max(1, Math.min(5, Math.round(rating / 20)));

  return (
    <div className="min-h-screen text-emerald-50 flex items-center justify-center p-4 font-mono" style={{background: "linear-gradient(135deg, #050e08 0%, #0b1f14 35%, #123322 65%, #08160e 100%)"}}>
      <div className="w-full max-w-2xl border border-emerald-700/50 rounded-lg shadow-2xl overflow-hidden" style={{backgroundColor: "#0e2818"}}>
        <div className="bg-emerald-900/60 border-b border-emerald-700/50 px-6 py-5 text-center">
          <div className="flex items-center justify-center gap-2 text-amber-400 mb-1">
            <Users size={22} />
            <span className="text-xs tracking-[0.3em] uppercase">Erste Amtshandlung</span>
          </div>
          <h1 className="text-xl sm:text-2xl font-bold tracking-wide text-white">Trainer verpflichten</h1>
          <p className="text-emerald-400/70 text-xs mt-1">{profile.team}</p>
        </div>

        <div className="p-5 space-y-4">
          <div className="flex items-center justify-between border border-emerald-800 rounded px-4 py-2.5 bg-emerald-950/30 text-sm">
            <span className="text-emerald-500">Startguthaben</span>
            <span className="font-bold text-amber-400">{budget.toLocaleString("de-CH")} €</span>
          </div>

          <div className="space-y-2">
            {kandidaten.map(k => {
              const gewaehlt = ausgewaehlt === k.id;
              return (
                <button
                  key={k.id}
                  type="button"
                  onClick={() => setAusgewaehlt(k.id)}
                  className={`w-full text-left rounded border px-4 py-3 transition-colors ${
                    gewaehlt ? "border-amber-400" : "border-emerald-800 hover:border-emerald-600"
                  }`}
                  style={{ backgroundColor: gewaehlt ? "rgba(251,191,36,0.08)" : "#0b1f14" }}
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <div className={`font-semibold text-sm ${gewaehlt ? "text-amber-300" : "text-emerald-100"}`}>{k.name}</div>
                      <div className="text-[11px] text-emerald-500 mt-0.5">{k.alter} Jahre · {k.stil}</div>
                    </div>
                    <div className="text-right">
                      <div className="text-amber-400 text-sm tracking-tight">{"★".repeat(sterne(k.rating))}<span className="text-emerald-800">{"★".repeat(5 - sterne(k.rating))}</span></div>
                      <div className="text-xs text-emerald-400 mt-0.5">{k.jahressalaer.toLocaleString("de-CH")} €/Jahr</div>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>

          {ausgewaehlt && (
            <div>
              <label className="block text-xs uppercase tracking-wider text-emerald-400/80 mb-2">Vertragsdauer</label>
              <div className="flex gap-1.5">
                {[1, 2, 3, 4].map(j => (
                  <button
                    key={j}
                    type="button"
                    onClick={() => setDauer(j)}
                    className={`flex-1 text-xs py-2 rounded border ${dauer === j ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-400"}`}
                  >
                    {j} {j === 1 ? "Jahr" : "Jahre"}
                  </button>
                ))}
              </div>
              <p className="text-[11px] text-emerald-600 mt-2">
                Monatslohn: {Math.round(kandidaten.find(k => k.id === ausgewaehlt).jahressalaer / 12).toLocaleString("de-CH")} € — kein Antrittsgeld, das Salär wird laufend aus dem Kontostand bezahlt.
              </p>
            </div>
          )}

          <button
            disabled={!ausgewaehlt}
            onClick={() => {
              const trainer = kandidaten.find(k => k.id === ausgewaehlt);
              onCoachChosen({ trainer, dauer, restbudget: budget });
            }}
            className="w-full mt-1 bg-amber-500 hover:bg-amber-400 disabled:bg-emerald-900 disabled:text-emerald-700 disabled:cursor-not-allowed text-[#0b1f14] font-bold rounded py-3 flex items-center justify-center gap-2 transition-colors"
          >
            <Play size={18} /> Vertrag unterzeichnen &amp; Karriere starten
          </button>
        </div>
      </div>
    </div>
  );
}

function TransfermarktView({ division, alleDivisionen, managerTeam, managerDivId, budget, datum, onTransfer, onLeihe, coachName, trainerVorschlaege, onAntwort, eingehendeAngebote, onAngebotAnnehmen, onAngebotAblehnen, spielerberaterAngebote, onSpielerberaterAngebotAnnehmen, onSpielerberaterAngebotAblehnen, ehemaligeEigengewaechse, meineAusgeliehenenSpieler, verkaufsliste, onAufMarktSetzen, onVonMarktNehmen, transferGesperrt, onTransferVerhandlungErgebnis, season, trophaeen }) {
  const fenster = transferfensterStatus(datum);
  const [modus, setModus] = useState("kaufen");
  const [kaufAnsicht, setKaufAnsicht] = useState("markt"); // "markt" | "verein"
  const [positionsFilter, setPositionsFilter] = useState("ALLE");
  const [suchbegriff, setSuchbegriff] = useState("");
  const [verhandlung, setVerhandlung] = useState(null); // { spieler, teamName, richtung, angebot, nachricht, sourceDivId }
  const [spielerFuerDetail, setSpielerFuerDetail] = useState(null);

  const eigenesSquad = division.squads[managerTeam];
  // Nicht mehr nur die eigene Liga: zusätzlich die direkt benachbarten Ligen (eine Stufe höher UND
  // eine tiefer, wo vorhanden) werden mit durchsucht — realistisch, da echte Vereine auch aus
  // Nachbarligen verpflichten (günstigere, aber schwächere Spieler von unten; teurere, aber
  // erfahrenere von oben). Marktwert und Verhandlungslogik bilden die Preisunterschiede bereits ab.
  const durchsuchteDivIds = useMemo(() => {
    const ids = [managerDivId];
    const hoeher = naechstHoehereDivision(managerDivId);
    const tiefer = naechstNiedrigereDivision(managerDivId);
    if (hoeher) ids.push(hoeher);
    if (tiefer) ids.push(tiefer);
    return ids;
  }, [managerDivId]);
  const marktSpieler = useMemo(
    () => sammleTransfermarktSpieler(alleDivisionen, durchsuchteDivIds, managerTeam, division.matchday)
      .sort((a, b) => b.p.rating - a.p.rating),
    [alleDivisionen, durchsuchteDivIds, managerTeam, division.matchday]
  );

  // "Verein durchsuchen" bezieht jetzt dieselben Ligen mit ein wie der freie Markt oben — Vereine aus
  // Nachbarligen erscheinen mit Liga-Kennzeichnung, damit die Herkunft klar bleibt.
  const gegnerTeamsMitLiga = useMemo(() => {
    const liste = [];
    durchsuchteDivIds.forEach(divId => {
      const div = alleDivisionen[divId];
      if (!div) return;
      div.teams.filter(t => !(divId === managerDivId && t === managerTeam)).forEach(t => {
        liste.push({ team: t, divId, ligaName: div.name });
      });
    });
    return liste;
  }, [alleDivisionen, durchsuchteDivIds, managerDivId, managerTeam]);
  const gegnerSchluessel = (eintrag) => `${eintrag.divId}::${eintrag.team}`;
  const [gegnerAuswahl, setGegnerAuswahl] = useState(() => gegnerTeamsMitLiga[0] ? gegnerSchluessel(gegnerTeamsMitLiga[0]) : "");
  const aktuellerGegner = gegnerTeamsMitLiga.find(e => gegnerSchluessel(e) === gegnerAuswahl) || gegnerTeamsMitLiga[0] || null;
  const gegnerSquad = aktuellerGegner ? (alleDivisionen[aktuellerGegner.divId]?.squads?.[aktuellerGegner.team] || []) : [];
  const gefilterteMarktSpieler = marktSpieler.filter(k => {
    if (positionsFilter !== "ALLE" && k.p.pos !== positionsFilter) return false;
    if (suchbegriff && !k.p.name.toLowerCase().includes(suchbegriff.toLowerCase()) && !k.team.toLowerCase().includes(suchbegriff.toLowerCase())) return false;
    return true;
  });
  const verkaufsVorschlaege = trainerVorschlaege?.verkaufen || [];
  const kaufVorschlaege = trainerVorschlaege?.kaufen || [];

  const oeffneVerhandlung = (spieler, teamName, richtung, sourceDivId, gelistet = true) => {
    if (transferGesperrt?.[spieler.id]) return;
    const wert = berechneMarktwert(spieler, sourceDivId || managerDivId);
    // Sinnvoller Startwert je nach Alter: bei einem älteren Spieler macht ein langer Vertrag ohnehin
    // selten Sinn, ein kürzerer Vorschlag passt daher besser als Ausgangspunkt.
    const laufzeitVorschlag = spieler.alter >= 32 ? 1 : spieler.alter >= 28 ? 2 : 3;
    setVerhandlung({ spieler, teamName, richtung, wert, quote: gelistet ? 100 : 130, laufzeit: laufzeitVorschlag, nachricht: null, sourceDivId: sourceDivId || managerDivId, gelistet });
  };

  const angebotAbgeben = () => {
    const { spieler, wert, quote, richtung, teamName, sourceDivId, gelistet, laufzeit } = verhandlung;
    if (transferGesperrt?.[spieler.id]) return;
    const summe = Math.round((wert * quote) / 100 / 100) * 100;
    const ratio = quote / 100;
    // Kauf: Verkäufer nimmt eher an, je höher das Angebot. Verkauf: Käufer nimmt eher an, je niedriger die Forderung.
    // Nicht gelistete Spieler will der Verein eigentlich gar nicht verkaufen — deutlich schwerer zu überzeugen.
    const nichtGelistetMalus = (richtung === "kaufen" && gelistet === false) ? 0.35 : 0;
    const chance = richtung === "kaufen"
      ? Math.max(0.02, Math.min(0.9, 0.5 + (ratio - 1) * 2 - nichtGelistetMalus))
      : Math.max(0.03, Math.min(0.97, 0.5 - (ratio - 1) * 2));
    const erfolg = Math.random() < chance;
    onTransferVerhandlungErgebnis(spieler.id, erfolg);

    if (erfolg) {
      onTransfer({ richtung, spieler, teamName, summe, sourceDivId, laufzeit });
      setVerhandlung(v => ({ ...v, nachricht: { art: "erfolg", summe } }));
    } else {
      // Ob daraus eine dauerhafte Sperre für den Rest dieses Transferfensters wird, entscheidet der
      // Zufall (siehe onTransferVerhandlungErgebnis) — hier wird zunächst immer nur die Ablehnung
      // gezeigt; die Sperre selbst wird erst beim nächsten Öffnungsversuch sichtbar (transferGesperrt).
      setVerhandlung(v => ({ ...v, nachricht: { art: "ablehnung" } }));
    }
  };

  if (!fenster.offen) {
    return (
      <div className="text-center py-8">
        <Lock className="mx-auto text-emerald-700 mb-3" size={28} />
        <div className="text-emerald-300 font-semibold text-sm">Transferfenster geschlossen</div>
        <div className="text-emerald-600 text-xs mt-1">Nächstes Fenster öffnet am {fenster.naechstesFenster}</div>
        <div className="text-emerald-700 text-[11px] mt-3">Sommerfenster: 01.07.–31.08. · Winterfenster: 01.01.–31.01.</div>
      </div>
    );
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-3 text-xs">
        <span className="text-amber-400 font-semibold">{fenster.name} geöffnet (bis {fenster.bisText})</span>
        <span className="text-emerald-500">Kontostand: <span className="text-amber-400 font-semibold">{budget.toLocaleString("de-CH")} €</span></span>
      </div>

      {eingehendeAngebote && eingehendeAngebote.length > 0 && (
        <div className="mb-3 space-y-2">
          <div className="text-[11px] uppercase tracking-wider text-amber-400/80">Abwerbeangebote für deine Spieler</div>
          {eingehendeAngebote.map(a => (
            <div key={a.id} className="border border-amber-400/40 rounded p-2.5" style={{ backgroundColor: "rgba(251,191,36,0.06)" }}>
              <div className="flex items-center justify-between text-xs">
                <span className="text-amber-300 font-semibold">{a.spielerName}</span>
                <span className="text-emerald-400">{a.summe.toLocaleString("de-CH")} €</span>
              </div>
              <div className="text-[11px] text-emerald-500 mt-0.5">{a.team} ({a.ligaName}) macht ein Angebot{a.spielerWillWechseln ? " — der Spieler würde gerne wechseln!" : ""}</div>
              <div className="flex gap-1.5 mt-2">
                <button onClick={() => onAngebotAnnehmen(a)} className="flex-1 bg-amber-500 hover:bg-amber-400 text-[#0b1f14] font-bold text-xs rounded py-1.5">Annehmen</button>
                <button onClick={() => onAngebotAblehnen(a)} className="flex-1 border border-emerald-700 text-emerald-300 text-xs rounded py-1.5">Ablehnen</button>
              </div>
              {a.spielerWillWechseln && <div className="text-[10px] text-red-400 mt-1.5">Bei Ablehnung leidet die Form des Spielers spürbar.</div>}
            </div>
          ))}
        </div>
      )}

      {spielerberaterAngebote && spielerberaterAngebote.length > 0 && (
        <div className="mb-3 space-y-2">
          <div className="text-[11px] uppercase tracking-wider text-sky-400/80">Spielerberater bieten dir Klienten an</div>
          {spielerberaterAngebote.map(a => (
            <div key={a.id} className="border border-sky-400/40 rounded p-2.5" style={{ backgroundColor: "rgba(56,189,248,0.06)" }}>
              <div className="flex items-center justify-between text-xs">
                <span className="text-sky-300 font-semibold">{a.spieler.name} <span className="text-emerald-600">· {a.spieler.posName} · {a.spieler.alter}J · Stärke {a.spieler.rating}</span></span>
                <span className="text-emerald-400">{a.preis.toLocaleString("de-CH")} €</span>
              </div>
              <div className="text-[11px] text-emerald-500 mt-0.5">Aktuell bei {a.verkaufendesTeam} ({a.ligaName}) — nicht offiziell gelistet, der Spieler {a.grund}.</div>
              <div className="flex gap-1.5 mt-2">
                <button onClick={() => onSpielerberaterAngebotAnnehmen(a)} className="flex-1 bg-sky-500 hover:bg-sky-400 text-[#0b1f14] font-bold text-xs rounded py-1.5">Verpflichten</button>
                <button onClick={() => onSpielerberaterAngebotAblehnen(a)} className="flex-1 border border-emerald-700 text-emerald-300 text-xs rounded py-1.5">Nicht interessiert</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {ehemaligeEigengewaechse && ehemaligeEigengewaechse.length > 0 && (
        <div className="mb-3 space-y-2">
          <div className="text-[11px] uppercase tracking-wider text-emerald-400/80">Ehemalige Eigengewächse</div>
          {ehemaligeEigengewaechse.map(e => {
            const aktuellerVerein = e.verkauftDivId && alleDivisionen[e.verkauftDivId]?.teams.includes(e.verkauftAn) ? e.verkauftAn : null;
            const aktuellerSpieler = aktuellerVerein ? alleDivisionen[e.verkauftDivId].squads[aktuellerVerein]?.find(p => p.id === e.spielerId) : null;
            if (!aktuellerSpieler) {
              return (
                <div key={e.spielerId} className="border border-emerald-900 rounded p-2.5 text-xs text-emerald-600" style={{ backgroundColor: "#0b1f14" }}>
                  {e.name} — Spur verloren (Vereinswechsel im Ausland o.ä.), kein Rückkauf mehr möglich.
                </div>
              );
            }
            const ratingDelta = aktuellerSpieler.rating - e.ratingBeimVerkauf;
            const marktwert = berechneMarktwert(aktuellerSpieler, e.verkauftDivId);
            const rueckkaufpreis = Math.round(marktwert * 1.15 / 100) * 100; // kleiner Aufschlag ggü. reinem Marktwert
            return (
              <div key={e.spielerId} className="border border-emerald-700/50 rounded p-2.5" style={{ backgroundColor: "rgba(16,185,129,0.05)" }}>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-emerald-300 font-semibold">{aktuellerSpieler.name} <span className="text-emerald-600">· {aktuellerSpieler.posName} · {aktuellerSpieler.alter}J · Stärke {aktuellerSpieler.rating}{ratingDelta !== 0 ? ` (${ratingDelta > 0 ? "+" : ""}${ratingDelta} seit Verkauf)` : ""}</span></span>
                  <span className="text-amber-400">{rueckkaufpreis.toLocaleString("de-CH")} €</span>
                </div>
                <div className="text-[11px] text-emerald-500 mt-0.5">
                  Verkauft in Saison {e.verkauftSaison}/{(e.verkauftSaison + 1) % 100} · jetzt bei {aktuellerVerein} ({alleDivisionen[e.verkauftDivId]?.name})
                </div>
                <button
                  disabled={rueckkaufpreis > budget}
                  onClick={() => onTransfer({ richtung: "kaufen", spieler: aktuellerSpieler, teamName: aktuellerVerein, summe: rueckkaufpreis, sourceDivId: e.verkauftDivId, laufzeit: 3 })}
                  className="w-full mt-2 bg-emerald-600 hover:bg-emerald-500 disabled:bg-emerald-900 disabled:text-emerald-700 disabled:cursor-not-allowed text-[#0b1f14] font-bold text-xs rounded py-1.5"
                >
                  Zurückkaufen — sorgt garantiert für einen Trikot-Ansturm
                </button>
              </div>
            );
          })}
        </div>
      )}

      {meineAusgeliehenenSpieler && meineAusgeliehenenSpieler.length > 0 && (
        <div className="mb-3 space-y-2">
          <div className="text-[11px] uppercase tracking-wider text-orange-400/80">Meine Leihspieler — aktueller Stand</div>
          {meineAusgeliehenenSpieler.map(e => {
            const aktuellerVerein = e.verliehenAnDivId && alleDivisionen[e.verliehenAnDivId]?.teams.includes(e.verliehenAn) ? e.verliehenAn : null;
            const aktuellerSpieler = aktuellerVerein ? alleDivisionen[e.verliehenAnDivId].squads[aktuellerVerein]?.find(p => p.id === e.spielerId) : null;
            if (!aktuellerSpieler) {
              return (
                <div key={e.spielerId} className="border border-emerald-900 rounded p-2.5 text-xs text-emerald-600" style={{ backgroundColor: "#0b1f14" }}>
                  {e.name} — Spur verloren, kehrt aber trotzdem zum Saisonende automatisch zurück.
                </div>
              );
            }
            const ratingDelta = aktuellerSpieler.rating - e.ratingBeiVerleih;
            return (
              <div key={e.spielerId} className="border border-orange-400/40 rounded p-2.5" style={{ backgroundColor: "rgba(251,146,60,0.06)" }}>
                <div className="flex items-center justify-between text-xs">
                  <span className="text-orange-300 font-semibold">{aktuellerSpieler.name} <span className="text-emerald-600">· {aktuellerSpieler.posName} · {aktuellerSpieler.alter}J · Stärke {aktuellerSpieler.rating}{ratingDelta !== 0 ? ` (${ratingDelta > 0 ? "+" : ""}${ratingDelta} seit Verleih)` : ""}</span></span>
                  <span className="text-emerald-500">{aktuellerSpieler.spiele || 0} Einsätze</span>
                </div>
                <div className="text-[11px] text-emerald-500 mt-0.5">
                  Verliehen seit Saison {e.verliehenSaison}/{(e.verliehenSaison + 1) % 100} · aktuell bei {aktuellerVerein} ({alleDivisionen[e.verliehenAnDivId]?.name}) · kehrt zum Saisonende automatisch zurück
                </div>
              </div>
            );
          })}
        </div>
      )}

      <div className="flex gap-1 mb-3">
        <button onClick={() => { setModus("kaufen"); setVerhandlung(null); }} className={`flex-1 text-xs py-1.5 rounded border ${modus === "kaufen" ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-400"}`}>Spieler kaufen</button>
        <button onClick={() => { setModus("verkaufen"); setVerhandlung(null); }} className={`flex-1 text-xs py-1.5 rounded border ${modus === "verkaufen" ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-400"}`}>Spieler verkaufen</button>
      </div>

      {modus === "kaufen" && (
        <div>
          {kaufVorschlaege.length > 0 && (
            <div className="mb-3">
              <div className="text-[11px] uppercase tracking-wider text-sky-400/80 mb-1.5">Der Trainer wünscht sich Verstärkung auf folgenden Positionen</div>
              <div className="space-y-1.5">
                {kaufVorschlaege.map(k => (
                  <div
                    key={k.position}
                    className="w-full rounded border px-3 py-2 text-xs border-sky-400/40"
                    style={{ backgroundColor: "rgba(56,189,248,0.05)" }}
                  >
                    <span className="text-sky-300 font-semibold">{k.posName}</span>
                    <div className="text-emerald-500 text-[11px] mt-0.5">„{k.grund}"</div>
                  </div>
                ))}
              </div>
            </div>
          )}

          <div className="flex gap-1 mb-3">
            <button onClick={() => setKaufAnsicht("markt")} className={`flex-1 text-[11px] py-1.5 rounded border ${kaufAnsicht === "markt" ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-500"}`}>Transfermarkt</button>
            <button onClick={() => setKaufAnsicht("verein")} className={`flex-1 text-[11px] py-1.5 rounded border ${kaufAnsicht === "verein" ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-500"}`}>Verein durchsuchen</button>
          </div>

          {kaufAnsicht === "markt" ? (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-emerald-400/80 mb-1.5">Transfermarkt — {gefilterteMarktSpieler.length} gelistete Spieler</div>
              <p className="text-[11px] text-emerald-600 mb-2">Nur Spieler, die ihr Verein selbst als entbehrlich einstuft, stehen zum Verkauf. Die Auswahl rotiert im Laufe der Saison.</p>
              <div className="flex gap-1.5 mb-2">
                <input
                  type="text"
                  value={suchbegriff}
                  onChange={e => setSuchbegriff(e.target.value)}
                  placeholder="Name oder Verein suchen…"
                  className="flex-1 border border-emerald-700/50 rounded px-3 py-2 text-xs focus:outline-none focus:border-amber-400"
                  style={{ backgroundColor: "#0b1f14", colorScheme: "dark" }}
                />
                <select
                  value={positionsFilter}
                  onChange={e => setPositionsFilter(e.target.value)}
                  className="border border-emerald-700/50 rounded px-2 py-2 text-xs focus:outline-none focus:border-amber-400"
                  style={{ backgroundColor: "#0b1f14", colorScheme: "dark" }}
                >
                  <option value="ALLE">Alle Positionen</option>
                  {POSITIONEN.map(pos => <option key={pos.code} value={pos.code}>{pos.code}</option>)}
                </select>
              </div>
              <div className="max-h-72 overflow-y-auto space-y-1">
                {gefilterteMarktSpieler.map(k => {
                  const gesperrt = !!transferGesperrt?.[k.p.id];
                  return (
                    <div
                      key={k.p.id}
                      className={`flex items-center gap-1.5 text-xs px-3 py-1.5 rounded border ${gesperrt ? "border-emerald-900/50 opacity-40" : "border-emerald-900"}`}
                      style={{ backgroundColor: "#0b1f14" }}
                    >
                      <button
                        disabled={gesperrt}
                        onClick={() => oeffneVerhandlung(k.p, k.team, "kaufen", k.divId, true)}
                        className={`flex-1 flex items-center justify-between text-left ${gesperrt ? "cursor-not-allowed" : "hover:opacity-80"}`}
                      >
                        <span className="text-emerald-100">
                          <span className="underline decoration-dotted hover:text-amber-300" onClick={e => { e.stopPropagation(); setSpielerFuerDetail(k.p); }}>{k.p.name}</span>
                          {" "}<span className="text-emerald-600">· {k.team} ({k.ligaName}) · {k.p.pos} · {k.p.alter}J · Stärke </span><span className="text-emerald-300 font-semibold">{k.p.rating}</span>
                        </span>
                        {gesperrt ? (
                          <span className="text-red-400 text-[11px] flex items-center gap-1"><Lock size={11} /> gesperrt</span>
                        ) : (
                          <span className="text-amber-400">{berechneMarktwert(k.p, k.divId).toLocaleString("de-CH")} €</span>
                        )}
                      </button>
                      {!gesperrt && (
                        <button
                          onClick={() => onLeihe({ richtung: "ausleihen", spieler: k.p, teamName: k.team, sourceDivId: k.divId })}
                          className="shrink-0 text-[10px] border border-orange-400/50 text-orange-300 rounded px-2 py-1"
                          title={`Für eine Saison ausleihen — ca. ${Math.round(berechneMarktwert(k.p, k.divId) * 0.15 / 100) * 100} € Leihgebühr statt vollem Kaufpreis`}
                        >
                          Leihen
                        </button>
                      )}
                    </div>
                  );
                })}
                {gefilterteMarktSpieler.length === 0 && (
                  <div className="text-center text-emerald-700 text-xs py-6">Keine passenden Spieler gelistet — versuch's mit einem anderen Filter oder schau später nochmal vorbei.</div>
                )}
              </div>
            </div>
          ) : (
            <div>
              <div className="text-[11px] uppercase tracking-wider text-emerald-400/80 mb-1.5">Kompletten Kader durchsuchen</div>
              <p className="text-[11px] text-emerald-600 mb-2">Hier siehst du den ganzen Kader — auch Spieler, die gar nicht zum Verkauf stehen. Ein Angebot ist möglich, aber deutlich schwerer durchzusetzen, da der Verein eigentlich nicht verkaufen will.</p>
              <select
                value={gegnerAuswahl}
                onChange={e => { setGegnerAuswahl(e.target.value); setVerhandlung(null); }}
                className="w-full border border-emerald-700/50 rounded px-3 py-2 text-sm mb-2 focus:outline-none focus:border-amber-400"
                style={{ backgroundColor: "#0b1f14", colorScheme: "dark" }}
              >
                {gegnerTeamsMitLiga.map(e => <option key={gegnerSchluessel(e)} value={gegnerSchluessel(e)}>{e.team} ({e.ligaName})</option>)}
              </select>
              <div className="max-h-64 overflow-y-auto space-y-1">
                {gegnerSquad.map(sp => {
                  const gesperrt = !!transferGesperrt?.[sp.id];
                  const gelistet = istAufTransfermarkt(sp, gegnerSquad, aktuellerGegner.team, division.matchday);
                  return (
                    <button
                      key={sp.id}
                      disabled={gesperrt}
                      onClick={() => oeffneVerhandlung(sp, aktuellerGegner.team, "kaufen", aktuellerGegner.divId, gelistet)}
                      className={`w-full flex items-center justify-between text-xs px-3 py-1.5 rounded border text-left ${gesperrt ? "border-emerald-900/50 opacity-40 cursor-not-allowed" : gelistet ? "border-emerald-900 hover:border-emerald-600" : "border-emerald-900/60 hover:border-red-500/50"}`}
                      style={{ backgroundColor: "#0b1f14" }}
                    >
                      <span className="text-emerald-100">
                        <span className="underline decoration-dotted hover:text-amber-300" onClick={e => { e.stopPropagation(); setSpielerFuerDetail(sp); }}>{sp.name}</span>
                        {" "}<span className="text-emerald-600">· {sp.pos} · {sp.alter}J · Stärke </span><span className="text-emerald-300 font-semibold">{sp.rating}</span>
                        {!gelistet && <span className="text-red-400 text-[10px] ml-1.5">nicht gelistet</span>}
                      </span>
                      {gesperrt ? (
                        <span className="text-red-400 text-[11px] flex items-center gap-1"><Lock size={11} /> gesperrt</span>
                      ) : (
                        <span className="text-amber-400">{berechneMarktwert(sp, aktuellerGegner.divId).toLocaleString("de-CH")} €</span>
                      )}
                    </button>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      )}

      {modus === "verkaufen" && (
        <div>
          <p className="text-[11px] text-emerald-600 mb-2">
            Setze Spieler auf den Transfermarkt, statt sie sofort zu verkaufen — andere Vereine machen dir dann über die nächsten Spieltage verteilt eigene Angebote, die du annehmen oder ablehnen kannst (siehe oben).
          </p>
          {verkaufsVorschlaege.length > 0 && (
            <div className="mb-2 space-y-1">
              {verkaufsVorschlaege.map(v => (
                <div key={v.playerId} className="text-[11px] text-orange-300 border border-orange-400/30 rounded px-2.5 py-1.5" style={{ backgroundColor: "rgba(251,146,60,0.06)" }}>
                  <div className="flex items-start gap-1.5">
                    <ThumbsDown size={12} className="mt-0.5 shrink-0" />
                    <span><span className="font-semibold">{v.name}</span>: „{v.grund}"</span>
                  </div>
                  {onAntwort && (
                    v.antwort ? (
                      <div className="text-emerald-400 mt-1.5 italic pl-4">
                        Du: „{MANAGER_ANTWORTEN_VERKAUF.find(a => a.id === v.antwort)?.text}"
                        {v.ersetzenBeimNaechstenSpieltag && <span className="text-emerald-700 not-italic"> — wird nach dem nächsten Spieltag ersetzt</span>}
                      </div>
                    ) : (
                      <div className="flex flex-wrap gap-1.5 mt-1.5 pl-4">
                        {MANAGER_ANTWORTEN_VERKAUF.map(a => (
                          <button
                            key={a.id}
                            type="button"
                            onClick={() => onAntwort("verkaufen", v.playerId, a)}
                            className="text-[10px] border border-emerald-700 text-emerald-300 rounded px-2 py-1 hover:border-amber-400 hover:text-amber-300"
                          >
                            {a.text}
                          </button>
                        ))}
                      </div>
                    )
                  )}
                </div>
              ))}
            </div>
          )}
          <div className="max-h-72 overflow-y-auto space-y-1">
            {[...eigenesSquad].filter(sp => !sp.leihspieler).sort((a, b) => (verkaufsVorschlaege.some(v => v.playerId === b.id) ? 1 : 0) - (verkaufsVorschlaege.some(v => v.playerId === a.id) ? 1 : 0)).map(sp => {
              const empfohlen = verkaufsVorschlaege.some(v => v.playerId === sp.id);
              const gelistet = (verkaufsliste || []).includes(sp.id);
              const anzahlAngebote = (eingehendeAngebote || []).filter(a => a.spielerId === sp.id).length;
              return (
                <div
                  key={sp.id}
                  className={`w-full flex items-center justify-between text-xs px-3 py-1.5 rounded border ${gelistet ? "border-sky-400/50" : empfohlen ? "border-orange-400/50" : "border-emerald-900"}`}
                  style={{ backgroundColor: "#0b1f14" }}
                >
                  <span className="text-emerald-100 flex items-center gap-1.5">
                    {empfohlen && <ThumbsDown size={11} className="text-orange-400" />}
                    <span className="underline decoration-dotted hover:text-amber-300 cursor-pointer" onClick={() => setSpielerFuerDetail(sp)}>{sp.name}</span>
                    {" "}<span className="text-emerald-600">· {sp.pos} · {sp.alter}J · Stärke </span><span className="text-emerald-300 font-semibold">{sp.rating}</span>
                    {gelistet && <span className="text-[10px] text-sky-400 border border-sky-400/40 rounded px-1.5 py-0.5">Auf Markt{anzahlAngebote > 0 ? ` · ${anzahlAngebote} Angebot${anzahlAngebote > 1 ? "e" : ""}` : ""}</span>}
                  </span>
                  <div className="flex items-center gap-2">
                    <span className="text-amber-400">{berechneMarktwert(sp, managerDivId).toLocaleString("de-CH")} €</span>
                    <button
                      onClick={() => onLeihe({ richtung: "verleihen", spieler: sp, teamName: managerTeam, sourceDivId: managerDivId })}
                      className="text-[11px] rounded px-2 py-1 border border-orange-400/50 text-orange-300"
                      title="Für eine Saison an einen anderen Verein verleihen — er sammelt dort Spielpraxis und kehrt automatisch zurück"
                    >
                      Verleihen
                    </button>
                    <button
                      onClick={() => gelistet ? onVonMarktNehmen(sp.id) : onAufMarktSetzen(sp.id)}
                      className={`text-[11px] rounded px-2 py-1 border ${gelistet ? "border-red-500/50 text-red-300" : "border-sky-400/50 text-sky-300"}`}
                    >
                      {gelistet ? "Vom Markt nehmen" : "Auf Markt setzen"}
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {verhandlung && (
        <div className="mt-3 border border-amber-400/40 rounded p-3" style={{ backgroundColor: "rgba(251,191,36,0.06)" }}>
          <div className="flex items-center justify-between mb-2">
            <div>
              <div className="text-sm font-semibold text-amber-300">{verhandlung.spieler.name}</div>
              <div className="text-[11px] text-emerald-500">{verhandlung.richtung === "kaufen" ? `von ${verhandlung.teamName} (${divisionName(verhandlung.sourceDivId)})` : "aus deinem Kader"} · {verhandlung.spieler.alter}J · Stärke {verhandlung.spieler.rating} · Marktwert {verhandlung.wert.toLocaleString("de-CH")} €</div>
            </div>
            <button onClick={() => setVerhandlung(null)} className="text-emerald-600 text-xs">✕</button>
          </div>

          {verhandlung.richtung === "kaufen" && verhandlung.gelistet === false && (
            <div className="text-[11px] text-red-400 mb-2">Dieser Spieler steht nicht zum Verkauf — der Verein braucht ein deutlich höheres Angebot, um sich umstimmen zu lassen.</div>
          )}

          <div className="text-[11px] text-emerald-500 mb-1.5">
            {verhandlung.richtung === "kaufen" ? "Dein Angebot" : "Deine Forderung"}: <span className="text-white font-semibold">{Math.round((verhandlung.wert * verhandlung.quote) / 100 / 100) * 100} €</span> ({verhandlung.quote}% des Marktwerts)
          </div>
          <div className="flex gap-1.5 mb-3">
            {(verhandlung.richtung === "kaufen" && verhandlung.gelistet === false ? [110, 130, 150, 175, 200] : [80, 90, 100, 110, 125]).map(q => (
              <button
                key={q}
                onClick={() => setVerhandlung(v => ({ ...v, quote: q, nachricht: null }))}
                className={`flex-1 text-xs py-1.5 rounded border ${verhandlung.quote === q ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-400"}`}
              >
                {q}%
              </button>
            ))}
          </div>

          {verhandlung.richtung === "kaufen" && (
            <div className="mb-3">
              <div className="text-[11px] text-emerald-500 mb-1.5">
                Vertragsdauer beim Wechsel: <span className="text-white font-semibold">{verhandlung.laufzeit} Jahr{verhandlung.laufzeit === 1 ? "" : "e"}</span>
                {verhandlung.spieler.alter >= 32 && <span className="text-amber-400"> — bei diesem Alter lieber kurz halten?</span>}
              </div>
              <div className="flex gap-1.5">
                {[1, 2, 3, 4, 5].map(j => (
                  <button
                    key={j}
                    onClick={() => setVerhandlung(v => ({ ...v, laufzeit: j }))}
                    className={`flex-1 text-xs py-1.5 rounded border ${verhandlung.laufzeit === j ? "border-amber-400 text-amber-300" : "border-emerald-800 text-emerald-400"}`}
                  >
                    {j}J
                  </button>
                ))}
              </div>
            </div>
          )}

          {verhandlung.richtung === "kaufen" && (() => {
            const jahresgehalt = berechneSpielerlohn(verhandlung.spieler, managerDivId);
            return (
              <div className="text-[11px] text-emerald-500 mb-3 border-t border-emerald-900 pt-2">
                Erwartetes Gehalt bei dir: <span className="text-white font-semibold">{jahresgehalt.toLocaleString("de-CH")} €/Jahr</span>
                <span className="text-emerald-600"> ({Math.round(jahresgehalt / 12).toLocaleString("de-CH")} €/Monat)</span> — zusätzlich zur Ablöse, läuft ab Vertragsbeginn als laufende Kaderkosten.
              </div>
            );
          })()}

          {verhandlung.nachricht?.art === "erfolg" && (
            <div className="text-xs text-emerald-300 mb-2">
              ✓ {verhandlung.richtung === "kaufen" ? "Transfer perfekt! Spieler wechselt für" : "Verkauft für"} {verhandlung.nachricht.summe.toLocaleString("de-CH")} €.
              {verhandlung.richtung === "verkaufen" && " Kein automatischer Ersatz — bei Bedarf selbst nachrüsten."}
            </div>
          )}
          {verhandlung.nachricht?.art === "ablehnung" && transferGesperrt?.[verhandlung.spieler.id] && (
            <div className="text-xs text-red-400 mb-2 flex items-center gap-1.5">
              <Lock size={12} /> {verhandlung.richtung === "kaufen" ? "Angebot abgelehnt." : "Kein Käufer zu dieser Forderung."} {verhandlung.richtung === "kaufen" ? "Der Verein" : "Der Käufer"} will für den Rest dieses Transferfensters nicht mehr über diesen Spieler verhandeln.
            </div>
          )}
          {verhandlung.nachricht?.art === "ablehnung" && !transferGesperrt?.[verhandlung.spieler.id] && (
            <div className="text-xs text-red-400 mb-2">
              ✗ {verhandlung.richtung === "kaufen" ? "Angebot abgelehnt." : "Kein Käufer zu dieser Forderung."} Ein weiterer Versuch ist möglich — versuch's mit einer anderen Quote.
            </div>
          )}

          {verhandlung.nachricht?.art !== "erfolg" && !transferGesperrt?.[verhandlung.spieler.id] && (
            <button
              onClick={angebotAbgeben}
              disabled={verhandlung.richtung === "kaufen" && Math.round((verhandlung.wert * verhandlung.quote) / 100) > budget}
              className="w-full bg-amber-500 hover:bg-amber-400 disabled:bg-emerald-900 disabled:text-emerald-700 text-[#0b1f14] font-bold text-xs rounded py-2"
            >
              {verhandlung.richtung === "kaufen" ? "Angebot abgeben" : "Verkaufen anbieten"}
            </button>
          )}
        </div>
      )}
      {spielerFuerDetail && (
        <SpielerDetailModal
          spieler={spielerFuerDetail}
          managerDivId={managerDivId}
          season={season}
          trophaeen={trophaeen}
          teamName={managerTeam}
          portrait={spielerPortraitFuer(spielerFuerDetail.id)}
          onClose={() => setSpielerFuerDetail(null)}
        />
      )}
    </div>
  );
}

function TrainingslagerView({ verfuegbar, phase, budget, campBonus, onBook }) {
  const [ausgewaehlt, setAusgewaehlt] = useState(null);

  if (!verfuegbar) {
    return (
      <div className="text-center py-8">
        <Tent className="mx-auto text-emerald-700 mb-3" size={28} />
        {campBonus ? (
          <>
            <div className="text-emerald-300 font-semibold text-sm">Formbonus aktiv: {campBonus.name}</div>
            <div className="text-emerald-600 text-xs mt-1">+{campBonus.wert.toFixed(1)} Teamstärke · noch {campBonus.verbleibend} Spieltage</div>
          </>
        ) : (
          <>
            <div className="text-emerald-300 font-semibold text-sm">Kein Trainingslager möglich</div>
            <div className="text-emerald-600 text-xs mt-1">Buchbar nur während eines offenen Transferfensters (Sommer oder Winter), in der jeweils passenden Saisonhälfte. Nächste Gelegenheit: mit dem nächsten Transferfenster.</div>
          </>
        )}
      </div>
    );
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-3 text-xs">
        <span className="text-amber-400 font-semibold">Trainingslager vor der {phase === "vorrunde" ? "Vorrunde" : "Rückrunde"}</span>
        <span className="text-emerald-500">Kontostand: <span className="text-amber-400 font-semibold">{budget.toLocaleString("de-CH")} €</span></span>
      </div>
      {campBonus && (
        <div className="text-[11px] text-emerald-500 mb-2">Aktueller Formbonus läuft noch {campBonus.verbleibend} Spieltage — ein neues Lager überschreibt ihn.</div>
      )}
      <div className="space-y-2">
        {TRAININGSLAGER_OPTIONEN.map(opt => {
          const bezahlbar = opt.kosten <= budget;
          const gewaehlt = ausgewaehlt === opt.id;
          return (
            <button
              key={opt.id}
              type="button"
              disabled={!bezahlbar}
              onClick={() => setAusgewaehlt(opt.id)}
              className={`w-full text-left rounded border px-4 py-3 transition-colors ${gewaehlt ? "border-amber-400" : "border-emerald-800 hover:border-emerald-600"} ${!bezahlbar ? "opacity-40 cursor-not-allowed" : ""}`}
              style={{ backgroundColor: gewaehlt ? "rgba(251,191,36,0.08)" : "#0b1f14" }}
            >
              <div className="flex items-center justify-between">
                <div>
                  <div className={`font-semibold text-sm ${gewaehlt ? "text-amber-300" : "text-emerald-100"}`}>{opt.name}</div>
                  <div className="text-[11px] text-emerald-500 mt-0.5">{opt.beschreibung}</div>
                  <div className="text-[11px] text-emerald-600 mt-0.5">+{opt.bonus} Teamstärke für {opt.dauer} Spieltage</div>
                </div>
                <div className="text-amber-400 text-sm shrink-0 pl-3">{opt.kosten.toLocaleString("de-CH")} €</div>
              </div>
            </button>
          );
        })}
      </div>
      <button
        disabled={!ausgewaehlt}
        onClick={() => onBook(TRAININGSLAGER_OPTIONEN.find(o => o.id === ausgewaehlt))}
        className="w-full mt-3 bg-amber-500 hover:bg-amber-400 disabled:bg-emerald-900 disabled:text-emerald-700 disabled:cursor-not-allowed text-[#0b1f14] font-bold text-sm rounded py-2.5 flex items-center justify-center gap-2"
      >
        <Tent size={15} /> Trainingslager buchen
      </button>
    </div>
  );
}

function SponsorScreen({ managerDivId, season, saisonLabel, onConfirm }) {
  const [kandidaten] = useState(() => generateSponsorKandidaten(managerDivId, season, Math.floor(Math.random() * 1000000)));
  const [ausgewaehlt, setAusgewaehlt] = useState(null);

  return (
    <div className="min-h-screen text-emerald-50 flex items-center justify-center p-4 font-mono" style={{background: "linear-gradient(135deg, #050e08 0%, #0b1f14 35%, #123322 65%, #08160e 100%)"}}>
      <div className="w-full max-w-2xl border border-emerald-700/50 rounded-lg shadow-2xl overflow-hidden" style={{backgroundColor: "#0e2818"}}>
        <div className="bg-emerald-900/60 border-b border-emerald-700/50 px-6 py-5 text-center">
          <div className="flex items-center justify-center gap-2 text-amber-400 mb-1">
            <Shirt size={22} />
            <span className="text-xs tracking-[0.3em] uppercase">Sponsoring</span>
          </div>
          <h1 className="text-xl sm:text-2xl font-bold tracking-wide text-white">Trikotsponsor — {saisonLabel}</h1>
          <p className="text-emerald-400/70 text-xs mt-1">Das Trikot vorne ist eure wertvollste Werbefläche. Wähle einen Partner.</p>
        </div>

        <div className="p-5 space-y-2">
          {kandidaten.map(k => {
            const gewaehlt = ausgewaehlt === k.id;
            return (
              <button
                key={k.id}
                type="button"
                onClick={() => setAusgewaehlt(k.id)}
                className={`w-full text-left rounded border px-4 py-3 transition-colors ${gewaehlt ? "border-amber-400" : "border-emerald-800 hover:border-emerald-600"}`}
                style={{ backgroundColor: gewaehlt ? "rgba(251,191,36,0.08)" : "#0b1f14" }}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <div className={`font-semibold text-sm ${gewaehlt ? "text-amber-300" : "text-emerald-100"}`}>{k.firma}</div>
                    <div className="text-[11px] text-emerald-500 mt-0.5">{k.laufzeit} {k.laufzeit === 1 ? "Jahr" : "Jahre"} Laufzeit</div>
                  </div>
                  <div className="text-amber-400 text-sm font-semibold">{k.betragProJahr.toLocaleString("de-CH")} €/Jahr</div>
                </div>
              </button>
            );
          })}

          <button
            disabled={!ausgewaehlt}
            onClick={() => onConfirm(kandidaten.find(k => k.id === ausgewaehlt))}
            className="w-full mt-2 bg-amber-500 hover:bg-amber-400 disabled:bg-emerald-900 disabled:text-emerald-700 disabled:cursor-not-allowed text-[#0b1f14] font-bold rounded py-3 flex items-center justify-center gap-2"
          >
            <Shirt size={18} /> Sponsorenvertrag unterzeichnen
          </button>
        </div>
      </div>
    </div>
  );
}

function TrainerZieleScreen({ trainerName, managerDivId, season, saisonLabel, onConfirm }) {
  const [kandidaten] = useState(() => generiereTrainerZielKandidaten(managerDivId, season, 1));
  const [ausgewaehlt, setAusgewaehlt] = useState([]);

  const toggle = (id) => {
    setAusgewaehlt(prev => {
      if (prev.includes(id)) return prev.filter(x => x !== id);
      if (prev.length >= 2) return prev;
      return [...prev, id];
    });
  };

  return (
    <div className="min-h-screen text-emerald-50 flex items-center justify-center p-4 font-mono" style={{background: "linear-gradient(135deg, #050e08 0%, #0b1f14 35%, #123322 65%, #08160e 100%)"}}>
      <div className="w-full max-w-xl border border-emerald-700/50 rounded-lg shadow-2xl overflow-hidden" style={{backgroundColor: "#0e2818"}}>
        <div className="bg-emerald-900/60 border-b border-emerald-700/50 px-6 py-5 text-center">
          <div className="flex items-center justify-center gap-2 text-amber-400 mb-1">
            <UserCog size={22} />
            <span className="text-xs tracking-[0.3em] uppercase">Vorgaben an den Trainer</span>
          </div>
          <h1 className="text-xl sm:text-2xl font-bold tracking-wide text-white">Fussballerische Ziele — {saisonLabel}</h1>
          <p className="text-emerald-400/70 text-xs mt-1">Gib {trainerName} genau 2 fussballerische Vorgaben mit — inklusive Prämie bei Erfüllung. Das motiviert ihn zusätzlich und hebt seine Zufriedenheit.</p>
        </div>

        <div className="p-5 space-y-2">
          {kandidaten.map(z => {
            const gewaehlt = ausgewaehlt.includes(z.id);
            return (
              <button
                key={z.id}
                type="button"
                onClick={() => toggle(z.id)}
                className={`w-full text-left rounded border px-4 py-3 transition-colors ${gewaehlt ? "border-amber-400" : "border-emerald-800 hover:border-emerald-600"}`}
                style={{ backgroundColor: gewaehlt ? "rgba(251,191,36,0.08)" : "#0b1f14" }}
              >
                <div className={`text-sm ${gewaehlt ? "text-amber-300 font-semibold" : "text-emerald-100"}`}>{z.text}</div>
                <div className="text-[11px] text-emerald-500 mt-0.5">Prämie bei Erfüllung: <span className="text-amber-400">{z.provision.toLocaleString("de-CH")} €</span></div>
              </button>
            );
          })}

          <button
            disabled={ausgewaehlt.length !== 2}
            onClick={() => onConfirm(kandidaten.filter(z => ausgewaehlt.includes(z.id)))}
            className="w-full mt-2 bg-amber-500 hover:bg-amber-400 disabled:bg-emerald-900 disabled:text-emerald-700 disabled:cursor-not-allowed text-[#0b1f14] font-bold rounded py-3 flex items-center justify-center gap-2"
          >
            <UserCog size={18} /> Vorgaben mitteilen ({ausgewaehlt.length}/2)
          </button>
        </div>
      </div>
    </div>
  );
}

function ZieleScreen({ managerDivId, season, saisonLabel, onConfirm, geradeAufgestiegen = false, hatJunior = true }) {
  const [ziele] = useState(() => generiereVorstandsZiele(managerDivId, season, 0, geradeAufgestiegen, hatJunior));

  return (
    <div className="min-h-screen text-emerald-50 flex items-center justify-center p-4 font-mono" style={{background: "linear-gradient(135deg, #050e08 0%, #0b1f14 35%, #123322 65%, #08160e 100%)"}}>
      <div className="w-full max-w-xl border border-emerald-700/50 rounded-lg shadow-2xl overflow-hidden" style={{backgroundColor: "#0e2818"}}>
        <div className="bg-emerald-900/60 border-b border-emerald-700/50 px-6 py-5 text-center">
          <div className="flex items-center justify-center gap-2 text-amber-400 mb-1">
            <ClipboardList size={22} />
            <span className="text-xs tracking-[0.3em] uppercase">Vorstandssitzung</span>
          </div>
          <h1 className="text-xl sm:text-2xl font-bold tracking-wide text-white">Saisonvorgaben — {saisonLabel}</h1>
          <p className="text-emerald-400/70 text-xs mt-1">Der Vorstand hat die Ziele für diese Saison festgelegt — nicht verhandelbar. Am Saisonende entscheidet die Vereinsversammlung anhand deren Erfüllung über deine Wiederwahl. Für jedes erreichte Ziel gibt's eine Erfolgsprämie.</p>
        </div>

        <div className="p-5 space-y-2">
          {ziele.map(z => (
            <div key={z.id} className="rounded border border-amber-400/40 px-4 py-3" style={{ backgroundColor: "rgba(251,191,36,0.06)" }}>
              <div className="text-sm text-amber-200 font-semibold">{z.text}</div>
              <div className="text-[11px] text-emerald-500 mt-1">Erfolgsprämie bei Erreichen: <span className="text-amber-400 font-semibold">{z.provision.toLocaleString("de-CH")} €</span></div>
            </div>
          ))}

          <button
            onClick={() => onConfirm(ziele)}
            className="w-full mt-2 bg-amber-500 hover:bg-amber-400 text-[#0b1f14] font-bold rounded py-3 flex items-center justify-center gap-2"
          >
            <ClipboardList size={18} /> Zur Kenntnis genommen
          </button>
        </div>
      </div>
    </div>
  );
}

function KarriereEndeScreen({ karriereEnde, onNeueKarriere }) {
  const istInsolvenz = karriereEnde.grund === "insolvenz";
  return (
    <div className="min-h-screen text-emerald-50 flex items-center justify-center p-4 font-mono" style={{background: "linear-gradient(135deg, #050e08 0%, #0b1f14 35%, #123322 65%, #08160e 100%)"}}>
      <div className="w-full max-w-md border border-red-500/50 rounded-lg shadow-2xl overflow-hidden" style={{backgroundColor: "#0e2818"}}>
        <div className="bg-red-900/30 border-b border-red-700/50 px-6 py-6 text-center">
          <XCircle className="mx-auto text-red-400 mb-2" size={32} />
          <h1 className="text-xl font-bold text-red-300">{istInsolvenz ? "Entlassen" : "Abgewählt"}</h1>
          <p className="text-emerald-400 text-xs mt-2">
            {istInsolvenz
              ? `Die Vereinsversammlung von ${karriereEnde.team} hat dich fristlos entlassen — der Verein war trotz Dispo und einer letzten Verkaufsaktion des Vorstands erneut zahlungsunfähig. Die Vereinsführung sah dabei keinen anderen Ausweg mehr.`
              : `Die Vereinsversammlung von ${karriereEnde.team} hat dir das Vertrauen entzogen — die zu wenig erfüllten Ziele der Saison ${karriereEnde.season}/${(karriereEnde.season + 1) % 100} waren ausschlaggebend.`}
          </p>
        </div>
        <div className="p-6 space-y-3">
          <div className="text-xs uppercase tracking-wider text-emerald-400/80">Deine Bilanz</div>
          <div className="text-sm text-emerald-200">{karriereEnde.anzahlSaisons} Saison{karriereEnde.anzahlSaisons === 1 ? "" : "en"} im Amt</div>
          <div className="text-sm text-emerald-200">{karriereEnde.anzahlTrophaeen} Trophäe{karriereEnde.anzahlTrophaeen === 1 ? "" : "n"} gewonnen</div>
          <button
            onClick={onNeueKarriere}
            className="w-full mt-3 bg-amber-500 hover:bg-amber-400 text-[#0b1f14] font-bold rounded py-3"
          >
            Neue Karriere starten
          </button>
        </div>
      </div>
    </div>
  );
}

