// Eigenständig gestaltete Europapokal-Icons — an die charakteristische Form mit den grossen
// geschwungenen Henkeln angelehnt, aber ohne reale Logos/Schriftzüge (markenrechtlich geschützt).
// Je Wettbewerb eigene Farbgebung: CL silber/gold, EL silber/orange, ECL silber/grün.
function EuropapokalIcon({ wettbewerb = "CL", size = 40 }) {
  const akzent = { CL: "#d4af37", EL: "#f97316", ECL: "#34d399" }[wettbewerb] || "#d4af37";
  const gradId = `euroGrad-${wettbewerb}`;
  return (
    <svg width={size} height={size} viewBox="0 0 100 130" fill="none">
      <defs>
        <linearGradient id={gradId} x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#f4f4f2" />
          <stop offset="45%" stopColor="#c9cdd1" />
          <stop offset="100%" stopColor="#8b9096" />
        </linearGradient>
      </defs>
      {/* Grosse geschwungene Henkel */}
      <path d="M32 28 Q4 30 6 62 Q8 88 32 92" stroke={akzent} strokeWidth="5" fill="none" strokeLinecap="round" />
      <path d="M68 28 Q96 30 94 62 Q92 88 68 92" stroke={akzent} strokeWidth="5" fill="none" strokeLinecap="round" />
      <path d="M35 28 Q12 31 14 60 Q16 82 35 86" stroke={`url(#${gradId})`} strokeWidth="2" fill="none" strokeLinecap="round" />
      <path d="M65 28 Q88 31 86 60 Q84 82 65 86" stroke={`url(#${gradId})`} strokeWidth="2" fill="none" strokeLinecap="round" />
      {/* Pokalkörper */}
      <ellipse cx="50" cy="24" rx="19" ry="8" fill={`url(#${gradId})`} stroke="#6b7075" strokeWidth="1.2" />
      <path d="M31 26 Q28 55 40 78 Q34 84 34 92 Q34 102 50 105 Q66 102 66 92 Q66 84 60 78 Q72 55 69 26 Z" fill={`url(#${gradId})`} stroke="#6b7075" strokeWidth="1.2" />
      <path d="M40 78 Q50 84 60 78" stroke="#6b7075" strokeWidth="1" fill="none" />
      {/* Sockel */}
      <path d="M50 105 Q50 112 50 116" stroke="#8b9096" strokeWidth="6" strokeLinecap="round" fill="none" />
      <rect x="28" y="116" width="44" height="7" rx="2" fill="#4a4e52" />
      <rect x="22" y="123" width="56" height="5" rx="2" fill={akzent} opacity="0.85" />
    </svg>
  );
}

